function fixHeading(){const page=document.getElementById('artist-area');if(!page||page.querySelector('h1')?.textContent!==a.name)return;for(const h of page.querySelectorAll('h2'))if(h.textContent==='Пять работ: рассмотри и сравни')h.textContent='Три работы из одного алтаря: рассмотри и сравни';}
