const batch={};
for(const [id,name,latin,life,tag,bio,technique,innovation,features,caution,keys,looks,status] of rows){const selected=keys.map((k,i)=>{if(!works[k])throw Error('Missing work '+k);return {...works[k],look:looks[i]};});const sources=[...selected.map(w=>[w.museum+': '+w.originalTitle,w.source]),...selected.filter(w=>w.imageSource).map(w=>['Репродукция и сведения о правах',w.imageSource]),...(refs[id]||[])];batch[id]={name,latin,life,tag,aliases:[name,latin],bio:[bio],technique:[technique],innovation,features:features.split('|'),caution,sources,works:selected,editorialStatus:status==='illustrated'?'illustrated':status==='historical'?'text_only_historical_attribution':status==='documentation'?'text_only_image_verification_pending':'text_only_permission_pending'};}
