/* artists-batch-24.js */
(()=>{'use strict';
const rows=[
['yi_nyeong','И Нён','Yi Nyeong (이녕)','работал в первой половине XII века','Корё · история пейзажной живописи','И Нён был художником при корейском дворе. В 1124 он сопровождал посольство в Северную Сун и, по письменным источникам, написал Реку Йесон по просьбе императора Хуэйцзуна.','Река Йесон и Южные ворота храма Чхонсу известны по литературным свидетельствам, но не сохранились. Конкретную кисть и палитру по ним проверить нельзя.','Источники указывают на изображение местных корейских видов уже в XII веке и на обмен с живописью Северной Сун.','Дворцовый художник|Посольство 1124|Местный пейзаж|Письменное свидетельство|Утраченные произведения','Это намеренно историческая страница, не обычная задача поиска фото. Не подставляем анонимную картину Корё как авторский образец И Нёна. Отнесение ворот к архитектурному письму кехва — реконструкция исследователей.',[],[],'historical'],
['yi_jehyeon','И Джехён','Yi Je-hyeon (이제현)','1287–1367 по AKS','Корё · литератор и культурный обмен с Юань','И Джехён — учёный, литератор и государственный деятель, связанный с культурными контактами Корё и Юань. Его имя присутствует в исходном учебном списке, но это не основание приписывать ему конкретную живопись.','Знаменитый портрет создан китайским художником Чэнь Цзяньжу в 1319; надписи принадлежат Тан Бинлуну и самому И Джехёну. Современная музейная запись сохраняет оговорку Presumably Chen Jianru.','Портрет, заказ, текст и модель — разные роли. Памятник важен для истории обмена художественными и интеллектуальными практиками.','Модель не автор|Отдельный автор надписи|Заказчик и художник|Обмен Корё и Юань|Проверка атрибуции','Портрет не помещён в авторский список works: иначе интерфейс мог бы назвать И Джехёна его художником. Подлинность и возможное позднее воспроизведение обсуждаются в исследовании 2024. Даты жизни взяты у AKS, не из опечатки 1376 в английском музейном тексте.',[],[],'context'],
['king_gongmin','Ван Конмин','King Gongmin of Goryeo (공민왕)','1330–1374; правил 1351–1374','Корё · государь, искусство и атрибуция','Конмин известен как государь, проявлявший интерес к живописи, каллиграфии и музыке. Но традиционные произведения с его именем требуют отдельной проверки авторства.','Исследование 2015 сопоставляет овец и фрагменты охотничьей композиции из разных собраний. Связь фрагментов с одним свитком — вывод этого исследования, не авторская подпись.','История коллекционирования и традиционного наименования не равна установлению руки художника.','Государь и художник|Традиционное приписывание|Сравнение фрагментов|Разные собрания|История коллекционирования','Пока справка без авторской репродукции. Картину с овцами, связанную с Конмином по традиции, не выдаём за бесспорно подписную. Оттиск каллиграфии из другого музейного памятника не подтверждает авторство живописи.',[],[],'historical'],
['an_gyeon','Ан Гён','An Gyeon (안견)','работал ок. 1440–1470','Чосон · придворная пейзажная живопись','Ан Гён написал Сонное путешествие в страну цветущих персиков в 1447 по заказу принца Анпхёна. Принц описал сон и собрал поэтические отклики современников.','Тушь и лёгкий цвет на шёлке. Динамичные скальные формы и световая атмосфера перерабатывают северосунскую традицию Го Си. Утопическая долина расположена в правой части.','Образ объединяет литературную модель Тао Юаньмина, переживание заказчика и работу художника; это не копия конкретного корейского вида.','Горизонтальный свиток|Скальные массы|Туман и свет|Утопическая долина|Поэзия и каллиграфия','Оригинал хранится в Центральной библиотеке университета Тэнри в Японии. Цифровая экспозиция в Сеуле — не перемещение оригинала. Другой заказ Анпхёна 1442 не сохранился.',['new:an'],['Сравни более земной левый пейзаж с замкнутой утопической областью справа. Надписи разных авторов относятся к большему ансамблю; репродукция показывает живописную часть, не все тексты.'],'illustrated'],
['jeong_seon','Чон Сон','Jeong Seon (정선)','1676–1759','Чосон · пейзаж узнаваемых мест','Чон Сон — мастер пейзажа настоящих видов, jingyeong sansuhwa. Гора Инван после дождя написана в 1751, когда художник жил у подножия знакомой ему горы.','Тушь на бумаге. Контраст тёмных скальных масс с туманными промежутками делает вид одновременно узнаваемым и художественно организованным.','Конкретное место становится основой самостоятельного пейзажного языка. Настоящий вид не означает фотографически точную фиксацию каждой детали.','Узнаваемая гора|Тёмные скальные массы|Светлые туманные зоны|Состояние после дождя|Местный опыт','После дара семьи Ли в 2021 работа поступила в Национальный музей Кореи. Старые подписи Commons с Ho-Am описывают прежнюю историю собрания. Не датируем её всей продолжительностью эпохи Чосон.',['new:jeong'],['Сопоставь насыщенные тушью скалы с белыми промежутками и мелкими строениями. По музейному источнику вид связан с повседневно знакомым окружением художника.'],'illustrated'],
['kim_hongdo','Ким Хондо','Kim Hong-do (김홍도)','1745 — после 1806 по музею','Чосон · жанровая живопись','Ким Хондо, известный под именем Танвон, создал знаменитый альбом повседневных сцен. Борьба — один лист этого альбома, не вся серия.','Простые, экономные мазки передают выражения лиц и накал состязания. Зрители образуют две группы, связанные обувью справа и продавцом сладостей слева.','Повседневное событие получает композиционную ясность и эмоциональную насыщенность без подробной декорации окружающего места.','Круг зрителей|Два борца|Продавец сладостей|Обувь справа|Экономная кисть','Музей даёт годы жизни 1745 — после 1806, не бесспорный 1814 из старых сводок. Около 1780 для листа — оценка Commons; точной даты текущая музейная запись не указывает.',['new:kim'],['Проследи две дуги зрителей. Продавец сладостей смотрит иначе, чем публика, а обувь справа связывает разрыв между группами.'],'illustrated']
];
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
const C='https://commons.wikimedia.org/wiki/';
const media=[
['an','Сонное путешествие в страну цветущих персиков','Dream Journey to the Peach Blossom Land','1447','Центральная библиотека университета Тэнри, Япония','Тушь и лёгкий цвет на шёлке; горизонтальный свиток','https://www.metmuseum.org/essays/mountain-and-water-korean-landscape-painting-1400-1800','Dream Journey to the Peach Blossom Land.jpg','Public domain согласно World History Encyclopedia; см. страницу репродукции'],
['jeong','Гора Инван после дождя','Clearing after Rain on Mount Inwang','1751','Национальный музей Кореи, Сеул','Тушь на бумаге; 79,2 × 138,2 см','https://www.museum.go.kr/site/eng/exhiSpecialTheme/view/current?exhiSpThemId=604620','Inwangjesaekdo.jpg','Public domain / PD-Art по странице файла; не CC0'],
['kim','Корейская борьба ссирым — лист альбома','Korean Traditional Wrestling','Чосон, XVIII век; ок. 1780 по Commons','Национальный музей Кореи, Сеул','Тушь и лёгкий цвет на бумаге; 26,9 × 22,2 см','https://www.museum.go.kr/ENG/contents/E0403000000.do?searchId=represent&schM=view&relicId=551','Danwon-Ssireum.jpg','Public domain согласно странице репродукции; не CC0']
];
const works=new Map(media.map(([id,title,originalTitle,date,museum,medium,source,file,license])=>['new:'+id,{key:'guide24:'+id,title,originalTitle,date,museum,medium,source,image:C+'Special:FilePath/'+encodeURIComponent(file)+'?width=960',zoom:C+'Special:FilePath/'+encodeURIComponent(file)+'?width=2048',imageSource:C+'File:'+encodeURIComponent(file),license}]));
const refs={yi_nyeong:[['AKS: Река Йесон, описание утраченной картины','https://encykorea.aks.ac.kr/Article/E0037958'],['AKS: Южные ворота Чхонсу, свидетельства и реконструкция','https://encykorea.aks.ac.kr/Article/E0055931']],yi_jehyeon:[['AKS: биография учёного и литератора','https://encykorea.aks.ac.kr/Article/E0045877'],['AKS: художник, модель, заказчик и надписи','https://encykorea.aks.ac.kr/Article/E0046803'],['Национальный музей Кореи: портрет и Presumably Chen Jianru','https://www.museum.go.kr/ENG/contents/E0403000000.do?searchId=represent&schM=view&relicId=1260'],['Korea Journal 2024: исследование портрета и вопрос копии','https://accesson.kr/kj/assets/pdf/43294/journal-64-2-17.pdf']],king_gongmin:[['Исследование 2015: работы, предположительно связанные с Конмином','https://www.earticle.net/Article/A251874'],['Музейный памятник: предположительно каллиграфия Конмина, не живопись','https://www.museum.go.kr/ENG/contents/E0403000000.do?schM=relic_represent_view&relicId=497']],an_gyeon:[['Национальный музей Кореи: заказ Анпхёна и сохранившийся шедевр','https://www.museum.go.kr/ENG/contents/E0401000000.do?schM=view&relicRecommendId=519671'],['Korea.net: оригинал в Тэнри и цифровая версия','https://www.korea.net/NewsFocus/Culture/view?articleId=132671'],['World History Encyclopedia: изображение помечено Public Domain','https://www.worldhistory.org/image/13344/mongyudowondo-dream-journey-to-the-peach-blossom-l/']],jeong_seon:[['Национальный музей Кореи: дар и история произведения','https://www.museum.go.kr/MUSEUM/contents/M0701040000.do?schM=view&catCustomType=post&catId=93&arcId=17706&cp=114&sv='],['Страница репродукции: PD-Art и прежнее собрание','https://en.wikipedia.org/wiki/File:Inwangjesaekdo.jpg']],kim_hongdo:[['Музей: альбом и годы жизни','https://www.museum.go.kr/ENG/contents/E0202010000.do?schM=view&menuId=current&exhiSpThemId=542310&listType=gallery']]};
const batch={};
for(const [id,name,latin,life,tag,bio,technique,innovation,features,caution,keys,looks,status] of rows){const selected=keys.map((key,i)=>{if(!works.has(key))throw Error('Missing work '+key);return {...works.get(key),look:looks[i]};});const sources=[...selected.map(w=>[w.museum+': '+w.originalTitle,w.source]),...selected.map(w=>['Репродукция и сведения о правах',w.imageSource]),...(refs[id]||[])];batch[id]={name,latin,life,tag,aliases:[name,latin],bio:[bio],technique:[technique],innovation,features:features.split('|'),caution,sources,works:selected,editorialStatus:status==='illustrated'?'illustrated':status==='context'?'historical_context_not_verified_painter':'text_only_historical_attribution',personRole:status==='context'?'scholar_and_portrait_subject':'artist_or_historical_attribution'};}
batch.king_gongmin.aliases.push('ван Конмин','Король Конмин','Gongmin');batch.kim_hongdo.aliases.push('Kim Hongdo','Ким Хон До','Танвон');batch.yi_jehyeon.aliases.push('Yi Jehyeon');
window.registerPaintingArtists(batch);
const byName=new Map(Object.values(batch).map(a=>[a.name,a])),host=document.getElementById('view');
function fixHeading(){const page=document.getElementById('artist-area'),a=byName.get(page?.querySelector('h1')?.textContent);if(!a)return;for(const h of page.querySelectorAll('h2')){if(h.textContent==='Пять работ: рассмотри и сравни')h.textContent=a.works.length?'Одна работа: рассмотри внимательно':'Исторический контекст и атрибуция: смотри источники';if(!a.works.length&&h.textContent==='Пять признаков для внимательного взгляда')h.textContent='Пять ориентиров для проверки';if(a.personRole==='scholar_and_portrait_subject'&&h.textContent==='Краткая биография')h.textContent='Литератор, модель портрета и культурный контекст';}}
if(host){new MutationObserver(fixHeading).observe(host,{childList:true,subtree:true});fixHeading();}
})();

