(()=>{'use strict';
const C='https://commons.wikimedia.org/wiki/',B={};
const met=(id,title,orig,date,medium,img,look,acc)=>({key:'met:'+id,title,originalTitle:orig,date,museum:'Метрополитен-музей, Нью-Йорк',medium,source:'https://www.metmuseum.org/art/collection/search/'+id,image:'https://images.metmuseum.org/CRDImages/ep/web-large/'+img,zoom:'https://images.metmuseum.org/CRDImages/ep/original/'+img,accessionNumber:acc,license:'Public domain / Met Open Access (CC0)',look});
function add(id,name,latin,life,tag,bio,technique,innovation,features,caution,sources,works,status){B[id]={name,latin,life,tag,aliases:[name,latin],bio,technique,innovation,features,caution,sources,works,editorialStatus:status};}
add('michelangelo','Микеланджело Буонарроти','Michelangelo Buonarroti','1475–1564','Италия · Высокое Возрождение',
['Микеланджело известен прежде всего как скульптор, и станковых картин у него сохранилось очень мало. Национальная галерея называет «Положение во гроб» одной из трёх известных живописных работ на доске; две другие — «Мадонна Манчестера» и «Тондо Дони» (Уффици).'],
['«Положение во гроб» написано маслом по дереву и осталось незаконченным: во многих местах видна лишь светло-коричневая подготовка. Музей отмечает также, что он соскоблил тёмную краску в скалах, оставив призрачный силуэт двух фигур у входа в гробницу.'],
'Незаконченность делает видимым порядок работы: Микеланджело доводил участки до конца по очереди, как во фреске или темпере, а не набрасывал сразу всю картину.',
['Одна из трёх известных досок','Незаконченная панель с подготовкой','Резерв: светло-коричневая подготовка','Соскобленные скалы и силуэты','Пустое место для коленопреклонённой Марии'],
'Это одна ранняя незаконченная картина, а не вся живопись Микеланджело: фрески Сикстинской капеллы здесь не разбираются. Алтарь, вероятно, заказан в 1500 году для церкви Сант-Агостино в Риме, но Микеланджело вернулся во Флоренцию в 1501 году, и работа осталась неоконченной. Репродукцию на странице не подключаю: права на конкретный файл не проверены.',
[['Национальная галерея, Лондон: Положение во гроб (NG790)','https://www.nationalgallery.org.uk/paintings/michelangelo-the-entombment-or-christ-being-carried-to-his-tomb']],[],'text_only_image_rights_pending');
add('klimt','Густав Климт','Gustav Klimt','1862–1918','Австрия · венский модерн',
['Климт родился в Баумгартене близ Вены в 1862 году и умер в Вене в 1918-м. Страница посвящена одному большому портрету позднего периода.','Банкир и промышленник Отто Примавези, один из финансовых покровителей Венских мастерских, заказал портрет дочери в 1912 году. Климт написал его в венской студии, где в 1914 году сделал и портрет матери Мэды, актрисы Евгении Примавези.'],
['Масло на холсте, 149,9 × 110,5 см. Музей отмечает уверенность и осанку девятилетней девочки, которая выглядит гораздо старше своих лет.'],
'Портрет ребёнка в полный рост и в большом формате показывает Климта вне «золотого периода»: упор на фигуру, позу и взгляд заказчика.',
['Полный рост, портретный формат','Уверенная осанка и взгляд','Позднее датирование 1912–13','Заказ мецената Венских мастерских','Парный семейный заказ (мать, 1914)'],
'Это один холст, а не обзор творчества: «Поцелуй» и золотой период здесь не разбираются. Название в Метрополитен-музее включает годы жизни модели (1903–2000).',
[['Метрополитен-музей: Мэда Примавези','https://www.metmuseum.org/art/collection/search/436819']],
[met(436819,'Мэда Примавези (1903–2000)','Mäda Primavesi (1903–2000)','1912–13','Масло на холсте; 149,9 × 110,5 см','DP243354.jpg','Рассмотри осанку и взгляд девочки: музей читает в них уверенность, не по годам взрослую. Затем сравни этот большой формат с парным портретом матери 1914 года, о котором пишет музей.','64.148')],'illustrated');
add('degas','Эдгар Дега','Edgar Degas','1834–1917','Франция · импрессионизм и реализм',
['Дега родился и умер в Париже. Страница показывает две его ранние сцены балетного класса из Метрополитен-музея: музей называет «Урок танца» 1874 года одной из самых амбициозных его картин на тему танца.'],
['«Урок танца» — масло на холсте, 83,5 × 77,2 см. Около двадцати четырёх женщин, балерины и их матери, ждут, пока танцовщица выполняет «аттитюд» перед балетмейстером Жюлем Перро. «Танцевальный класс» около 1870 года — небольшая картина маслом по дереву (19,7 × 27 см).'],
'Музей подчёркивает, что сцена вымышленная: репетиционный зал старой Парижской оперы, сгоревшей незадолго до этого. Дега строит воображаемое событие из наблюдений, а не фиксирует случайный момент.',
['Много фигур в репетиционном зале','Ожидание вместо движения','Афиша «Вильгельм Телль» на стене','Зеркало и разные поворотные позы','Вымышленное место (сгоревшая Опера)'],
'«Урок танца» 1874 года в Метрополитен-музее — вариант картины из Музея Орсе: не путай их. Афиша напоминает о певце Жане-Батисте Форе, заказавшем картину; она показывалась на выставке импрессионистов 1876 года.',
[['Метрополитен-музей: Урок танца (1987.47.1)','https://www.metmuseum.org/art/collection/search/438817'],['Метрополитен-музей: Танцевальный класс (29.100.184)','https://www.metmuseum.org/art/collection/search/436141']],
[met(438817,'Урок танца','The Dance Class','1874','Масло на холсте; 83,5 × 77,2 см','DP-20101-001.jpg','Найди старого балетмейстера Перро с тростью и танцовщицу, показывающую позу. Затем разыщи афишу «Вильгельма Телля» у зеркала: музей объясняет её как дань заказчику.','1987.47.1'),
met(436141,'Танцевальный класс','The Dancing Class','около 1870','Масло на дереве; 19,7 × 27 см','DP-25445-001.jpg','Это, по музею, первая картина Дега на тему танцевального класса. Сравни её скромный масштаб с большим «Уроком танца» 1874 года.','29.100.184')],'illustrated');
add('manet','Эдуар Мане','Edouard Manet','1832–1883','Франция · реализм и предимпрессионизм',
['Мане родился в Париже в 1832 году и умер там же в 1883-м. Первые его работы, попавшие в музей, — «Мальчик со шпагой» и «Молодая дама в 1866 году» (подарок Эрвина Дэвиса Метрополитен-музею в 1889 году).'],
['«Мальчик со шпагой» — масло на холсте, 131,1 × 93,4 см. Пасынок Мане Леон Коэлла-Леенхоф позировал для картины в 1861 году, когда ему было около десяти лет. Мане одел его в костюм XVII века и добавил шпагу как реквизит: дань испанским мастерам, особенно Веласкесу.'],
'Музей подчёркивает связь с испанской традицией: Мане берёт приёмы старых мастеров и применяет их к современной сцене.',
['Фигура на нейтральном фоне','Костюм XVII века','Реквизит (шпага)','Родственная модель (пасынок)','Дань Веласкесу'],
'Это одна ранняя работа, а не вся биография художника; «Олимпия» и другие картины здесь не разбираются. Репродукцию не подключаю: адрес файла не удалось проверить.',
[['Метрополитен-музей: Мальчик со шпагой (89.21.2)','https://www.metmuseum.org/art/collection/search/436948']],[],'text_only_image_rights_pending');
add('munch','Эдвард Мунк','Edvard Munch','1863–1944','Норвегия · символизм и экспрессионизм',
['Мунк родился в Лётене в 1863 году и умер в Экели в 1944-м. По записи Гарвардских музеев, в 1889–1892 годах он работал в Париже и писал виды бульваров; «Рю де Риволи» (1891) создана за два года до «Крика».'],
['«Крик» (1893) — масло, темпера и пастель по картону, около 91 × 73 см. Работа входит в серию «Крик»: версий несколько, и Национальный музей Норвегии хранит именно эту (NG.M.00939).'],
'Олаф Шоу купил картину и в 1910 году сразу передал её в дар музею; она участвовала в большинстве персональных выставок Мунка до 1910 года.',
['Резкие волнистые линии','Красно-оранжевое небо','Фигура на мосту','Искажённая перспектива','Ощущение тревоги, а не пейзажа'],
'Не путай версии «Крика»: литография и другие варианты — отдельные произведения. На Commons файл «The Scream.jpg» помечен как заменяемый более новым; при желании его можно подменить. Мунк умер в 1944 году, поэтому произведение находится в общественном достоянии.',
[['Национальный музей Норвегии: Крик (NG.M.00939)','https://www.nasjonalmuseet.no/en/collection/object/NG.M.00939'],['Гарвардские музеи: Рю де Риволи (1963.153)','https://harvardartmuseums.org/index.php/collections/object/228366']],
[{key:'guide28:munch_scream',title:'Крик',originalTitle:'The Scream',date:'1893',museum:'Национальный музей Норвегии, Осло',medium:'Масло, темпера и пастель по картону',source:'https://www.nasjonalmuseet.no/en/collection/object/NG.M.00939',image:C+'Special:FilePath/'+encodeURIComponent('The Scream.jpg')+'?width=800',zoom:C+'Special:FilePath/'+encodeURIComponent('The Scream.jpg')+'?width=2048',imageSource:C+'File:The_Scream.jpg',accessionNumber:'NG.M.00939',license:'Public domain (автор умер в 1944 году) по странице Commons',look:'Проследи линию перил и неба: они не передают пейзаж, а выражают состояние. Сравни фигуру с двумя силуэтами вдали. Репродукция: Commons, файл «The Scream.jpg»; музей хранит именно эту версию.'}],'illustrated');
add('schiele','Эгон Шиле','Egon Schiele','1890–1918','Австрия · экспрессионизм',
['Шиле родился в 1890 году и умер в 1918-м в Вене. Он ученик и младший современник Климта и участник венского модерна.'],
['На этой странице нет картин: большая часть его работ в американских музеях — рисунки, акварели и гуашь на бумаге, а подтверждённой картины маслом в открытом доступе я не нашёл.'],
'Линия и контур у Шиле важнее объёма; но страница без работ не иллюстрирует это, а только фиксирует пробел.',
['Линия и контур','Работы на бумаге','Связь с Климтом и венским модерном','Венские музеи как основной источник живописи','Умер в 28 лет'],
'Страница без репродукций: выбрать одну открытую картину предстоит позже, из венских коллекций или с Commons. Данные о числе работ взяты из стороннего каталога и требуют проверки.',
[['Каталог собраний (сторонний): Egon Schiele в музеях','https://findartinfo.com/artist/egon-schiele/11EABC0B79FA08C0AD5FC4B301B9DA2D/museums']],[],'text_only_no_open_painting_found');
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
B.michelangelo.aliases.push('Микеланджело','Michelangelo');B.klimt.aliases.push('Климт','Klimt');B.degas.aliases.push('Дега','Degas');B.manet.aliases.push('Мане','Manet');B.munch.aliases.push('Мунк','Munch');B.schiele.aliases.push('Шиле','Schiele');
const byName=new Map(Object.values(B).map(a=>[a.name,a])),host=document.getElementById('view');
function fixHeading(){const page=document.getElementById('artist-area'),a=byName.get(page?.querySelector('h1')?.textContent);if(!a)return;for(const h of page.querySelectorAll('h2')){if(h.textContent==='Пять работ: рассмотри и сравни')h.textContent=a.works.length===2?'Две работы: рассмотри и сравни':a.works.length?'Одна работа: рассмотри внимательно':'Репродукция пока не подключена';}}
if(host){new MutationObserver(fixHeading).observe(host,{childList:true,subtree:true});fixHeading();}
})();

;
/* artists-batch-29.js */
(()=>{'use strict';
const B={};
const met=(id,title,orig,date,medium,img,look,acc)=>({key:'met:'+id,title,originalTitle:orig,date,museum:'Метрополитен-музей, Нью-Йорк',medium,source:'https://www.metmuseum.org/art/collection/search/'+id,image:'https://images.metmuseum.org/CRDImages/ep/web-large/'+img,zoom:'https://images.metmuseum.org/CRDImages/ep/original/'+img,accessionNumber:acc,license:'Public domain / Met Open Access (CC0)',look});
function add(id,name,latin,life,tag,bio,technique,innovation,features,caution,sources,works,status){B[id]={name,latin,life,tag,aliases:[name,latin],bio,technique,innovation,features,caution,sources,works,editorialStatus:status};}
add('bruegel','Питер Брейгель Старший','Pieter Bruegel the Elder','около 1525–1569','Нидерланды · северное Возрождение',
['Брейгель родился, вероятно, в Бреде около 1525 года и умер в Брюсселе в 1569-м. Страница посвящена «Жатве» из цикла времён года.','Картина принадлежала циклу из шести досок, который антверпенский купец заказал для столовой своего загородного дома.'],
['Масло по дубу. Размер вместе с добавленными полосами 119 × 162 см, исходная живописная поверхность 116,5 × 159,5 см. Музей описывает жаркий, дремотный день июля или августа: рабочие косят пшеницу, собирают яблоки и отдыхают в тени.'],
'Музей считает «Жатву» одним из первых настоящих пейзажей в западном искусстве: пейзаж здесь уже не фон религиозной сцены, а сам предмет изображения. Согнувшаяся женщина образует треугольник, повторяющий форму пшеницы, и как будто сливается с полем.',
['Пейзаж как главный сюжет','Крестьянский труд и обед в тени','Треугольная форма согнутой женщины','Цикл из шести картин','Сочувственный, но идеализированный взгляд'],
'Это одна доска из шести, а не весь цикл. Музей отмечает, что Брейгель смягчил тяжесть крестьянского труда ради вкуса богатого городского заказчика.',
[['Метрополитен-музей: Жатва (19.164)','https://www.metmuseum.org/art/collection/search/435809']],
[met(435809,'Жатва','The Harvesters','1565','Масло по дубу; 119 × 162 см (с добавленными полосами)','DP119115.jpg','Найди под деревом на переднем плане группу, которая обедает хлебом, и женщину в большой треугольной шляпе с круглым сыром. Затем проследи взглядом, как поле уходит к далёкому морю.','19.164')],'illustrated');
add('hals','Франс Халс','Frans Hals','1582/83–1666','Нидерланды · золотой век',
['Халс родился в Антверпене в 1582 или 1583 году и умер в Харлеме в 1666-м. Метрополитен-музей называет его бытовые сцены 1620–1630-х годов «условными эссе» о нравах: они строятся на типажах с остроумными вариациями.'],
['«Молодой мужчина и женщина в трактире» (1623) — масло на холсте, 105,4 × 79,4 см. Музей отмечает смелую манеру письма, которой Халс научился у фламандской живописи, и румяные щёки, открытые рты и улыбки героев.'],
'Картина показывает беззаботную пару, которая веселится в дверях трактира или борделя: музей называет изображение «весело неосуждающим». Тема связана с притчей о блудном сыне, а над камином в бедной комнате всё же висит пейзаж.',
['Смелый, свободный мазок','Весёлая пара в дверях трактира','Тема блудного сына','Собака и фляга в руках кавалера','Пейзаж над камином'],
'Раньше картину считали портретом знаменосца Питера Рампа, но эту версию отвергли: женщина похожа на героиню другой картины Халса. Отсюда второе название — «Йонкер Рамп и его возлюбленная».',
[['Метрополитен-музей: Молодой мужчина и женщина в трактире (14.40.602)','https://www.metmuseum.org/art/collection/search/436616'],['Метрополитен-музей: Франс Халс (эссе)','https://www.metmuseum.org/en/essays/frans-hals-158283-1666']],
[met(436616,'Молодой мужчина и женщина в трактире («Йонкер Рамп и его возлюбленная»)','Young Man and Woman in an Inn ("Yonker Ramp and His Sweetheart")','1623','Масло на холсте; 105,4 × 79,4 см','DP145899.jpg','Сравни быстрые мазки на лицах с аккуратной одеждой. Найди собаку, фляжку над головой кавалера и открытую дверь, за которой виден смеющийся человек с блюдом.','14.40.602')],'illustrated');
add('canaletto','Каналетто','Canaletto (Giovanni Antonio Canal)','1697–1768','Италия · венецианская ведута',
['Каналетто родился и умер в Венеции. Музей называет его самым знаменитым ведутистом Венеции XVIII века, особенно популярным среди британских путешественников.'],
['«Пьяцца Сан-Марко» (конец 1720-х) — масло на холсте, 68,6 × 112,4 см. «Кампо Сант-Анджело» (1730-е) — 46,7 × 77,5 см.'],
'Каналетто и его заказчики, особенно англичане, мыслили картины сериями: они собирали виды главных площадей и менее известных церквей и дворцов. «Кампо Сант-Анджело» входит в группу из двадцати одинаковых по размеру работ, которые, вероятно, заказал британский консул в Венеции Джозеф Смит (1744–1760).',
['Вид главной площади Венеции','Серии одинакового размера','Британские заказчики','Ведута как «путевой» сувенир','Свежая живопись'],
'Страница без репродукций: адреса файлов для этих двух картин не удалось проверить. Это не обзор всего творчества, а две работы Метрополитен-музея.',
[['Метрополитен-музей: Пьяцца Сан-Марко (1988.162)','https://www.metmuseum.org/art/collection/search/435839'],['Метрополитен-музей: Кампо Сант-Анджело (2019.141.5)','https://www.metmuseum.org/art/collection/search/438103']],[],'text_only_image_rights_pending');
add('constable','Джон Констебл','John Constable','1776–1837','Англия · романтический пейзаж',
['Констебл родился в Ист-Бергхолте в 1776 году и умер в Хэмпстеде в 1837-м. Его «Солсберийский собор из епископского сада» (около 1825) в Метрополитен-музее — полноразмерный этюд для картины 1826 года из коллекции Фрика.'],
['Масло на холсте, 87,9 × 111,8 см. Заказ восходит к 1822 году: Констебл раскрыл кроны деревьев и добавил солнечное небо, чтобы обрамить шпиль собора — самый высокий в Англии.'],
'Картину заказал друг художника Джон Фишер, епископ Солсберийский; он изображён в левом нижнем углу, как и на окончательной версии.',
['Собор в обрамлении деревьев','Полноразмерный этюд','Солнечное небо вместо облачного','Епископ с семьёй на дорожке','Друг-заказчик'],
'Это этюд, а не итоговая картина (она хранится в коллекции Фрика). Репродукцию не подключаю: адрес файла для картины Метрополитен-музея не удалось проверить. Файл «Google Art Project» на Commons относится к версии Фрика, а не к этой.',
[['Метрополитен-музей: Солсберийский собор из епископских земель (50.145.8)','https://www.metmuseum.org/art/collection/search/435922']],[],'text_only_image_rights_pending');
add('bosch','Иероним Босх','Hieronymus Bosch','около 1450–1516','Нидерланды · северное Возрождение',
['Босх — нидерландский художник, умерший в 1516 году. Национальная галерея искусств в Вашингтоне хранит его панель «Смерть скупца» (около 1485/1490), и музей публикует эти изображения как открытые.'],
['Масло по дереву, 93 × 31 см (вместе с рамой 107,95 × 46,04 см). Голый мужчина с бледной кожей сидит на кровати под балдахином, а слева в дверь входит скелет со стрелой.'],
'Сцена соединяет разные моменты: демон с мешком золота искушает скупца из-под занавеси кровати, а коленопреклонённый ангел справа зовёт его к распятию в окне. Это «memento mori» о неизбежности смерти.',
['Скелет в дверях со стрелой','Демон с мешком золота','Ангел и распятие в окне','Высокая узкая панель','Часть триптиха'],
'Панель была частью триптиха, средняя часть которого утрачена (по Википедии). Репродукцию не подключаю: адрес файла в NGA не удалось получить.',
[['Национальная галерея искусств: Смерть скупца (1952.5.33)','https://www.nga.gov/artworks/41645-death-and-miser']],[],'text_only_image_rights_pending');
add('malevich','Казимир Малевич','Kazimir Malevich','1878–1935','Россия · супрематизм',
['Малевич родился в Киеве и умер в Ленинграде в 1935 году (в Русском музее указан 1878 год рождения, в других источниках — 1879). «Чёрный квадрат» в Русском музее датируется около 1923 года (масло, 106 × 106 см, Ж-9484, поступил в 1936 году).'],
['Музей называет «Чёрный квадрат» стоящим на простейших геометрических формах, из которых строится новая реальность, не связанная с природой. Первая версия была показана на выставке «0,10» в Петрограде в 1915 году.'],
'На выставке «0,10» картину повесили в правом углу зала, где в православных домах висят иконы. Сам Малевич называл её «голой иконой без рамы».',
['Простейшая геометрическая форма','Отказ от предметности','Красный угол вместо иконы','Четыре версии','Супрематизм'],
'Работ в США в открытом доступе почти нет; репродукцию не подключаю, потому что у файла на Commons неясна версия и источник. Правовой статус: по Commons, работа в общественном достоянии в России.',
[['Виртуальный Русский музей: Чёрный квадрат','https://rusmuseumvrm.ru/data/collections/painting/19_20/zh_9484/index.php?lang=en']],[],'text_only_image_rights_pending');
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
B.bruegel.aliases.push('Брейгель','Bruegel','Brueghel');B.hals.aliases.push('Халс','Hals');B.canaletto.aliases.push('Каналетто');B.constable.aliases.push('Констебл','Constable');B.bosch.aliases.push('Босх','Bosch');B.malevich.aliases.push('Малевич','Malevich');
const byName=new Map(Object.values(B).map(a=>[a.name,a])),host=document.getElementById('view');
function fixHeading(){const page=document.getElementById('artist-area'),a=byName.get(page?.querySelector('h1')?.textContent);if(!a)return;for(const h of page.querySelectorAll('h2')){if(h.textContent==='Пять работ: рассмотри и сравни')h.textContent=a.works.length===2?'Две работы: рассмотри и сравни':a.works.length?'Одна работа: рассмотри внимательно':'Репродукция пока не подключена';}}
if(host){new MutationObserver(fixHeading).observe(host,{childList:true,subtree:true});fixHeading();}
})();

;
/* artists-batch-30.js */
(()=>{'use strict';
const B={};
function add(id,name,latin,life,tag,bio,technique,innovation,features,caution,sources,status){B[id]={name,latin,life,tag,aliases:[name,latin],bio,technique,innovation,features,caution,sources,works:[],editorialStatus:status||'text_only_image_rights_pending'};}
add('rublev','Андрей Рублёв','Andrei Rublev','XV век (даты жизни спорны)','Россия · иконопись',
['Рублёв — самый известный русский иконописец. По Википедии, только две работы приписываются ему с уверенностью: икона «Троица» и фрески Успенского собора во Владимире.','«Троица» (около 1411 или 1425–27) создана для Троице-Сергиевой лавры в честь Сергия Радонежского. Официально указаны 1411 или 1425–27, но исследователи предлагали и 1408–1425, и 1422–1423.'],
['Темпера по доске, 142 × 114 см. Три ангела сидят за столом, на котором стоит чаша с головой тельца. На заднем плане — дом, дерево (дуб Мамре) и гора.','Поверхность неоднократно «поновлялась»: в 1904 году реставратор Гурьянов снял оклад и записи, а в 1918–1919 годах иконе вернули более близкий к авторскому вид.'],
'Рублёв отказался от большинства традиционных деталей сюжета «Гостеприимство Авраама»: нет ни Авраама, ни Сарры, ни сцены закалывания тельца. Ангелы беседуют, а не едят, и фигуры образуют круг — форму единосущия Троицы.',
['Круг, который образуют ангелы','Чаша с головой тельца в центре','Дом, дерево и гора','Отказ от сюжетных деталей','Тишина и неподвижность'],
'Икона — не станковая картина: её чтут как святыню. С 1929 года она была в Третьяковской галерее, в 2022 году её передали в Троице-Сергиеву лавру (с 2024 года — в Старый Троицкий собор). Музеи предупреждали о риске для хрупкой доски. Репродукцию не подключаю: файл ещё не выбран.',
[['Википедия: Троица (Андрей Рублёв)','https://en.wikipedia.org/wiki/Trinity_(Andrei_Rublev)']]);
add('repin','Илья Репин','Ilya Repin','1844–1930','Россия · реализм, передвижники',
['Репин вырос в Чугуеве (ныне Украина) и в 1863 году поступил в Императорскую академию художеств. «Бурлаки на Волге» (1870–1873) он считал первой своей профессиональной картиной.','Замысел возник во время поездки на Волгу в 1870 году; этюды Репин писал в Ширяевом овраге близ Ставрополя-на-Волге.'],
['Масло по холсту, 131,5 × 281 см, Русский музей. Одиннадцать бурлаков тянут баржу по берегу Волги; на заднем плане — крошечный пароход, намёк на близкий конец этого труда.','Репин писал реальных людей: среди них бывший солдат, расстрига-священник Канин и художник.'],
'Картина соединяет жанровую сцену с масштабом исторической живописи. Центром становится светловолосый юноша, который вырывается из лямки; выразительный ритм голов повторяет «стоп-ход» тяжёлого шага.',
['Одиннадцать бурлаков в ряд','Юноша в центре композиции','Расстрига Канин как ведущий','Серебристый «почти венецианский» свет','Пароход вдали'],
'Картину купил великий князь Владимир Александрович; в 1873 году она получила бронзовую медаль на Всемирной выставке в Вене. Критики упрекали её в академичности рисунка и желтоватом тоне. Это одна картина, а не вся биография Репина. Репродукцию не подключаю: файл ещё не выбран.',
[['Википедия: Бурлаки на Волге','https://en.wikipedia.org/wiki/Barge_Haulers_on_the_Volga']]);
add('vrubel','Михаил Врубель','Mikhail Vrubel','1856–1910','Россия · символизм и модерн',
['Врубель родился в Омске и умер в Петербурге. Третьяковская галерея пишет, что всю жизнь его занимал образ Демона.'],
['«Демон (сидящий)» (1890) — масло по холсту, 116,5 × 213,8 см (инв. 5600). Картина поступила в Третьяковскую галерею в 1917 году из собрания В. О. Гиршмана.','Сохранился акварельный эскиз 1890 года (17 × 27 см, инв. 5634), в котором уже найдена общая композиция.'],
'Врубель описывал замысел так: полуобнажённая крылатая молодая фигура сидит, обняв колени, на фоне заката и грустно смотрит на цветущую поляну, с которой к ней тянутся ветви.',
['Фигура, обнявшая колени','Закат за спиной','Цветущая поляна','Горизонтальный вытянутый холст','Образ Демона как тема жизни'],
'Это одна картина из цикла Врубеля о Демоне. Размеры в источниках слегка различаются (WikiArt даёт 212,5 × 115 см); принят размер Третьяковской галереи. Репродукцию не подключаю: файл ещё не выбран.',
[['Третьяковская галерея: Демон (сидящий)','https://my.tretyakov.ru/app/masterpiece/8393'],['Виртуальный Русский музей: Демон (сидящий)','https://rusmuseumvrm.ru/data/collections/museums/gtg/vrubel_m._a._demon_sidyaschiy._1890._inv._5600._gtg/index.php?lang=en']]);
add('aivazovsky','Иван Айвазовский','Ivan Aivazovsky','1817–1900','Россия · романтическая маринистика',
['Айвазовский родился в Феодосии (Крым) в семье армянина. «Девятый вал» (1850) — его самая известная работа.'],
['Масло по холсту, 221 × 332 см, Русский музей. Картина показывает море после ночной бури: люди, спасшиеся после кораблекрушения, цепляются за обломки.','Тёплые тона смягчают угрожающий вид моря, а шанс на спасение выглядит правдоподобным.'],
'Название связано с моряцким выражением: девятый вал — самая большая волна в череде нарастающих. Обломки в форме креста читаются как христианская метафора спасения.',
['Огромная волна на пределе','Люди на обломках мачты','Тёплый рассветный свет','Крест из мачты','Красота и насилие природы'],
'Это одна картина мариниста, а не обзор его творчества. Репродукцию не подключаю: файл ещё не выбран.',
[['Википедия: Девятый вал','https://en.wikipedia.org/wiki/The_Ninth_Wave']]);
add('shishkin','Иван Шишкин','Ivan Shishkin','1832–1898','Россия · реалистический пейзаж',
['Шишкин — классик русского лесного пейзажа. «Утро в сосновом лесу» (1889), прежде «Медвежье семейство в лесу», написано вместе с Константином Савицким.'],
['Масло по холсту, 139 × 213 см, Третьяковская галерея. Считается, что сосны писаны на острове Городомля на озере Селигер.','Сначала картина была без медведей: Савицкий по просьбе Шишкина дописал медвежат и медведицу, чтобы «оживить» сцену.'],
'Павел Третьяков купил картину с двумя подписями и приказал стереть подпись Савицкого скипидаром: по его словам, замысел и исполнение выдают манеру одного Шишкина. Сегодня картину обычно приписывают Шишкину.',
['Туман между стволами','Поваленная сосна и семейство медведей','Утренний свет','Лес без человека','Широко известная в России'],
'Один из самых популярных образов в России — он попал на обёртку конфет «Мишка косолапый». Репродукцию не подключаю: файл ещё не выбран.',
[['Википедия: Утро в сосновом лесу','https://en.wikipedia.org/wiki/Morning_in_a_Pine_Forest']]);
add('surikov','Василий Суриков','Vasily Surikov','1848–1916','Россия · историческая живопись',
['Суриков написал «Утро стрелецкой казни» в 1881 году; картина хранится в Третьяковской галерее.'],
['Масло по холсту. Размеры в источниках расходятся: Википедия и WikiArt дают 218 × 379 см, другой источник — 223 × 383,5 см.','Картина показывает Красную площадь перед казнью стрельцов после неудавшегося восстания 1698 года.'],
'В композиции — Пётр I с свитой, стрельцы на телегах, плачущие семьи, собор Василия Блаженного на заднем плане. Суриков строит картину как столкновение двух миров, а не как парадную историю.',
['Телеги со стрельцами','Пётр I на коне','Плачущие женщины и дети','Красная площадь и собор','Толпа как герой'],
'Это одна картина, а не вся биография Сурикова. Репродукцию не подключаю: файл ещё не выбран.',
[['Википедия: Утро стрелецкой казни','https://en.wikipedia.org/wiki/The_Morning_of_the_Streltsy_Execution']]);
add('levitan','Исаак Левитан','Isaac Levitan','1860–1900','Россия · лирический пейзаж',
['Павел Третьяков при жизни Левитана купил у него больше двадцати работ, и сегодня собрание Левитана в Третьяковской галерее — одно из крупнейших.'],
['«Над вечным покоем» (1893–1894) хранится в Третьяковской галерее. Картина показывает деревянную церковь на холме над широкой рекой под тяжёлыми облаками.','Другая работа — «Золотая осень» (1895), масло по холсту, 82 × 126 см.'],
'Левитан писал Третьякову, что в «Вечном покое» «вся моя личность, вся психика». Журнал Третьяковской галереи связывает его размышления о вечности и времени с символистскими мотивами.',
['Церковь на холме','Широкая река и небо','Размышление о вечности','Лирическое настроение','Коллекция Третьякова'],
'Размеры «Над вечным покоем» в найденных источниках не указаны, поэтому не привожу. Репродукцию не подключаю: файл ещё не выбран.',
[['Журнал Третьяковской галереи: О пейзажах Левитана','https://www.tretyakovgallerymagazine.com/node/1693']]);
add('serov','Валентин Серов','Valentin Serov','1865–1911','Россия · портрет и импрессионизм',
['«Девочка с персиками» (1887) — портрет 11-летней Веры Мамонтовой, дочери мецената Саввы Мамонтова. Картина написана в Абрамцеве, близ Москвы.'],
['Масло по холсту, 91 × 85 см, Третьяковская галерея. Серов вспоминал, что хотел достичь «свежести» и писал картину больше месяца, замучив девочку.','В 1887 году картина получила первую премию на выставке Московского общества любителей художеств.'],
'По книге «1000 Drawings of Genius» стиль картины близок к французским импрессионистам, хотя Серов познакомился с их работами позже. Игорь Грабарь назвал её шедевром русской живописи.',
['Свежесть цвета и света','Девочка за столом с персиками','Абрамцево как место','Портрет без позы','Интернет-мем'],
'Вера Мамонтова умерла в 1907 году в 32 года (по Википедии). Репродукцию не подключаю: файл ещё не выбран.',
[['Википедия: Девочка с персиками','https://en.wikipedia.org/wiki/Girl_with_Peaches']]);
add('kustodiev','Борис Кустодиев','Boris Kustodiev','1878–1927','Россия · модерн, бытовой жанр',
['«Купчиха за чаем» (1918) — масло по холсту, 120 × 120 см, Русский музей (Ж-1868). Поступила в 1925 году из Государственного музейного фонда.'],
['Масло по холсту, 120 × 120 см.'],
'Русский музей пишет, что «купчихи» Кустодиева с пышными фигурами и румяными щеками воплощали русский национальный идеал здоровья и красоты, а его сюжеты — безвозвратно ушедшую жизнь, не потерявшую своего острого аромата.',
['Румяная купчиха','Чаепитие как обряд','Яркие краски','Ностальгия','Квадратный формат'],
'Картина написана в 1918 году: музей видит в ней воспоминание об исчезнувшем быте. Репродукцию не подключаю: файл ещё не выбран.',
[['Виртуальный Русский музей: Купчиха за чаем','https://rusmuseumvrm.ru/data/collections/painting/19_20/zh_1868/index.php?lang=en']]);
add('filonov','Павел Филонов','Pavel Filonov','1883–1941','Россия · аналитическое искусство',
['«Пир королей» (1912–1913) хранится в Русском музее. По Commons, это масло по холсту, 175 × 215 см.'],
['В каталоге Arthive та же работа описана как акварель и тушь по картону (1912): сведения о материале расходятся, поэтому требуют проверки по музейной карточке.'],
'Arthive относит работу к «аналитическому реализму» — направлению, которое развивал сам Филонов. Подробный разбор пока не заполнен.',
['Аллегорическая сцена','Аналитический реализм','Русский музей','Расхождение в сведениях о материале','Крупный формат (175 × 215 см)'],
'Страница краткая и требует проверки: сведения о материале и дате «Пира королей» в источниках расходятся (Commons — масло, 1913; Arthive — акварель и тушь, 1912). Репродукцию не подключаю: файл ещё не выбран.',
[['Commons: Pavel Filonov KingsFeat.jpg','https://commons.wikimedia.org/wiki/File:Pavel_Filonov_KingsFeat.jpg'],['Arthive: Пир королей','https://arthive.com/pavelfilonov/works/336653~The_feast_of_kings']]);
add('blake','Уильям Блейк','William Blake','1757–1827','Англия · визионерский романтизм',
['Блейк был одновременно поэтом, гравёром и художником. «Древний днями» (1794) — фронтиспис его книги «Европа: пророчество».'],
['Цветная рельефная гравюра с белой линией и ручной раскраской. Копия D в Британском музее — 233 × 168 мм, копия A в Йельском центре британского искусства — оттиск 23,2 × 16,8 см.','Работа входит в 17 рельефных гравюр книги; каждая из сохранившихся копий раскрашена вручную по-разному.'],
'Бородатый нагой старец в огненном круге склонился с неба и измеряет тьму циркулем. Это Уризен — героиня авторской мифологии Блейка, а не обычный образ христианского Бога.',
['Циркуль над тьмой','Огненная сфера','Ручная раскраска оттисков','Собственная мифология','Тема бога-творца'],
'Это печатная графика с ручной раскраской, а не картина маслом. Блейк, по DailyArt, раскрашивал копию этой гравюры за несколько дней до смерти (источник неоднозначный). Репродукцию не подключаю: файл ещё не выбран.',
[['Британский музей: Европа: пророчество, копия D','https://www.britishmuseum.org/collection/object/P_1859-0625-72'],['Йельский центр британского искусства: Древний днями','https://collections.britishart.yale.edu/catalog/tms:3878']]);
add('matisse','Анри Матисс','Henri Matisse','1869–1954','Франция · фовизм',
['«Радость жизни» (Le Bonheur de vivre) написана между октябрём 1905 и мартом 1906 года и хранится в Фонде Барнса (Филадельфия, BF719).'],
['Масло по холсту, 176,5 × 240,7 см. Каталог причисляет работу к фовизму и описывает её как композицию из плоских цветовых пятен.'],
'Каталог причисляет картину к фовизму и описывает её как композицию из плоских цветовых областей. Подробный разбор пока не заполнен.',
['Плоские цветовые области','Фовизм','Большой формат (176,5 × 240,7 см)','Фонд Барнса, BF719','Рубеж 1905–1906 годов'],
'Матисс умер в 1954 году: для работ после 1930 года статус защиты зависит от страны, поэтому репродукции нужно проверять отдельно. Репродукцию не подключаю.',
[['Фонд Барнса: Радость жизни','https://collection.barnesfoundation.org/objects/7199/Le-Bonheur-de-vivre-also-called-The-Joy-of-Life/']]);
add('klee','Пауль Клее','Paul Klee','1879–1940','Швейцария/Германия · Баухаус',
['Клее родился в Швейцарии. К моменту создания «Поющей машины» (1922) он год преподавал в Баухаусе.'],
['«Поющая машина» — рисунок «масляной кальки» с акварелью и тушью по бумаге, 64,1 × 48,3 см (MoMA, 564.1939). Клее обводил оригинал иглой по листу, покрытому масляной краской, и получал «случайные» пятна, подчёркивающие плоскость.'],
'MoMA видит в ней «жестокий союз природы и техники»: птицы привязаны к жердочке с ручкой над ямой — ловушкой для следующего «певца».',
['Птицы на проволоке','Ручка-рукоятка','Синий фон и розовое пятно','Метод масляной кальки','Природа и механизм'],
'Это работа на бумаге, а не холст. В 1933 году нацисты объявили её «дегенеративным искусством» и в 1939 году продали дилеру за 120 долларов; в том же году её купил MoMA. Репродукцию не подключаю: Клее умер в 1940 году, но права на файл нужно проверить.',
[['MoMA: Twittering Machine','https://www.moma.org/collection/works/37347'],['Википедия: Twittering Machine','https://en.wikipedia.org/wiki/Twittering_Machine']]);
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
const al={rublev:['Рублёв','Рублев','Rublev'],repin:['Репин','Repin'],vrubel:['Врубель','Vrubel'],aivazovsky:['Айвазовский','Aivazovsky'],shishkin:['Шишкин','Shishkin'],surikov:['Суриков','Surikov'],levitan:['Левитан','Levitan'],serov:['Серов','Serov'],kustodiev:['Кустодиев','Kustodiev'],filonov:['Филонов','Filonov'],blake:['Блейк','Blake'],matisse:['Матисс','Matisse'],klee:['Клее','Klee']};
for(const k in al)B[k].aliases.push(...al[k]);
const byName=new Map(Object.values(B).map(a=>[a.name,a])),host=document.getElementById('view');
function fixHeading(){const page=document.getElementById('artist-area'),a=byName.get(page?.querySelector('h1')?.textContent);if(!a)return;for(const h of page.querySelectorAll('h2')){if(h.textContent==='Пять работ: рассмотри и сравни')h.textContent='Репродукция пока не подключена';}}
if(host){new MutationObserver(fixHeading).observe(host,{childList:true,subtree:true});fixHeading();}
})();

;
/* artists-batch-31.js */
(()=>{'use strict';
const B={};
function add(id,name,latin,life,tag,bio,technique,innovation,features,caution,sources){B[id]={name,latin,life,tag,aliases:[name,latin],bio,technique,innovation,features,caution,sources,works:[],editorialStatus:'text_only_rights_protected'};}
const rights='Права на изображение защищены (или статус неясен): репродукцию не подключаю, смотри музейную карточку по ссылке.';
add('kokoschka','Оскар Кокошка','Oskar Kokoschka','1886–1980','Австрия · экспрессионизм',
['Кокошка родился в 1886 году и умер в Швейцарии 22 февраля 1980 года. «Невеста ветра» (1913–1914) — его самая известная работа.','В 1912 году он познакомился с Альмой Малер, вдовой композитора Густава Малера; начался страстный роман, из которого вышло множество рисунков и картин.'],
['Масло по холсту, 181 × 220 см, Кунстмузеум Базель. Картина показывает Альму, мирно спящую рядом с Кокошкой, который бодрствует и смотрит в пространство.','Разрыв пары в 1914 году, по описанию, сделал его мазок более бурным.'],
'Поэт Георг Тракль почти ежедневно навещал Кокошку во время работы и воспел картину в стихотворении «Ночь». Картину называют также «Буря» (Die Windsbraut).',
['Автопортрет рядом с возлюбленной','Спящая Альма и бодрствующий художник','Турбулентные мазки','Аллегорическая композиция','Базельский музей'],
rights+' Кокошка умер в 1980 году.',
[['Википедия: Невеста ветра','https://en.wikipedia.org/wiki/The_Bride_of_the_Wind']]);
add('dali','Сальвадор Дали','Salvador Dalí','1904–1989','Испания · сюрреализм',
['«Постоянство памяти» (1931) — самая известная работа Дали и один из самых узнаваемых образов сюрреализма. Её впервые показали в галерее Жюльена Леви в 1932 году и продали за 250 долларов; в 1934 году анонимный даритель передал картину MoMA.'],
['Масло по холсту, 24 × 33 см (MoMA, 162.1934). Мягкие «тающие» часы соседствуют с причудливым существом в центре; оранжевые часы слева покрыты муравьями и не плавятся.','За год до этого Дали разработал «паранойяльно-критический метод», вызывая у себя галлюцинации.'],
'Дали объяснял мягкие часы не теорией относительности, а образом камамбера, тающего на солнце. Существо в центре считают приблизительным автопортретом; скалы справа напоминают мыс Кап-де-Креус в Каталонии.',
['Плавящиеся часы','Часы с муравьями','Существо в центре — автопортрет','Каталонский пейзаж','Малый формат (24 × 33 см)'],
rights+' Дали умер в 1989 году.',
[['Википедия: Постоянство памяти','https://en.wikipedia.org/wiki/The_Persistence_of_Memory']]);
add('magritte','Рене Магритт','René Magritte','1898–1967','Бельгия · сюрреализм',
['«Вероломство образов» (1929) — картина Магритта, известная также как «Это не трубка». Она хранится в Художественном музее округа Лос-Анджелес (LACMA).'],
['Масло по холсту, 60,33 × 81,12 см. Изображена курительная трубка, под ней — надпись по-французски: «Ceci n’est pas une pipe» («Это не трубка»).','В 1929 году Магритт опубликовал в журнале «Сюрреалистическая революция» свой программный текст «Слова и образы».'],
'Магритт говорил, что трубку нельзя набить табаком: это лишь изображение. Подпись «Это трубка» была бы ложью. Картина стала примером мета-сообщения и предметом эссе Мишеля Фуко «Это не трубка».',
['Трубка без дыма','Надпись под изображением','Игра слов и образов','Философский диалог','Многие вариации темы'],
rights+' Магритт умер в 1967 году.',
[['Википедия: Вероломство образов','https://en.wikipedia.org/wiki/The_Treachery_of_Images']]);
add('ernst','Макс Эрнст','Max Ernst','1891–1976','Германия/США · дадаизм и сюрреализм',
['«Европа после дождя II» (1940–1942) хранится в Атенеуме Уодсворт в Хартфорде (США). Эрнст написал её вскоре после бегства из оккупированной Франции в США, где ему помогала Пегги Гуггенхейм.'],
['Масло по холсту, 54 × 146 см. По описаниям, картина показывает разорённый ландшафт, в котором природные и архитектурные формы сливаются; Эрнст применил декалькоманию — отпечатки краски между поверхностями.'],
'Название восходит к более ранней рельефной «карте Европы» 1933 года, года прихода Гитлера к власти. Однозначного толкования нет: фигуры похожи на поросшие статуи или полумифических выживших.',
['Руины и органические формы','Декалькомания','Фигура с копьём и птичья голова','Изгнание и война','Эмигрантский период'],
rights+' Эрнст умер в 1976 году. Размеры взяты из сторонних каталогов (Artchive, WikiArt), поэтому их стоит сверить с музеем.',
[['Макс Эрнст: Europe after the Rain II','https://www.max-ernst.com/europe-after-rain.jsp']]);
add('miro','Жоан Миро','Joan Miró','1893–1983','Испания · каталонский сюрреализм',
['«Ферма» (1921–1922) хранится в Национальной галерее искусств (Вашингтон, 1987.18.1). Миро считал картину итогом жизни в деревне и отправной точкой для всего дальнейшего творчества.'],
['Масло по холсту, 123,8 × 141,3 см. Миро писал её девять месяцев, начав в Монт-роиг-дель-Кампе летом 1921 года и закончив в Париже зимой 1922-го; ради травы он просил прислать настоящие высохшие травы из Монт-роига.','Каждый лист эвкалипта, каждый камень и каждое животное прописаны отдельно.'],
'Дилер Леонс Розенберг серьёзно предлагал разрезать холст на восемь частей, чтобы его легче было продать. Миро забрал картину; её купил Эрнест Хемингуэй за пять тысяч франков.',
['Эвкалипт в центре','Мул, куры, собака, коза, кролик','Исчерпывающая «опись» фермы','Наивная ясность и кубизм','Хемингуэй как владелец'],
rights+' Миро умер в 1983 году.',
[['Википедия: Ферма (Миро)','https://en.wikipedia.org/wiki/The_Farm_(Mir%C3%B3)']]);
add('hopper','Эдвард Хоппер','Edward Hopper','1882–1967','США · американский реализм',
['«Полуночники» (1942) — самая известная картина Хоппера, хранится в Чикагском институте искусств (1942.51). Её купили за 3000 долларов 13 мая 1942 года.'],
['Масло по холсту, 84,1 × 152,4 см. Четверо людей в закусочной ночью, видимые сквозь огромное стекло; свет из закусочной освещает тёмную пустую улицу.','Позировали Хоппер (для двух мужчин, в зеркале) и его жена Джо (для женщины).'],
'Хоппер говорил, что «упрощал сцену» и «сделал закусочную больше», вдохновившись кафе в Гринвич-Виллидж. Об одиночестве он сказал, что, возможно, невольно писал одиночество большого города.',
['Закусочная за стеклом','Ночная пустая улица','Четыре фигуры','Яркий свет интерьера на тёмной улице','Одиночество города'],
rights+' Хоппер умер в 1967 году; статус зависит от даты работы и страны.',
[['Википедия: Полуночники','https://en.wikipedia.org/wiki/Nighthawks_(Hopper)']]);
add('okeeffe','Джорджия О’Кифф','Georgia O’Keeffe','1887–1986','США · американский модернизм',
['«Коровий череп: красный, белый и синий» (1931) хранится в Метрополитен-музее (52.203) в коллекции Альфреда Штиглица. После поездки 1929 года на юго-запад США её интересы сместились от нью-йоркских зданий к природе Нью-Мексико.'],
['Масло по холсту, 101,3 × 91,1 см. Белый череп с рогами в центре; позади чёрная вертикальная полоса, красные полосы по краям и сине-белый фон.','Музей читает кости как символ красоты пустыни и силы американского духа.'],
'О’Кифф выбрала красно-бело-синюю палитру, чтобы картина выглядела патриотично, и стремилась создать новое представление об «американском» искусстве. Чёрная полоса может быть тыльной стороной мольберта.',
['Череп как портрет','Красно-бело-синяя палитра','Чёрная вертикаль','Образ пустыни','Коллекция Штиглица'],
rights+' О’Кифф умерла в 1986 году.',
[['Метрополитен-музей: Коровий череп','https://www.metmuseum.org/art/collection/search/488694']]);
add('wyeth','Эндрю Уайет','Andrew Wyeth','1917–2009','США · американский реализм',
['«Мир Кристины» (1948) — одна из самых известных картин американского искусства. Её купил MoMA в 1949 году.'],
['Темпера по доске, 81,9 × 121,3 см (MoMA). Одинокая фигура в поле в штате Мэн; Уайет значительно увеличил поле, чтобы усилить драму сцены.'],
'Историк искусства Роберт Розенблюм в 1977 году назвал Уайета одновременно самым недооценённым и самым переоценённым художником в истории. Картина остаётся образом американского реализма.',
['Фигура в поле','Увеличенное поле','Темпера по доске','Мэнский пейзаж','Темпера по доске, а не масло'],
rights+' Уайет умер в 2009 году.',
[['MoMA: Мир Кристины','https://www.moma.org/audio/playlist/172/2279']]);
add('pollock','Джексон Поллок','Jackson Pollock','1912–1956','США · абстрактный экспрессионизм',
['«Осенний ритм (№ 30)», 1950 хранится в Метрополитен-музее (57.92, Hearn Fund 1957). Это одна из трёх монументальных картин, написанных летом 1950 года (вместе с № 32 и «Единство: № 31»).'],
['Размер 269,9 × 528,3 см. Материал описывается по-разному: Метрополитен-музей указывает оксидированную алкидную смолу по холсту, Википедия — эмалевую краску.','Поллок работал в технике «пролитой» краски (дриппинг).'],
'Работа считается образцом «живописи действия»: масштаб картины создаёт эффект среды, в которую погружается зритель.',
['Переплетение пролитых линий','Огромный горизонтальный формат (около 2,7 × 5,3 м)','Отсутствие центра','Дриппинг','Один из трёх монументальных холстов 1950 года'],
rights+' Поллок умер в 1956 году, правообладатель — Pollock-Krasner Foundation (по записи Met).',
[['Метрополитен-музей: Осенний ритм','https://www.metmuseum.org/art/collection/search/488978'],['Википедия: Осенний ритм','https://en.wikipedia.org/wiki/Autumn_Rhythm_(Number_30)']]);
add('rothko','Марк Ротко','Mark Rothko','1903–1970','США · цветовые поля',
['«№ 61 (Ржавый и синий) [Коричневый, синий, коричневый на синем]» (1953) хранится в Музее современного искусства в Лос-Анджелесе (MOCA, 84.9, собрание Панцы).'],
['Масло по холсту, 292,74 × 233,68 см. Большие участки цвета с тёмными оттенками: по описанию, ржавый фон и синий прямоугольник в центре.'],
'Страница краткая: в найденных источниках — только паспорт картины. Разбор эффекта цветовых полей пока не заполнен.',
['Огромные цветовые поля','Ржавый и синий','Вертикальный формат (около 2,9 × 2,3 м)','Собрание Панцы','Данные паспорта'],
rights+' Ротко умер в 1970 году; правообладатели — Kate Rothko Prizel и Christopher Rothko (по записи MOCA).',
[['MOCA: № 61 (Rust and Blue)','https://www.moca.org/artworks/no-61-rust-and-blue-brown-blue-brown-on-blue']]);
add('warhol','Энди Уорхол','Andy Warhol','1928–1987','США · поп-арт',
['«Банки с супом Кэмпбелл» — серия из 32 картин (1961–1962), каждая 51 × 41 см, акриловая краска по холсту; хранится в MoMA (476.1996.1–32), куда поступила в 1996 году.','Впервые серию показали 9 июля 1962 года в галерее Ферус (Лос-Анджелес); её хозяин Ирвинг Блюм выкупил весь комплект у Уорхола за 1000 долларов, заплатив десятью ежемесячными взносами по 100.'],
['Вопреки распространённому мнению, оригинальные 32 холста не шелкографии: они обведены и расписаны вручную, а золотую лилию на каждом отпечатали резиновым штампом.','Банки писались по фотографиям Эдварда Валловича.'],
'Уорхол превратил упаковку — а не сам суп — в предмет искусства, а повторение сделал темой: банки почти одинаковы и различаются сортами.',
['32 банки по числу сортов','Одинаковый формат (51 × 41 см)','Ручная роспись и штамп','Выставка «на полке»','Серия как единое произведение'],
rights+' Уорхол умер в 1987 году. Не путай оригинал с позднейшими сериями шелкографий 1968–1969 годов.',
[['Википедия: Банки с супом Кэмпбелл','https://en.wikipedia.org/wiki/Campbell%27s_Soup_Cans']]);
add('lichtenstein','Рой Лихтенштейн','Roy Lichtenstein','1923–1997','США · поп-арт',
['«Бам!» (Whaam!, 1963) — двухпанельная картина из акрила (Magna), масла и графитового карандаша на холсте, общий размер 173 × 405,9 см. В каталоге-резоне она значится под номером RLCR 808; в Тейт она числится с декабря 1966 года.'],
['Каждая панель около 172,9 × 203 см. Картина основана на комиксе; сохранился рисунок к ней (графит на бумаге, 149 × 305 мм, подарок художника, 1969 год).'],
'Страница краткая: найдены размеры, материал и история хранения. Разбор приёмов (растр, контур) пока не заполнен.',
['Две панели','Комиксный сюжет','Большой формат (около 1,7 × 4 м)','Каталог-резоне RLCR 808','Коллекция Тейт'],
rights+' Лихтенштейн умер в 1997 году.',
[['Каталог-резоне Лихтенштейна: Whaam!','https://www.lichtensteincatalogue.org/catalogue/entry.php?id=472']]);
add('bacon','Фрэнсис Бэкон','Francis Bacon','1909–1992','Великобритания · фигуративный экспрессионизм',
['«Три этюда фигур у подножия распятия» (1944) — триптих, написанный за две недели; Бэкон считал его началом своего творчества и уничтожил большую часть более ранних работ.','Триптих показали в галерее Лефевр в Лондоне в апреле 1945 года, и он вызвал сенсацию; в 1953 году его передал в дар Тейт Эрик Холл.'],
['Масло и пастель по ДВП, три панели по 94 × 73,7 см (Tate Britain, N06171). Три искажённых существа на плоском оранжевом фоне.','Бэкон вспоминал, что писал, мучаясь похмельем, и что выпивка, возможно, помогла ему стать свободнее.'],
'Существа основаны на Эриниях из «Орестеи» Эсхила. Бэкон, неверующий, рассматривал распятие не как религиозное событие, а как человеческое поведение.',
['Три существа на оранжевом фоне','Вытянутая шея и раскрытый рот','Плоский фон','Эринии вместо святых','Начало зрелого творчества'],
rights+' Бэкон умер в 1992 году.',
[['Бэкон, каталог-резоне: Three Studies','https://www.francis-bacon.com/artworks/paintings/three-studies-figures-base-crucifixion'],['Википедия: Three Studies','https://en.wikipedia.org/wiki/Three_Studies_for_Figures_at_the_Base_of_a_Crucifixion']]);
add('hockney','Дэвид Хокни','David Hockney','родился в 1937','Великобритания · поп-арт',
['«Больший всплеск» (A Bigger Splash, 1967) — акрил (Liquitex) по белому хлопковому холсту, 242,5 × 243,9 см, Tate (T03254, куплена в 1981 году). Картина показывает бассейн рядом с современным домом и всплеск от невидимого прыгуна.'],
['По данным Тейт, Хокни писал сам всплеск две недели, копируя форму, оттенки и детали с фотографии маленькими кистями. Эскиза на холсте не было.'],
'Картина почти в натуральную величину: зритель оказывается внутри сцены, а не перед ней.',
['Бассейн и трамплин','Всплеск как главная форма','Квадратный формат (около 2,4 × 2,4 м)','Акрил без подготовительного рисунка','Калифорнийский свет'],
rights+' Хокни жив.',
[['Tate: Больший всплеск','https://www.tate.org.uk/art/artworks/hockney-a-bigger-splash-t03254'],['Tate: Понимание A Bigger Splash','https://www.tate.org.uk/art/artworks/hockney-a-bigger-splash-t03254/understanding-david-hockneys-bigger-splash']]);
add('nerdrum','Одд Нердрум','Odd Nerdrum','родился в 1944','Норвегия · фигуративная живопись, «китч»',
['Нердрум родился в Хельсингборге (Швеция) в 1944 году и называет свою живопись китчем, а не искусством. Главные влияния — Рембрандт и Караваджо; он противопоставляет себя абстракции и концептуальному искусству.','Он учился в Академии художеств в Осло и недолго у Йозефа Бойса; его учениками были Эми Шеральд и Сара Макрэй Мортон.'],
['Нердрум пишет по традиционным методам: сам растирает краски, работает по холсту, который сам натянул, и с натуры, часто с самого себя и членов семьи. В 2011 году он признал, что техника 1980-х годов (смесь масла и воска) была ошибочной.'],
'Манифест «О китче» (2001) лёг в основу движения: его последователи называют себя китч-художниками. «Рассвет» (Dawn, 1989), принадлежавший Дэвиду Боуи, продан на аукционе Sotheby’s в 2016 году за 341 000 фунтов — рекорд для художника на тот момент.',
['Рембрандт и Караваджо','Безвременные костюмы и пустынный ландшафт','Тихие архетипические фигуры','Манифест «О китче»','Собственные краски'],
rights+' Нердрум жив. В 2011–2014 годах он был осуждён в Норвегии за уклонение от налогов, а в 2017 году помилован королём Харальдом V.',
[['Википедия: Одд Нердрум','https://en.wikipedia.org/wiki/Odd_Nerdrum']]);
add('kahlo','Фрида Кало','Frida Kahlo','1907–1954','Мексика · автопортрет, сюрреализм',
['«Две Фриды» (1939) — первая крупная работа Кало, двойной автопортрет: слева женщина в европейском платье, справа в мексиканском платье из Теуантепека. Картина написана в год развода с Диего Риверой (они снова поженились через год).'],
['Масло по холсту, 173,5 × 173 см, Музей современного искусства в Мехико. Фриды держатся за руки; кровеносный сосуд соединяет их сердца, а у европейской Фриды зажим перерезает его, и кровь капает на белое платье.','В 1947 году картину приобрёл Национальный институт изящных искусств, а в 1966-м передал музею.'],
'Трактовки различаются: двойное происхождение (немецкий отец, мексиканская мать); любимая и отвергнутая Диего Фрида; по воспоминаниям самой Кало — образ воображаемой подруги детства. Картину показали на Международной выставке сюрреализма в Мехико в январе 1940 года.',
['Две Фриды рядом','Европейское и мексиканское платье','Общий кровеносный сосуд','Портрет Диего в руке','Открытые сердца'],
rights+' Кало умерла в 1954 году; срок защиты зависит от страны.',
[['Википедия: Две Фриды','https://en.wikipedia.org/wiki/The_Two_Fridas']]);
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
const al={kokoschka:['Кокошка','Kokoschka'],dali:['Дали','Dali','Dalí'],magritte:['Магритт','Magritte'],ernst:['Эрнст','Ernst'],miro:['Миро','Miro'],hopper:['Хоппер','Hopper'],okeeffe:['О’Кифф','Окифф',"O'Keeffe",'OKeeffe'],wyeth:['Уайет','Wyeth'],pollock:['Поллок','Pollock'],rothko:['Ротко','Rothko'],warhol:['Уорхол','Уорхолл','Warhol'],lichtenstein:['Лихтенштейн','Lichtenstein'],bacon:['Бэкон','Бекон','Bacon'],hockney:['Хокни','Hockney'],nerdrum:['Нердрум','Nerdrum'],kahlo:['Кало','Kahlo']};
for(const k in al)B[k].aliases.push(...al[k]);
const byName=new Map(Object.values(B).map(a=>[a.name,a])),host=document.getElementById('view');
function fixHeading(){const page=document.getElementById('artist-area'),a=byName.get(page?.querySelector('h1')?.textContent);if(!a)return;for(const h of page.querySelectorAll('h2')){if(h.textContent==='Пять работ: рассмотри и сравни')h.textContent='Репродукция пока не подключена';}}
if(host){new MutationObserver(fixHeading).observe(host,{childList:true,subtree:true});fixHeading();}
})();

;
/* artists-batch-32.js */
(()=>{'use strict';
const B={};
function add(id,name,latin,life,tag,bio,technique,innovation,features,caution,sources){B[id]={name,latin,life,tag,aliases:[name,latin],bio,technique,innovation,features,caution,sources,works:[],editorialStatus:'text_only_rights_protected'};}
const rights='Права на изображение защищены: репродукцию не подключаю, смотри музейную или аукционную карточку по ссылке.';
add('basquiat','Жан-Мишель Баския','Jean-Michel Basquiat','1960–1988','США · неоэкспрессионизм',
['Баския родился в Бруклине 22 декабря 1960 года, отец — выходец с Гаити, мать — американка пуэрто-риканского происхождения. Умер в Манхэттене 12 августа 1988 года в 27 лет от передозировки героина.','В 1978 году он начал писать граффити на стенах Нижнего Манхэттена вместе с Алом Диасом под псевдонимом SAMO. В 21 год он стал самым молодым участником Documenta в Касселе (1982), а в 22 года — одним из самых молодых участников Биеннале Уитни (1983).'],
['«Голливудские африканцы» (1983) — акрил и масляная пастель по холсту, 213,5 × 213,4 см, Музей американского искусства Уитни (84.23, дар Дугласа Крамера). Баския написал картину во время длительной поездки в Лос-Анджелес; на ней он изображён с граффитчиками Токсиком и Раммельзи.','Холст покрыт плотным текстом и несколькими линейными рисунками на жёлтом размытом фоне (по описанию музея).'],
'Баския соединял слово и образ, абстракцию и фигуративность, поэзию, рисунок и живопись. Его картины покрыты кодами: словами, буквами, цифрами, пиктограммами, логотипами и схемами. Корону и ореол он использовал, чтобы обозначить героев и святых.',
['Слова и перечёркнутые надписи','Короны и ореолы','Головы и черепа','Акрил и масляная пастель','Портреты друзей-граффитчиков'],
rights+' В 2017 году картина «Без названия» (1982) с чёрным черепом и красно-жёлтыми потёками продана за 110,5 млн долларов. За десять лет он создал около 600 картин и 1500 рисунков.',
[['Музей Уитни: Голливудские африканцы','https://whitney.org/media/62993'],['Википедия: Жан-Мишель Баския','https://en.wikipedia.org/wiki/Jean-Michel_Basquiat'],['Sotheby’s: Без названия (1982)','https://www.sothebys.com/en/articles/monumental-basquiat-leads-contemporary-art-evening-sale']]);
add('banksy','Бэнкси','Banksy','с 1990-х годов; личность не подтверждена','Великобритания · стрит-арт',
['Бэнкси — псевдоним английского уличного художника, который никогда публично не подтверждал свою личность. Он начинал в бристольском андеграунде в 1990–1994 годах как граффитчик, а к 2000 году перешёл на трафареты, потому что так работа занимает меньше времени.','Он больше не продаёт фотографии и репродукции своих уличных работ. Небольшое число работ официально продаётся через созданную им структуру Pest Control, которая также подтверждает подлинность.'],
['«Любовь в мусорной корзине» (Love Is in the Bin, 2018) — акция Бэнкси в Sotheby’s Лондон: его картина 2006 года «Девочка с шаром» самоуничтожилась сразу после продажи. Материалы: аэрозоль и акрил, холст, картон; размер 101 × 78 × 18 см.','Шредер был спрятан в раме и остановился, когда полотно прошло примерно наполовину; Бэнкси говорил, что хотел измельчить его полностью.'],
'Sotheby’s назвал работу «первым в истории произведением искусства, созданным прямо на аукционе». Картину продали 5 октября 2018 года за 1 042 000 фунтов; покупательница оставила покупку, а работа была переименована. Она в бессрочном пользовании Штаатсгалери Штутгарта с марта 2019 года.',
['Трафаретная техника','Политическая и социальная сатира','Анонимность автора','Акция на аукционе','Рост цены с 1 до 18,6 млн фунтов'],
rights+' Это уличный художник, а не живописец в привычном смысле. 14 октября 2021 года «Любовь в мусорной корзине» перепродана за 18 582 000 фунтов (около 25,4 млн долларов) при ориентире 4–6 млн — рекорд для автора на тот момент.',
[['Википедия: Love Is in the Bin','https://en.wikipedia.org/wiki/Love_Is_in_the_Bin'],['Би-би-си: Love is in the Bin продана за рекордные 16 млн фунтов','https://www.bbc.com/news/entertainment-arts-58908768'],['Википедия: Бэнкси','https://en.wikipedia.org/wiki/Banksy']]);
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
B.basquiat.aliases.push('Баския','Баскиа','Basquiat');B.banksy.aliases.push('Бэнкси','Банкси','Banksy');
const byName=new Map(Object.values(B).map(a=>[a.name,a])),host=document.getElementById('view');
function fixHeading(){const page=document.getElementById('artist-area'),a=byName.get(page?.querySelector('h1')?.textContent);if(!a)return;for(const h of page.querySelectorAll('h2')){if(h.textContent==='Пять работ: рассмотри и сравни')h.textContent='Репродукция пока не подключена';}}
if(host){new MutationObserver(fixHeading).observe(host,{childList:true,subtree:true});fixHeading();}
})();

;
/* artists-batch-33.js */
(()=>{'use strict';
const B={};
function add(id,name,latin,life,tag,bio,technique,innovation,features,caution,sources,al){B[id]={name,latin,life,tag,aliases:[name,latin,...al],bio,technique,innovation,features,caution,sources,works:[],editorialStatus:'text_only_rights_protected'};}
const R='Права на изображение защищены (или статус неясен): репродукцию не подключаю, смотри музейную карточку по ссылке.';
add('chagall','Марк Шагал','Marc Chagall','1887–1985','Россия/Франция · модернизм',
['Шагал родился в 1887 году в Российской империи, жил и работал в Париже и умер во Франции в 1985 году.'],
['«Я и деревня» (1911) — масло по холсту, 192,1 × 151,4 см, МоМА, Нью-Йорк (146.1945, Mrs. Simon Guggenheim Fund). Картина написана в Париже; МоМА приобрёл её 13 июня 1945 года.'],
'Картина собирает воспоминания о деревне из разорванных, кубистически разрезанных образов и профилей лиц; в каталогах её относят к кубизму.',
['Профили лиц','Воспоминания о родной деревне','Кубистические сдвиги плоскостей','Большой вертикальный формат'],
R+' Шагал умер в 1985 году.',
[['МоМА: Я и деревня','https://www.moma.org/collection/works/78984'],['Википедия: I and the Village','https://en.wikipedia.org/wiki/I_and_the_Village']],['Шагал','Chagall']);
add('dekooning','Виллем де Кунинг','Willem de Kooning','1904–1997','США/Нидерланды · абстрактный экспрессионизм',
['Де Кунинг родился в Роттердаме в 1904 году, жил в США и умер в Ист-Хэмптоне, штат Нью-Йорк, в 1997 году.'],
['«Женщина I» (1950–52) — масло и металлическая краска по холсту, 192,7 × 147,3 см, МоМА (478.1953, покупка 1953 года). По данным МоМА, он писал её, стирал и переписывал около пятидесяти раз до лета 1952 года.'],
'После лет абстракции де Кунинг вернулся к фигуре. Картина открывает серию из шести больших холстов с одной женщиной (1950–53): гигантские глаза, зубастая улыбка, резкие мазки оранжевого, синего, жёлтого и зелёного поверх чёрных контуров. МоМА связывает образ с палеолитическими фетишами плодородия и американскими плакатами.',
['Серия «Женщина»','Многослойные переписанные мазки','Фигура, рвущаяся за край холста','Возврат к фигуративности в эпоху абстракции','Масло и металлическая краска'],
R+' Де Кунинг умер в 1997 году, правообладатель — The Willem de Kooning Foundation (по записи МоМА).',
[['МоМА: Женщина I','https://www.moma.org/collection/works/79810'],['Метрополитен: Woman, I','https://www.metmuseum.org/de/art/collection/search/687867']],['Де Кунинг','de Kooning','De Kooning']);
add('freud','Люсьен Фрейд','Lucian Freud','1922–2011','Великобритания · реализм',
['Фрейд — британский художник, внук Зигмунда Фрейда; умер в 2011 году.'],
['«Смотрительница пособий спит» (1995) — масло по холсту, 151,3 × 219 см, частная коллекция. Модель — Сью Тилли, работница лондонского Jobcentre; фигура написана в натуральную величину и лежит на потрёпанном диване.'],
'Аукцион Christie’s продал картину в мае 2008 года в Нью-Йорке за 33,6 млн долларов Роману Абрамовичу; тогда это был рекорд для живущего художника. В 2015 году «Бригадир» ушёл за 35,8 млн фунтов (56,2 млн долларов) и вытеснил её с первого места среди работ Фрейда на аукционах.',
['Обнажённая натура без идеализации','Натуральная величина','Плотная фактура масла','Потёртый диван','Частная коллекция'],
R+' Фрейд умер в 2011 году.',
[['Википедия: Benefits Supervisor Sleeping','https://en.wikipedia.org/wiki/Benefits_Supervisor_Sleeping'],['Christie’s: лот 1997 года','https://www.christies.com/en/lot/lot-5074074'],['The Times: рекорд $33 млн','https://www.thetimes.com/travel/destinations/uk-travel/england/london-travel/lucian-freuds-benefits-supervisor-sleeping-sells-for-record-dollar33m-zh8vc8ljglc']],['Фрейд','Freud']);
add('murakami','Такаси Мураками','Takashi Murakami','род. 1962','Япония · Superflat',
['Мураками родился в 1962 году. Он автор термина Superflat (2000): так называется и его теория плоскостности в японском искусстве (укиё-э, манга, аниме), и выставка в Токио, которая в 2001 году поехала в США: MOCA Лос-Анджелес, Walker Art Center, Henry Art Gallery. В 2001 году его мастерская стала компанией Kaikai Kiki Co.'],
['«727» (1996) — синтетический полимер по холсту на доске, три панели, 299,7 × 449,6 см, МоМА (дар Дэвида Тейгера, 2003). Гигантская волна напоминает гравюры Хокусая; фон создан примерно двадцатью слоями краски, которые снимали, — ссылка на стиль нихонга. На ней персонаж Mr. DOB.'],
'Superflat стирает границу между высоким и низким, музеем и торговлей, поэтому Мураками работает и с живописью, и с товарами Kaikai Kiki.',
['Mr. DOB','Три панели, как ширма','Волна в духе Хокусая','Плоские цветовые плоскости','Фон нихонга'],
R+' Мураками жив, правообладатель — Takashi Murakami/Kaikai Kiki Co., Ltd. (по записи МоМА).',
[['МоМА: 727','https://www.moma.org/slideshows/35/660'],['TheArtStory: Superflat','https://www.theartstory.org/movement/superflat/'],['Википедия: Superflat','https://en.wikipedia.org/wiki/Superflat']],['Мураками','Murakami']);
add('rivera','Диего Ривера','Diego Rivera','1886–1957','Мексика · муралисты',
['Ривера входил в «Los Tres Grandes» («Великая тройка») мексиканского муралисма вместе с Ороско и Сикейросом. С 1920-х годов они расписывали общественные здания, чтобы рассказывать о истории и людях Мексики после революции.'],
['«Человек на перепутье» (Man at the Crossroads) — роспись в здании RCA, Рокфеллер-центр, Нью-Йорк. Работу остановили 9 мая 1933 года, когда Ривера отказался убрать портрет Ленина, а 10 февраля 1934 года роспись сбили со стен.','В 1934 году он повторил её во Дворце изящных искусств в Мехико под названием «Человек, управляющий вселенной» — меньше по размеру, на одной стене, с новыми портретами (Рокфеллер-младший, Троцкий, Маркс, Энгельс).'],
'Он писал более гладко, чем Ороско и Сикейрос, и заполнял всё пространство повествованием; росписи в Детройте (Detroit Industry) принесли ему успех, но нью-йоркская история закрыла ему путь к американским заказам.',
['Монументальные росписи','Ленин в Рокфеллер-центре','Уничтоженная и повторённая работа','Повествование и символика'],
R+' Ривера умер в 1957 году; срок защиты зависит от страны.',
[['Open University: Рокфеллер-центр','https://www.open.edu/openlearn/history-the-arts/art-and-the-mexican-revolution/content-section-8'],['Smarthistory: Los Tres Grandes','https://smarthistory.org/mexican-muralism-los-tres-grandes-david-alfaro-siqueiros-diego-rivera-and-jose-clemente-orozco/']],['Ривера','Rivera']);
add('siqueiros','Давид Альфаро Сикейрос','David Alfaro Siqueiros','1896–1974','Мексика · муралисты',
['Сикейрос — один из основателей мексиканского муралисма и участник «Великой тройки» вместе с Риверой и Ороско. Из троих он считался самым радикальным по технике, композиции и политике.'],
['«Эхо крика» (1937) — эмаль (Duco) по дереву, 121,9 × 91,4 см, МоМА (дар Эдварда М. М. Варбурга).'],
'Сикейрос утверждал, что революционному искусству нужны революционные материалы: он отказался от фрески, использовал аэрограф и быстросохнущие синтетические краски (пироксилин) на стенах и холстах. Свой приём композиции «полиугловая перспектива» он считал ответом живописи на кинематографический монтаж.',
['Эмаль и пироксилин','Аэрограф','Полиугловая перспектива','Динамичная, трёхмерная композиция','Политическое искусство'],
R+' Сикейрос умер в 1974 году.',
[['МоМА: Эхо крика','https://www.moma.org/collection/works/80144'],['Art History Teaching Resources: Мексиканский муралисм','https://arthistoryteachingresources.org/lessons/mexican-muralism/']],['Сикейрос','Siqueiros']);
add('giacometti','Альберто Джакометти','Alberto Giacometti','1901–1966','Швейцария · скульптор и живописец',
['Джакометти (1901–1966) — скульптор и живописец, известный вытянутыми фигурами.'],
['«Аннетта» (1961) — масло по холсту, около 55 × 46 см, Фонд Джакометти. Это один из трёх бюстов, написанных в Штампе в 1961 году: лицо серое, детали намечены чёрными и белыми штрихами, фон охристый, красная куртка — единственный цвет.'],
'Широко открытый взгляд прямо перед собой напоминает коптские погребальные портреты, которыми он восхищался (по описанию Фонда).',
['Серая палитра','Фронтальный взгляд','Серая рамка по краю','Охристый фон','Красная куртка'],
R+' Самая известная работа — скульптура «Идущий человек I» (1961), проданная на Sotheby’s в Лондоне в феврале 2010 года за 65 млн фунтов (104,3 млн долларов), тогда рекорд для аукциона.',
[['Фонд Джакометти: Аннетта','https://www.fondation-giacometti.fr/en/database/175779/annette'],['Cleveland.com / AP: Walking Man','https://www.cleveland.com/world/2010/02/post_35.html']],['Джакометти','Giacometti']);
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
const byName=new Map(Object.values(B).map(a=>[a.name,a])),host=document.getElementById('view');
function fixHeading(){const page=document.getElementById('artist-area'),a=byName.get(page?.querySelector('h1')?.textContent);if(!a)return;for(const h of page.querySelectorAll('h2')){if(h.textContent==='Пять работ: рассмотри и сравни')h.textContent='Репродукция пока не подключена';}}
if(host){new MutationObserver(fixHeading).observe(host,{childList:true,subtree:true});fixHeading();}
})();

