/* artists-batch-46.js */
(()=>{'use strict';
const N='https://www.nationalgallery.org.uk/',C='https://commons.wikimedia.org/wiki/',T='https://www.museothyssen.org/en/collection/artists/butinone-bernardino/nativity';
const file='Bernardino Bergognone (c.1460-1470-1523) - The Virgin and Child with Two Angels - NG1077 - National Gallery.jpg';
const B={
bernardino_butinone:{name:'Бернардино Бутиноне',latin:'Bernardino Butinone',life:'работал в 1475 — около 1510',tag:'Италия · Тревильо и Милан, позднее кватроченто',aliases:['Бернардино Бутиноне','Бутиноне','Bernardino Butinone'],
bio:['Бутиноне происходил из Тревильо и работал в Милане. Он сотрудничал с Бернардо Дзенале; музей Тиссена относит начало их совместной работы к 1485 году. Среди его ориентиров — Мантенья, Франческо дель Косса, Косме Тура и Винченцо Фоппа.','Лондонская Национальная галерея указывает период активности 1475 — около 1510 и сообщает о двух известных подписных самостоятельных произведениях. Это не означает, что все остальные картины имеют одинаково надёжную атрибуцию.'],
technique:['«Рождество», 1493 год по паспорту Тиссена: темпера и масло по дереву, 46 × 97 см, инвентарный номер 1977.45. На фоне тёмной скальной массы ярко освещённые фигуры выделяются интенсивным цветом; богато одетый коленопреклонённый ангел составляет контраст с обнажённым Младенцем на каменистом ложе.','Пейзаж разделён центральным мотивом. Слева показано Благовестие пастухам среди гор и дороги с деревьями, справа путь приводит к городским зданиям. Вытянутый формат позволяет связать несколько пространственных и повествовательных зон.'],
innovation:'Живопись Бутиноне позволяет изучать не только влияние падуанско-феррарской выразительности, но и изменения в миланском художественном окружении. Родольфо Паллуккини увидел в пейзаже и ангеле «Рождества» интерес к Леонардо и «Мадонне в скалах»; это исследовательская интерпретация, не документ об обучении у Леонардо.',
features:['Световой контраст: фигуры ярко выступают на тёмной скале.','Интенсивный цвет: одежды ангела усиливают зрительное напряжение.','Развёрнутый пейзаж: природная местность переходит в городскую.','Несколько эпизодов: Благовестие пастухам дополняет центральное Рождество.','Вытянутый формат: композиция могла быть связана с пределлой алтаря.'],
caution:'«Рождество» принадлежит коллекции Тиссена и передано на хранение в MNAC в Барселоне: не указывай Мадрид как подтверждённое нынешнее местонахождение. Паспорт даёт 1493 год, авторский очерк обсуждает более широкий период 1490-х. Связь с пределлой — гипотеза; другие панели не идентифицированы. Лондонское «Поклонение пастухов» NG3336 музей обозначает Probably by Bernardino Butinone: его нельзя подменять бесспорно атрибутированным примером. Репродукция «Рождества» не подключена: музей публикует специальные условия использования фотографий, свободный файл для этой карточки не подтверждён.',
sources:[['Музей Тиссена: Рождество, описание и условия использования',T],['Национальная галерея: Бернардино Бутиноне',N+'artists/bernardino-butinone'],['Национальная галерея: вероятно Бутиноне, Поклонение пастухов',N+'paintings/probably-by-bernardino-butinone-the-adoration-of-the-shepherds']],works:[],
pendingWorks:[{key:'thyssen:1977.45',title:'Рождество',originalTitle:'The Nativity',date:'1493; в очерке — 1490-е',medium:'Темпера и масло по дереву; 46 × 97 см',museum:'Коллекция Тиссена-Борнемисы, на хранении в MNAC, Барселона',source:T,reason:'Открытый файл изображения и условия его использования не подтверждены'}],editorialStatus:'text_only_image_file_and_rights_pending'},
bernardino_bergognone:{name:'Бернардино Бергоньоне',latin:'Bernardino Bergognone',life:'около 1455/1460–1525',tag:'Италия · Ломбардия, позднее кватроченто',aliases:['Бернардино Бергоньоне','Бернардино Боргоньоне','Bernardino Bergognone','Bernardino Borgognone'],
bio:['Бернардино — младший брат Амброджо Бергоньоне. В 1490-х годах он был главным помощником брата в важных ломбардских проектах. Сходство манеры и совместная практика требуют различать авторов, а не собирать все работы под одной фамилией.','Национальная галерея связывает «Мадонну с Младенцем и двумя ангелами» с Бернардино и указывает его имя в буквах на краю плаща Марии возле выступающей туфли. Музей характеризует его манеру как ещё более традиционную и сильнее связанную с Фоппой, чем манеру Амброджо.'],
technique:['Масло по дереву; 92,7 × 57,5 см, NG1077, 1490–1495 годы. Мария поддерживает Младенца одной рукой, другой держит открытую книгу. Богато резной трон, золотые нимбы и музицирующие ангелы соединяют материнскую близость с образом Царицы Небесной.','Тонкая золотая вышивка обрамляет плащ Марии, горловину и запястья одежды Младенца. Почти прозрачный платок вокруг головы и плеч даёт иной эффект, чем плотные ткани и резьба трона. Красный крест на нимбе Христа напоминает о будущем Распятии.'],
innovation:'Пример помогает понять, как художник внутри семейной мастерской создаёт узнаваемое молитвенное изображение без обязательного разрыва с традицией. Драгоценная отделка, музыка и спокойный жест представляют Марию одновременно доступной заступницей и небесной царицей.',
features:['Поддерживающий жест: Мария удерживает стоящего на коленях Младенца.','Открытая книга: чтение включено в материнскую сцену.','Два музыканта: ангелы создают образ небесного прославления.','Золотая отделка: нимбы и вышивка работают вместе с богатым троном.','Почти прозрачный платок: тонкая ткань контрастирует с плотными одеждами.'],
caution:'Не путай Бернардино с Амброджо Бергоньоне из батча 45. В старых описаниях группы NG1077 сохраняются осторожные формулировки атрибуции и иная датировка; текущая самостоятельная карточка NG1077 называет Бернардино, 1490–1495 годы и надпись с именем. Панель позднее объединяли с двумя сценами Амброджо около 1501 года, но они не были созданы как единый триптих. Первоначальная функция этой Мадонны — часть полиптиха или самостоятельный молитвенный образ — не установлена. Даты в имени файла Commons не заменяют актуальные музейные даты. Полную страницу файла получить не удалось: статус Public Domain взят из индексируемой записи. Визуальный просмотр и браузерная загрузка не проверены.',
sources:[['Национальная галерея: Бернардино Бергоньоне',N+'artists/bernardino-bergognone'],['Национальная галерея: Мадонна с Младенцем и двумя ангелами, NG1077',N+'paintings/bernardino-bergognone-the-virgin-and-child-with-two-angels'],['Национальная галерея: история составной группы NG1077',N+'paintings/ambrogio-bergognone-the-agony-in-the-garden'],['Commons: конкретный файл NG1077 и статус прав',C+'File:'+file.replace(/ /g,'_')]],
works:[{key:'ng:NG1077',title:'Мадонна с Младенцем и двумя ангелами',originalTitle:'The Virgin and Child with Two Angels',date:'1490–1495',medium:'Масло по дереву; 92,7 × 57,5 см',museum:'Национальная галерея, Лондон',source:N+'paintings/bernardino-bergognone-the-virgin-and-child-with-two-angels',image:C+'Special:FilePath/'+encodeURIComponent(file)+'?width=800',zoom:C+'Special:FilePath/'+encodeURIComponent(file)+'?width=1600',imageSource:C+'File:'+file.replace(/ /g,'_'),license:'Public Domain по индексируемой странице Commons; полный текст страницы получить не удалось',imageVisuallyReviewed:false,look:'Сопоставь поддерживающую руку Марии, открытую книгу и музицирующих ангелов. Затем найди туфлю у края плаща: рядом музей отмечает буквы имени художника. Сравни прозрачный платок с золотой вышивкой и резным троном.'}],editorialStatus:'museum_sources_indexed_image_rights_full_file_page_and_browser_check_pending'}
};
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

;
/* artists-batch-47.js */
(()=>{'use strict';
const N='https://www.nationalgallery.org.uk/',C='https://commons.wikimedia.org/wiki/';
const bs=N+'paintings/giovanni-antonio-boltraffio-the-virgin-and-child',ms=N+'paintings/marco-d-oggiono-portrait-of-a-man-aged-20-the-archinto-portrait';
const B={
giovanni_antonio_boltraffio:{name:'Джованни Антонио Больтраффио',latin:'Giovanni Antonio Boltraffio',life:'около 1467–1516',tag:'Италия · Милан, круг Леонардо, рубеж XV–XVI веков',aliases:['Джованни Антонио Больтраффио','Джованни Антонио Больтраффьо','Больтраффио','Болтраффио','Giovanni Antonio Boltraffio'],
bio:['Больтраффио — один из наиболее одарённых учеников Леонардо да Винчи. К 1498 году у него уже была самостоятельная практика: он создавал алтари, портреты и небольшие молитвенные картины. Ученичество не означает, что все его произведения — копии учителя.','«Мадонна с Младенцем» NG728, вероятно около 1493–1499 годов, связана с художественными поисками миланского окружения Леонардо. Музей отмечает и собственные подготовительные исследования женских голов у Больтраффио.'],
technique:['Масло по ореховой доске; 92,7 × 67,3 см. Фронтальная фигура Марии и крупный Младенец образуют устойчивый треугольник. Почти натуральный масштаб и низкая точка зрения придают группе телесную весомость. Нежные нимбы не подавляют впечатление живых людей.','Зелёная завеса отделяет фигуры от пейзажа и работает как почётная ткань. Почти прозрачный вышитый платок контрастирует с плотной красной одеждой. Исследование связующих обнаружило темперу с примесью масла в некоторых подмалёвках и масло, в том числе ореховое, в верхних слоях: краткое «масло» не описывает весь процесс.'],
innovation:'Привычная сцена объединяет несколько смыслов: богато одетая Мария — Царица Небесная, открытая грудь напоминает о кормлении, а расположение крупного тела сына поперёк её коленей может вызвать ассоциацию с будущей Пьетой. Эти смыслы возникают внутри убедительной телесной группы, а не через обилие отдельных символов.',
features:['Монументальный треугольник: Мария и Младенец составляют цельную массу.','Сдержанные нимбы: святость выражена без броского золотого убранства.','Взгляд к зрителю: Христос отворачивается от матери и смотрит наружу.','Почётная завеса: зелёная ткань отделяет фигуры от пейзажа.','Тонкие фактуры: прозрачный платок сопоставлен с плотной одеждой.'],
caution:'Не путай авторскую NG728 с «Мадонной с Младенцем» NG2496 и «Нарциссом» NG2673: музей относит обе последние работы к последователю Больтраффио. Картина NG728 не показывает обычную «Мадонну Смирения», сидящую на земле. Возможное назначение центральной панелью большого алтаря и ассоциация с Пьетой — интерпретации музея, не доказанные сведения о заказе. Файл Boltraffio 014.jpg изображает портрет Джироламо Касио, а не эту Мадонну; он исключён. Правильный файл-кандидат WGA2391 найден, но полная страница с условиями использования недоступна: репродукция не подключена.',
sources:[['Национальная галерея: Больтраффио',N+'artists/giovanni-antonio-boltraffio'],['Национальная галерея: Мадонна с Младенцем, NG728',bs],['Technical Bulletin: анализ связующих NG728',N+'media/15641/white_pilc1996.rtf'],['Национальная галерея: Нарцисс, последователь Больтраффио',N+'paintings/follower-of-giovanni-antonio-boltraffio-narcissus']],works:[],pendingWorks:[{key:'ng:NG728',title:'Мадонна с Младенцем',date:'вероятно около 1493–1499',source:bs,candidateImageSource:C+'File:Giovanni_Antonio_Boltraffio_-_Virgin_and_Child_-_WGA2391.jpg',reason:'Музейный номер совпадает; полная страница файла, условия использования и визуальное соответствие не проверены'}],editorialStatus:'text_only_image_file_and_rights_pending'},
marco_d_oggiono:{name:'Марко д’Оджоно',latin:"Marco d'Oggiono",life:'документирован с 1487; умер в 1524',tag:'Италия · Милан, круг Леонардо, рубеж XV–XVI веков',aliases:['Марко д’Оджоно',"Марко д'Оджоно",'Марко д’Оджонно','Марко д’Оггионо',"Marco d'Oggiono",'Marco d’Oggiono'],
bio:['Марко д’Оджоно работал под сильным влиянием Леонардо да Винчи и обучался в его мастерской. Национальная галерея осторожно предполагает, что именно он назван Марко в записи о мастерской Леонардо 1490 года. Начало документированной деятельности в 1487 году — не год рождения.','Датированный 1494 годом «Портрет двадцатилетнего мужчины» NG1665 служит важным ориентиром для изучения раннего миланского круга Леонардо. Внешние сходства с «Прекрасной Ферроньерой» помогают понять связь двух манер, но не превращают картину Марко в работу Леонардо.'],
technique:['Масло по ореховой доске; 53,3 × 38,1 см. Подготовка необычна: привычного гипсового грунта нет, вместо него нанесён толстый слой свинцовых белил в масле. В тенях использовано много угольной чёрной, что затрудняет исследование подрисунка.','Пепельный тон кожи частично связан с первоначальной серой краской теней, но усилился из-за выцветания красного лака. Синий дублет написан дорогим ультрамарином поверх азурита; побеление верхнего слоя сделало одежду более плоской. Почти чёрная шапка первоначально могла иметь насыщенный пурпурный цвет.'],
innovation:'Портрет соединяет новые композиционные решения — парапет, разворот плеч, взгляд мимо зрителя — с экспериментами над красочным слоем. Его нынешний вид одновременно свидетельствует об авторском замысле и старении материалов. Это полезный пример того, почему нельзя определять манеру художника только по сегодняшней цветной репродукции.',
features:['Парапет-порог: рука лежит на мраморной полке перед фигурой.','Разворот плеч: корпус не показан строго фронтально.','Взгляд вдаль: модель смотрит мимо зрителя.','Тёмный фон: лицо и костюм отделены от окружающего пространства.','Свиток с данными: возраст двадцать лет и дата 1494 зафиксированы надписью.'],
caution:'«Портрет Аркинто» — историческое название по месту в палаццо Аркинто, а не доказанное имя модели. Идентификация как Франческо ди Бартоломео Аркинто не подтверждена. Монограмму нельзя уверенно читать как подпись Амброджо де Предиса: часть штрихов может быть поздней. Текущий паспорт называет Марко д’Оджоно, но в описании ранний портрет характеризуется как вероятная атрибуция — эта осторожность сохранена. Не принимай выцветшую кожу, побелевший синий и потемневшую шапку за полностью намеренную палитру. Репродукция пока не подключена: конкретный файл найден, полная страница и права не проверены.',
sources:[['Национальная галерея: Марко д’Оджоно',N+'artists/marco-d-oggiono'],['Национальная галерея: Портрет Аркинто, NG1665, техническое исследование',ms],['Technical Bulletin: миланская практика 1490-х',N+'research/publications/technical-bulletin/painting-practice-in-milan-in-the-1490s-the-influence-of-leonardo']],works:[],pendingWorks:[{key:'ng:NG1665',title:'Портрет двадцатилетнего мужчины («Портрет Аркинто»)',date:'1494',source:ms,candidateImageSource:C+"File:Marco_d'Oggiono_-_The_Archinto_Portrait_(National_Gallery,_London).jpg",reason:'Конкретный файл найден; полная страница, условия использования и визуальное соответствие не проверены'}],editorialStatus:'text_only_image_file_and_rights_pending'}
};
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

