/* artists-batch-50.js */
(()=>{'use strict';
const N='https://www.nationalgallery.org.uk/',C='https://commons.wikimedia.org/wiki/',B={};
function add(id,name,latin,life,tag,aliases,bio,technique,innovation,features,caution,sources,pendingWorks,works=[]){B[id]={name,latin,life,tag,aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources,works,pendingWorks,editorialStatus:works.length?'museum_sources_commons_file_rights_checked_browser_check_pending':'text_only_image_file_and_rights_pending'};}
const fs=N+'paintings/francesco-francia-saint-anne-with-the-virgin-and-four-saints',cs=N+'paintings/giovanni-battista-cima-da-conegliano-the-incredulity-of-saint-thomas',ms=N+'paintings/bartolomeo-montagna-the-virgin-and-child-1',bs=N+'paintings/marco-basaiti-the-virgin-and-child',ls=N+'paintings/lorenzo-lotto-portrait-of-a-woman-inspired-by-lucretia';
add('francesco_francia','Франческо Франча','Francesco Francia','около 1447–1517','Италия · Болонья, рубеж XV–XVI веков',['Франча','Франческо Райболини','Francesco Raibolini'],
['Франческо Райболини, известный как Франча, происходил из Болоньи. Сначала он обучался ювелирному делу: в гильдии золотых дел мастеров записан в 1482 году, как живописец документирован в 1486-м.','Его ранняя манера связана с Лоренцо Костой, а мягкий зрелый стиль — прежде всего с Перуджино. Франча был влиятелен при жизни и широко подражаем в Болонье, хотя позднее его затмила слава следующего поколения.'],
['Алтарь Буонвизи, 1510–1512, был создан для семейной капеллы в Сан-Фредиано в Лукке. В основной панели NG179 Мария и Анна сидят на престоле, а Младенец тянется к плоду, который предлагает бабушка. По сторонам стоят Себастьян, Павел, Лаврентий и Бенедикт.','Основная панель: масло, первоначально по дереву, переведено на холст; 195 × 180,5 см. В верхней полукруглой «Пьете» NG180 постаревшая Мария оплакивает сына. Широкие трещины и утраты показывают, что нынешняя поверхность не полностью передаёт первоначальное мягкое письмо.'],
'Два яруса связывают детство и будущую жертву Христа. Задумчивость молодой Марии внизу получает продолжение в скорби пожилой матери наверху. Разбор алтаря как целого раскрывает больше, чем изолированное сравнение лиц и красок.',
['Семейная группа: Анна, Мария и Младенец объединены на престоле.','Передача плода: жест связывает три поколения.','Святые по сторонам: фигуры упорядочивают центральную сцену.','Мягкость образов: зрелая манера связана с Перуджино.','Два времени: детство внизу сопоставлено с оплакиванием наверху.'],
'NG179 — основная панель, NG180 — отдельная верхняя люнета; не называй их одной доской. Современная общая рама изготовлена в XIX веке. Первоначальная основа NG179 деревянная, нынешняя — холст после перевода. «Мадонна с двумя святыми» имеет оговорку о мастерской, а лондонская «Мадонна с ангелом» — подделка XIX века по Франче, не его оригинал. Файл NG179 найден, но полную страницу и права проверить не удалось; репродукция не подключена.',
[['Национальная галерея: Франча',N+'artists/francesco-francia'],['Национальная галерея: основная панель NG179',fs],['Национальная галерея: алтарь как целое',N+'paintings/francesco-francia-the-buonvisi-altarpiece'],['Национальная галерея: Пьета NG180',N+'paintings/francesco-francia-the-pieta']],
[{key:'ng:NG179',title:'Богоматерь с Младенцем, святой Анной, Иоанном Крестителем и четырьмя святыми',date:'1510–1512',source:fs,candidateImageSource:C+'File:Francesco_Francia_(c.1450-1517)_-_The_Virgin_and_Child_with_Saint_Anne_and_Other_Saints_-_NG179_-_National_Gallery.jpg',reason:'Файл основной панели найден; полная страница, права и визуальное соответствие не проверены'}]);
add('cima_da_conegliano','Чима да Конельяно','Giovanni Battista Cima da Conegliano','около 1459/1460 — около 1517/1518','Италия · Венеция и Венето, рубеж XV–XVI веков',['Джованни Баттиста Чима да Конельяно','Чима','Cima da Conegliano'],
['Чима был одним из наиболее продуктивных мастеров Венеции конца XV века. Национальная галерея отмечает свыше тридцати сохранившихся алтарей. Искусство Джованни Беллини оказало на него определяющее влияние, но формальное ученичество не доказано.','«Неверие святого Фомы» заказало братство, управлявшее четырьмя госпиталями в Портогруаро. Решение о заказе принято 28 мая 1497 года; выплаты зафиксированы с 1502-го, установка состоялась в 1504-м, окончательный расчёт — лишь в 1509-м после судебных действий художника.'],
['NG816, около 1502–1504: масло, первоначально по дереву, вероятно тополю, переведено на холст; 294 × 199,4 см. Фома касается раны воскресшего Христа в окружении апостолов.','Сначала одежды написаны крупными плоскими цветовыми полями; тональные переходы складок получены разной толщиной прозрачных лессировок. Широкая палитра и драгоценная глубина цвета связаны с возможностями Венеции как центра торговли пигментами.'],
'Цвет и светотень превращают богословское доказательство Воскресения в зримый телесный опыт. Сохранившиеся счета позволяют сопоставить художественный результат с экономикой заказа: работа не возникла как свободное вдохновение вне отношений с братством.',
['Касание раны: главный жест связывает Христа и Фому.','Реакции апостолов: окружающие фигуры усиливают значимость события.','Глубина цвета: складки моделируются лессировками.','Свет справа: направление могло учитывать место установки.','Два картеллино: один связан с художником, другой с руководителями братства.'],
'1497 — решение о заказе, 1504 — установка, 1509 — окончательная выплата: не смешивай эти даты с паспортной датировкой около 1502–1504. В написанном листке есть подпись и дата 1504, но музей считает цифры позднейшим добавлением. Объяснение правого света положением алтаря предположительно. Не считай нынешний холст исходной основой или нынешнюю раму ренессансной: она английская XIX века. Свободный конкретный файл изображения пока не проверен.',
[['Национальная галерея: Чима',N+'artists/giovanni-battista-cima-da-conegliano'],['Национальная галерея: NG816, техника и счета братства',cs]],
[{key:'ng:NG816',title:'Неверие святого Фомы',date:'около 1502–1504',source:cs,reason:'Музейный оригинал проверен; конкретный свободный файл репродукции не подтверждён'}]);
add('bartolomeo_montagna','Бартоломео Монтанья','Bartolomeo Montagna','год рождения не установлен; умер в 1523','Италия · Виченца и венецианская традиция, кватроченто',['Монтанья'],
['Монтанья связан с Виченцей и венецианской живописной традицией. О его обучении известно мало: работа в мастерской Беллини возможна, но не доказана.','Для разбора выбрана ранняя «Мадонна с Младенцем» NG802, вероятно около 1485–1487 годов. Сочетание простых объёмных форм и подробно населённого пейзажа позволяет увидеть связи с Беллини и возможное влияние Антонелло да Мессины.'],
['Масло по дереву; 64,8 × 54,6 см. Младенец сидит на огромной книге, вероятно Библии. Мария и Христос держат по вишне. Музей связывает книгу с исполнением ветхозаветных пророчеств, плод — с раем.','Широкий треугольник синего плаща и твёрдо очерченные части тела придают формам весомость. Укороченный большой палец Марии показан почти с торца — пример ракурса. На заднем плане фантастическая скальная арка соседствует с розовой церковью, лагуной и гондолами.'],
'Священная группа приближена к зрителю через мраморный парапет, а за ней разворачивается подробный североитальянский мир. Геометрическая ясность фигур не исключает тонкого рассказа в пейзаже; предметы соединяют телесную близость с богословским смыслом.',
['Синий треугольник: плащ организует крупную массу.','Твёрдые формы: тело строится отчётливыми объёмами.','Младенец на книге: предмет участвует в смысле образа.','Две вишни: повтор плода связывает мать и сына.','Населённый пейзаж: храм, лагуна и гондолы дополняют скальную арку.'],
'1459 в музейном справочнике означает «жил в 1459», не подтверждённый год рождения. Связь с мастерской Беллини и влияние Антонелло — предположения. Книга названа Библией вероятностно, символическое прочтение не является бытовым описанием младенца. Не путай деревянную NG802 с переведённой на холст NG1098 или фреской NG1696, имеющей вероятную атрибуцию. Проверенная репродукция NG802 не подобрана.',
[['Национальная галерея: Монтанья',N+'artists/bartolomeo-montagna'],['Национальная галерея: Мадонна NG802',ms],['Национальная галерея: другая Мадонна NG1098',N+'paintings/bartolomeo-montagna-the-virgin-and-child'],['Национальная галерея: вероятная атрибуция фрески',N+'paintings/probably-by-bartolomeo-montagna-the-virgin-and-child']],
[{key:'ng:NG802',title:'Мадонна с Младенцем',date:'вероятно около 1485–1487',source:ms,reason:'Музейная работа проверена; конкретный свободный файл не подтверждён'}]);
add('marco_basaiti','Марко Базаити','Marco Basaiti','работал в 1496–1530','Италия · Венеция, рубеж XV–XVI веков',['Марко Базайти','Базаити','Marco Baxaiti'],
['Базаити, вероятно, имел греческое происхождение; место рождения — Венеция или Фриули — не установлено однозначно. Сохранилось много подписанных работ, иногда датированных; написание подписи варьируется, часто как Baxaiti.','Небольшая «Мадонна с Младенцем» NG2499 относится к ранним работам, около 1496–1505 годов. Её тип — фигуры перед пейзажем и частично закрывающей его завесой — был распространён Беллини и его мастерской.'],
['Масло по установленной тополевой основе; 62,9 × 47 см. Мария поддерживает локоть Младенца, который пытается встать на мраморный выступ и благословляет правой рукой. Оба смотрят вниз, вероятно в расчёте на высокую развеску.','Плащ Марии спускается через парапет в пространство зрителя. Тёмно-зелёная ткань частично закрывает горный пейзаж. Эти пороги одновременно отделяют священный мир и создают ощущение, что он находится в пределах досягаемости.'],
'Беллиниевский тип приспособлен к частной молитве: небольшой размер и поддерживающий жест делают священную группу близкой. Пространственная иллюзия работает вместе с материнским взаимодействием, а не только с перспективой далёких гор.',
['Поддержка локтя: материнский жест показан конкретно.','Благословение: правая рука Младенца обращена к зрителю.','Взгляд вниз: композиция предполагает положение выше глаз.','Спадающий плащ: ткань пересекает мраморный порог.','Зелёная завеса: пейзаж частично закрыт позади фигур.'],
'1496–1530 — период деятельности, не жизни. Греческое происхождение и место рождения предположительны. Сходство с Беллини не доказывает конкретное ученичество. Подпись слева на парапете частично утрачена при обрезке нижнего края до поступления в музей. Назначение для домашней молитвы и обращение к женской аудитории — вероятные объяснения, не известный заказ. Конкретный файл изображения и права не подтверждены.',
[['Национальная галерея: Базаити',N+'artists/marco-basaiti'],['Национальная галерея: NG2499, подпись и композиция',bs]],
[{key:'ng:NG2499',title:'Мадонна с Младенцем',date:'около 1496–1505',source:bs,reason:'Музейный оригинал проверен; конкретный свободный файл и права не подтверждены'}]);
const lf='Lorenzo Lotto - Portrait of a Woman inspired by Lucretia - Google Art Project.jpg';
add('lorenzo_lotto','Лоренцо Лотто','Lorenzo Lotto','около 1480–1556/1557','Италия · Венеция, Бергамо и Марке, чинквеченто',['Лотто'],
['Лотто работал в разных центрах Италии и создавал как религиозные картины, так и портреты. Его поздние произведения отличаются напряжённой религиозностью.','В «Портрете женщины, вдохновлённой примером Лукреции» уверенная модель держит рисунок античной героини. Имена модели и героини, вероятно, совпадали, но достоверно установить личность женщины не удалось.'],
['NG4256, около 1530–1533: масло по холсту; 96,5 × 110,6 см по музейному каталогу. Прямой взгляд и решительные жесты выделяют модель. Богатая одежда сопоставлена с небольшим рисунком внутри картины и латинской надписью на отдельном листке.','Рентгенография и инфракрасная съёмка выявили первоначально яркий полосатый фон, позднее изменённый художником. Изображение на листе также перерабатывалось: под тушевым рисунком найдена цветная женская фигура с иначе повёрнутой головой.'],
'Портрет показывает не только внешность, но и публично заявленный образ добродетели. Нарисованная героиня становится аргументом, который модель предъявляет зрителю; при этом изменения фона и рисунка раскрывают, как тщательно выстраивалось высказывание.',
['Прямой взгляд: модель удерживает внимание зрителя.','Активный жест: рука указывает на смысловые предметы.','Рисунок внутри картины: античная история введена как изображение.','Роскошный костюм: ткани и украшения показывают социальную роль.','Листок с текстом: надпись связывает портрет с Лукрецией.'],
'Это не буквальное изображение римской Лукреции и не установленный портрет Лукреции Валье. Современный паспорт даёт около 1530–1533, каталог — около 1530–1532. История античной героини связана с сексуальным насилием и самоубийством: надпись отражает нормы прошлого, а не вину пострадавшей или необходимость следовать её поступку. Копии и рисунок внутри картины не заменяют само полотно NG4256. Страница файла и PD-Art проверены; визуальное соответствие и браузерная загрузка не проверены.',
[['Национальная галерея: Лотто',N+'artists/lorenzo-lotto'],['Национальная галерея: портрет NG4256',ls],['Музейный каталог: размеры и личность модели',N+'paintings/catalogues/penny-2004/portrait-of-a-woman-inspired-by-lucretia'],['Technical Bulletin: изменения композиции',N+'research/publications/technical-bulletin/two-paintings-by-lorenzo-lotto-in-the-national-gallery'],['Commons: файл NG4256 и PD-Art',C+'File:'+lf.replace(/ /g,'_')]],[],
[{key:'ng:NG4256',title:'Портрет женщины, вдохновлённой примером Лукреции',originalTitle:'Portrait of a Woman inspired by Lucretia',date:'около 1530–1533',medium:'Масло по холсту; 96,5 × 110,6 см по каталогу',museum:'Национальная галерея, Лондон',source:ls,image:C+'Special:FilePath/'+encodeURIComponent(lf)+'?width=800',zoom:C+'Special:FilePath/'+encodeURIComponent(lf)+'?width=1600',imageSource:C+'File:'+lf.replace(/ /g,'_'),license:'PD-Art по полной странице Commons; Commons предупреждает о возможных ограничениях вне США',imageVisuallyReviewed:false,look:'Сопоставь прямой взгляд модели, её жест и маленький рисунок Лукреции. Отдели живую женщину от героини на бумаге. Представь, как первоначальный яркий полосатый фон мог изменить восприятие этого высказывания.'}]);
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

