/* artists-batch-51.js */
(()=>{'use strict';
const N='https://www.nationalgallery.org.uk/',C='https://commons.wikimedia.org/wiki/',B={};
function add(id,name,latin,life,tag,aliases,bio,technique,innovation,features,caution,sources,pending){B[id]={name,latin,life,tag,aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources,works:[],pendingWorks:[pending],editorialStatus:'text_only_image_file_and_rights_pending'};}
const moretto=N+'paintings/moretto-da-brescia-portrait-of-count-fortunato-martinengo',romanino=N+'paintings/girolamo-romanino-the-nativity',moroni=N+'paintings/giovanni-battista-moroni-the-tailor-il-tagliapanni',pordenone=N+'paintings/giovanni-antonio-pordenone-saint-bonaventure',dosso=N+'paintings/dosso-dossi-the-adoration-of-the-kings';
add('moretto_da_brescia','Моретто да Брешиа','Moretto da Brescia','около 1498–1554','Италия · Брешиа, чинквеченто',['Моретто','Алессандро Бонвичино','Alessandro Bonvicino'],
['Моретто и Романино были ведущими мастерами Брешии первой половины XVI века. Большинство его произведений — крупные религиозные холсты для города и окрестностей; портреты встречаются реже.','Портретному мастерству у него учился Морони. «Портрет графа Фортунато Мартиненго», около 1540–1545 годов, показывает гуманиста, основателя брешианской Академии сомневающихся.'],
['Масло по холсту; 114 × 94,4 см, NG299. Граф опирается головой на руку, локтем — на шёлковые подушки. Меховая подкладка, красный бархат и золотой дамаст создают драгоценную, но тесную среду.','На столе лежат античные монеты, перчатки и бронзовый светильник в форме ноги. Серая мраморная стена ограничивает глубину, а направленный вдаль взгляд противопоставлен подчеркнуто ощутимым предметам.'],
'Портрет показывает одновременно общественное положение и внутреннее созерцание. Поза связана с традицией меланхолии, а древности — с учёностью; сочетание не позволяет свести образ к демонстрации богатства или к медицинскому диагнозу.',
['Голова на руке: традиционная поза меланхолии.','Взгляд вдаль: модель не вступает в прямой зрительный контакт.','Драгоценные фактуры: мех, бархат и золотая ткань сопоставлены.','Античные предметы: монеты и светильник указывают на круг интересов.','Сжатое пространство: мраморная стена усиливает сосредоточенность.'],
'Греческий девиз означает примерно «Увы, я слишком сильно желаю»; неизвестно, желает ли граф знания, любви или путешествия. Заказ перед паломничеством 1541 года возможен, но не доказан; датировка около 1540–1545 выведена по костюму. Мех определяется как рысь или снежный барс, а не однозначно. Не путай Фортунато с другими Мартиненго или поздними названиями портретов. Свободный файл именно NG299 и условия его использования пока не подтверждены.',
[['Национальная галерея: Моретто',N+'artists/moretto-da-brescia'],['Национальная галерея: Фортунато Мартиненго, NG299',moretto]],
{key:'ng:NG299',title:'Портрет графа Фортунато Мартиненго',date:'около 1540–1545',medium:'Масло по холсту; 114 × 94,4 см',source:moretto,reason:'Музейная работа и личность модели проверены; конкретный свободный файл репродукции не подтверждён'});
add('girolamo_romanino','Джироламо Романино','Girolamo Romanino','около 1484 — около 1560','Италия · Брешиа и Северная Италия, чинквеченто',['Романино'],
['Романино работал во фреске, алтарной живописи и иногда портрете в Брешии, Падуе, Кремоне и Тренто. По сравнению с Моретто его фигуры и пейзажи отличаются усиленной выразительностью.','«Рождество», около 1524 года, — центральная панель главного алтаря Сан-Алессандро в Брешии. За алтарь отвечало братство Тела Христова; изображение Младенца находилось над дарохранительницей.'],
['NG297.1: масло по дереву, вероятно тополю; 265 × 117,2 см. В облаках сохранились отпечатки пальцев и ладони: художник наносил краску не только кистью. Пейзаж местами написан по сырому, а густые участки краски демонстрируют эксперименты с фактурой.','Мария и Иосиф поклоняются Младенцу на покрытой тканью корзине. Вверху движется группа маленьких ангелов. Синий цвет одежды потемнел из-за изменения смальты; золотые лилии на плаще Марии связаны со святым Александром.'],
'Живое движение красочного слоя соединено с богословской программой алтаря: рождение Христа внизу первоначально сопоставлялось с мёртвым Спасителем наверху. Традиционная многочастная форма не препятствовала смелому обращению с маслом.',
['Подвижные облака: ангелы и краска создают ощущение движения.','Следы руки: в красочном слое различимы отпечатки пальцев и ладони.','Густая фактура: отдельные участки выступают над поверхностью.','Золотые лилии: орнамент связан с посвящением храма.','Связь ярусов: Рождество входило в более широкий алтарный рассказ.'],
'Нынешняя панель — не весь полиптих. Утрачены рама Стефано Ламберти и первоначальное завершение; отождествление сохранившихся створок предположительно. Около 1524 — дата панели, весь алтарь, вероятно, завершён в 1525-м. Потемневший синий не равен первоначальному цветовому замыслу. Не путай NG297.1 с повторениями Франческо Праты и Каллисто Пьяццы. «Пегас и музы» имеет лишь возможную атрибуцию Романино. Репродукция не подключена: свободный файл не проверен.',
[['Национальная галерея: Романино',N+'artists/girolamo-romanino'],['Национальная галерея: Рождество, NG297.1',romanino],['Национальная галерея: реконструкция полного алтаря',N+'paintings/girolamo-romanino-high-altarpiece-s-alessandro-brescia']],
{key:'ng:NG297.1',title:'Рождество — центральная панель алтаря Сан-Алессандро',date:'около 1524',medium:'Масло по дереву, вероятно тополю; 265 × 117,2 см',source:romanino,reason:'Музейный оригинал проверен; конкретная свободная репродукция не подтверждена'});
add('giovanni_battista_moroni','Джованни Баттиста Морони','Giovanni Battista Moroni','1520/1524–1579 по Национальной галерее','Италия · Бергамо и Альбино, чинквеченто',['Морони'],
['Морони учился у Моретто и работал в Брешии, Тренто и Бергамо, позднее вернулся в родной Альбино. Он писал знать, духовенство и образованных профессионалов.','«Портной», 1565–1570, относится к поздней карьере: человек словно прерывает работу и реагирует на появление зрителя. Это художественно построенное впечатление момента, а не буквальный снимок мастерской.'],
['Масло по холсту; 99,5 × 77 см, NG697. Свет сверху слева и диагональ тени направляют взгляд от лица через левую руку к ткани. Белые меловые линии на чёрной материи сопоставлены с кремовым камзолом и красными штанами.','Морони работал непосредственно с натуры без подготовительных рисунков. Волоски у виска и борода местами написаны по сырому, телесные участки тонки и показывают зерно холста. Позднее письмо мягче и атмосфернее ранней блестящей чёткости.'],
'Портрет подчёркивает достоинство профессионального навыка: модель держит ножницы и при этом демонстрирует высокий социальный статус. Непосредственный взгляд и остановленное действие превращают зрителя в участника встречи.',
['Прямой взгляд: мастер будто заметил вошедшего посетителя.','Ножницы над тканью: работа приостановлена в конкретном действии.','Меловые линии: намеченный крой делает профессию видимой.','Мягкая фактура: письмо по сырому оживляет лицо и волосы.','Пояс для шпаги: деталь сообщает о социальном положении.'],
'Личность мужчины неизвестна; возможны торговец тканями или старшина цеха, а не только рядовой портной. Датировка 1565–1570 приблизительна. Холст расширили на два-три сантиметра с каждой стороны в 1863 году, нынешняя рамка не тождественна первоначальному кадрированию. Даты художника даны по текущему паспорту Национальной галереи; в других выставочных материалах встречается 1521–1580. Конкретный файл Google Art Project найден, но полная страница и права не проверены; репродукция не подключена.',
[['Национальная галерея: Морони',N+'artists/giovanni-battista-moroni'],['Национальная галерея: Портной, NG697, техника и социальный статус',moroni],['Wikidata: соответствие файла и картины','https://www.wikidata.org/wiki/Q5561848']],
{key:'ng:NG697',title:'Портной («Il Tagliapanni»)',date:'1565–1570',medium:'Масло по холсту; 99,5 × 77 см',source:moroni,candidateImageSource:C+"File:Giovanni_Battista_Moroni_-_The_Tailor_('Il_Tagliapanni')_-_Google_Art_Project.jpg",reason:'Конкретный файл сопоставлен с картиной; полная страница файла, права и визуальное соответствие не проверены'});
add('giovanni_antonio_pordenone','Джованни Антонио Порденоне','Giovanni Antonio Pordenone','работал в 1504; умер в 1539','Италия · Фриули и Венеция, чинквеченто',['Порденоне','Il Pordenone'],
['Порденоне происходил из Фриули и работал в разных областях Северной Италии. В Венеции он соперничал с Тицианом; его сценам свойственны крупные фигуры и сильные ракурсы.','«Святой Бонавентура», вероятно 1530–1535, сохранился из потолка Скуолы Сан-Франческо-аи-Фрари в Венеции. Его первоначальная функция — часть девятичастного ансамбля, а не отдельный небольшой молитвенный образ.'],
['Масло по дереву; 29,8 × 29,8 см, NG4038. Святой указывает вверх — первоначально в сторону центрального изображения Франциска, получающего стигматы. Красная кардинальская шляпа висит на стене за ним.','Четыре евангелиста занимали квадратные угловые панели, четыре францисканских святых — восьмиугольные отделения вокруг центрального образа. Жесты и взгляд рассчитаны на целое и на рассматривание потолка снизу.'],
'Фигура связывает небольшой фрагмент с утраченным архитектурным пространством. Для понимания движения руки нужно восстановить соседство панелей: художественная выразительность зависит не только от собственного поля доски.',
['Указующая рука: жест направлен к центральному образу.','Кардинальская шляпа: атрибут помогает узнать святого.','Потолочная функция: произведение рассчитано на взгляд снизу.','Геометрические отделения: квадратные и восьмиугольные части образуют систему.','Францисканская программа: выбор святых объединяет ансамбль.'],
'1504 — год активности, не рождения. Не называй Бонавентуру единственным святым потолка: первоначально было девять изображений. Центральная панель Франциска утрачена; часть других находится в Будапеште, святой Людовик Тулузский — в Лондоне. Датировка вероятностна и основана на сравнении со стилем работ начала 1530-х. «Женщина у окна» NG2146 раньше приписывалась Порденоне, теперь музей называет североитальянского анонимного автора. Свободное изображение NG4038 пока не проверено.',
[['Национальная галерея: Порденоне',N+'artists/giovanni-antonio-pordenone'],['Национальная галерея: Бонавентура, NG4038, состав потолка',pordenone],['Национальная галерея: снятая атрибуция NG2146',N+'paintings/italian-north-woman-at-a-window']],
{key:'ng:NG4038',title:'Святой Бонавентура — фрагмент потолка',date:'вероятно 1530–1535',medium:'Масло по дереву; 29,8 × 29,8 см',source:pordenone,reason:'Музейная атрибуция и функция проверены; свободный файл репродукции не подтверждён'});
add('dosso_dossi','Доссо Досси','Dosso Dossi','около 1486–1542','Италия · Феррара, чинквеченто',['Джованни ди Лутери','Giovanni di Luteri'],
['Доссо и его брат Баттиста были ведущими живописцами Феррары начала XVI века. С 1514 года Доссо работал преимущественно при дворе д’Эсте, создавая мифологические и поэтические картины, портреты, фрески и религиозные сцены.','Он развивал живописные поиски Джорджоне и Тициана, особенно в пейзаже. Около 1527 года усилился его интерес к мощным контрастам света и тени и необычным атмосферным эффектам.'],
['«Поклонение волхвов», около 1527–1529: масло по дереву, вероятно тополю; 85,1 × 108 см, NG3924. Необычная ночная сцена освещена огромной луной с розовым ореолом, пересечённой тучами и веткой дерева.','Золотые отсветы выделяют город и края растительности. В краске у листвы, в жёлтом луны и на руке Марии видны отпечатки пальцев, вероятно художника. За священной группой не природная пещера, а античная арка, заросшая растениями.'],
'Ночной пейзаж становится носителем предчувствия и чуда. Небо не просто освещает людей, а перестраивает знакомый сюжет через необычный цвет и ожидание грозы. Руины соединяют зрительный эффект с христианским толкованием смены старого и нового времени.',
['Огромная луна: небесное тело организует ночную сцену.','Розово-золотое свечение: цвет делает пространство необычным.','Грозовые облака: погода придаёт действию напряжение.','Заросшая арка: архитектура выглядит почти природной пещерой.','Работа пальцами: следы нанесения краски участвуют в поверхности.'],
'Не называй изображённую луну документом конкретного затмения: датированное астрономическое событие не установлено. Отпечатки принадлежат, вероятно, Доссо; это не криминалистическая идентификация. Предполагаемое влияние немецких мастеров или участие в фоне «Мадонны Фолиньо» остаются гипотезами. «Вакханалия» NG5279 отнесена к последователю, а не уверенно к Доссо. Фрагмент NG1234 происходит из отдельного потолочного заказа 1524 года, не из «Поклонения». Проверенный свободный файл NG3924 пока не найден.',
[['Национальная галерея: Доссо Досси',N+'artists/dosso-dossi'],['Национальная галерея: ночное Поклонение, NG3924',dosso],['Национальная галерея: последователь, NG5279',N+'paintings/follower-of-dosso-dossi-a-bacchanal'],['Национальная галерея: фрагмент потолка, NG1234',N+'paintings/dosso-dossi-a-man-embracing-a-woman']],
{key:'ng:NG3924',title:'Поклонение волхвов',date:'около 1527–1529',medium:'Масло по дереву, вероятно тополю; 85,1 × 108 см',source:dosso,reason:'Музейный оригинал проверен; конкретный свободный файл репродукции не подтверждён'});
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

