/* artists-batch-63.js */
(()=>{'use strict';
const batch={"ludolf_de_jongh":{"name":"Людолф де Йонг","latin":"Ludolf de Jongh","life":"1616–1679","tag":"Нидерланды · охота и повествовательный пейзаж","aliases":["Людолф де Йонг","Ludolf de Jongh","Людольф де Йонг","Людольф де Ионг","Ludolf Leendertsz de Jongh"],"bio":["Де Йонг происходил из Оверсхи и работал в Роттердаме. Писал жанровые, исторические и охотничьи сцены, пейзажи и портреты; мастерство не ограничивалось домашним интерьером.","Для карточки выбрана «Охота на лису» с подписью L. D. Jongh. Она даёт более надёжную опору для знакомства с художником, чем неподписанный лондонский интерьер, авторство которого остаётся спорным."],"technique":["1650–1679, масло по холсту; SK-A-1858. Лиса окружена возбуждёнными охотничьими собаками, а всадники приближаются с разных сторон.","Сходящиеся направления движения связывают группу животных с пространством пейзажа. Предметный рассказ строится вокруг действия, а не вокруг документально названного конкретного места."],"innovation":"Охотничья картина соединяет наблюдение за животными и многофигурное движение. Знакомство с рисунками собак позволяет сопоставлять повторяющиеся мотивы, не приписывая автоматически один и тот же этюд каждой картине.","features":["Окружённая лиса: центр действия.","Подвижные собаки: напряжение переднего плана.","Всадники: движение с нескольких сторон.","Пейзаж: пространство объединяет охотников.","Подпись: опора для музейной атрибуции."],"caution":"1650–1679 — широкий диапазон создания, не точная дата. Измерение 51 × 71 × 7,7 см включает глубину предмета и не выдано здесь за размер красочного поля или толщину холста. NG2552 лишь предположительно относится к де Йонгу. Страница музейного файла не загрузилась; репродукция пока не подключена.","sources":[["Рейксмюсеум: SK-A-1858, подпись и техника","https://www.rijksmuseum.nl/en/collection/object/The-Fox-Hunt--38e42a50d95b8a523e27d33a6f1e81ca"],["Национальная галерея: спорная атрибуция NG2552","https://www.nationalgallery.org.uk/paintings/possibly-by-ludolf-de-jongh-an-interior-with-a-woman-refusing-a-glass-of-wine"],["Рейксмюсеум: отдельный этюд собаки","https://www.rijksmuseum.nl/en/collection/object/Seated-Greyhound-Seen-from-Behind--15d8a6b3051eb05778a000c57068e92f"],["Биография: место рождения и круг жанров","https://en.wikipedia.org/wiki/Ludolf_de_Jongh"]],"works":[],"pendingWorks":[{"key":"rijks:SK-A-1858","title":"Охота на лису","date":"1650–1679","medium":"Масло по холсту","museum":"Рейксмюсеум, Амстердам","source":"https://www.rijksmuseum.nl/en/collection/object/The-Fox-Hunt--38e42a50d95b8a523e27d33a6f1e81ca","reason":"Музейный оригинал установлен; условия использования конкретного файла репродукции не подтверждены"}],"editorialStatus":"text_only_image_file_and_rights_pending"},"jacob_ochtervelt":{"name":"Якоб Охтервелт","latin":"Jacob Ochtervelt","life":"1634–1682","tag":"Нидерланды · светский интерьер и фактура","aliases":["Якоб Охтервелт","Jacob Ochtervelt","Якоб Охтервельт","Якоб Лукас Охтервелт"],"bio":["Охтервелт родился в Роттердаме и писал преимущественно жанровые сцены. Национальная галерея сообщает о его обучении у Николаса Берхема и сближает ранние интерьеры с Питером де Хохом.","«Девушка, подстригающая ногти» относится к группе сцен начала 1670-х с повторяющимися серебряным кувшином и блюдом. Их датируют временем около переезда мастера из Роттердама в Амстердам."],"technique":["Вероятно 1670–1675, масло по холсту; 74,6 × 59 см, NG2553. Девушка пользуется ножницами, служанка приносит серебряный кувшин и блюдо для мытья рук.","На столе под дорогим турецким ковром лежат зеркало, шкатулка и жемчуг. Большая шпалера на задней стене показывает повествовательную сцену, которую музей не может уверенно определить."],"innovation":"Малое бытовое действие становится поводом для тонкой передачи роскоши и отношений между фигурами. Живопись вещей не сводится к перечню символов: материал и освещение создают самостоятельный интерес.","features":["Ножницы: точное действие героини.","Серебряная посуда: блеск металла.","Турецкий ковёр: дорогая фактурная поверхность.","Жемчуг и зеркало: предметы туалета.","Шпалера: изображение внутри интерьера."],"caution":"Не устанавливай личность модели без доказательств. Назначение большого таза на переднем плане предположительно; сюжет шпалеры не определён достоверно. Не подменяй эту картину музыкальными сценами того же автора. Дата вероятная, не подписанный точный год. Конкретный свободный файл пока не подтверждён.","sources":[["Национальная галерея: NG2553, размеры и ограничения толкования","https://www.nationalgallery.org.uk/paintings/jacob-ochtervelt-a-young-lady-trimming-her-fingernails"],["Национальная галерея: биография","https://www.nationalgallery.org.uk/artists/jacob-ochtervelt"],["Для сравнения: другая музыкальная сцена","https://www.nationalgallery.org.uk/paintings/jacob-ochtervelt-two-women-and-a-man-making-music"]],"works":[],"pendingWorks":[{"key":"ng:NG2553","title":"Девушка, подстригающая ногти, в сопровождении служанки","date":"вероятно 1670–1675","medium":"Масло по холсту; 74,6 × 59 см","museum":"Национальная галерея, Лондон","source":"https://www.nationalgallery.org.uk/paintings/jacob-ochtervelt-a-young-lady-trimming-her-fingernails","reason":"Музейный оригинал установлен; условия использования конкретного файла репродукции не подтверждены"}],"editorialStatus":"text_only_image_file_and_rights_pending"},"eglon_hendrik_van_der_neer":{"name":"Эглон Хендрик ван дер Нер","latin":"Eglon Hendrik van der Neer","life":"около 1634–1703; рождение предположительно","tag":"Нидерланды · исторический образ и роскошный костюм","aliases":["Эглон Хендрик ван дер Нер","Eglon Hendrik van der Neer","Эглон ван дер Нер","Эглон Хендрик ван дер Неер"],"bio":["Эглон родился в Амстердаме, учился у своего отца Арта ван дер Нера и у Якоба ван Лоо. Работал также в Брюсселе и позднее при дворе курфюрста Пфальца в Дюссельдорфе.","Отцовская известность связана прежде всего с пейзажем; Эглон развивал иные задачи. В передаче дорогих тканей музей сближает его с Терборхом и Франсом ван Мирисом, а не только с отцом."],"technique":["«Юдифь», около 1678: масло по дереву, вероятно дубу; 32 × 24,6 см, NG2535. Свет выделяет шёлк, парчу и жемчуг на тёмном фоне. Картина подписана.","Меч и служанка с мешком уточняют библейский сюжет, который не сразу распознаётся за роскошным костюмом. Шлем с перьями и другие материалы продолжают игру отражений и фактур."],"innovation":"Священная героиня может выступать моделью для портретного самопредставления. Однако возможность портрета в образе Юдифи не равна установленной личности конкретной заказчицы.","features":["Светлый костюм: главный зрительный акцент.","Шёлк и парча: различие материальных поверхностей.","Жемчуг: детали дорогого наряда.","Меч: атрибут раскрывает сюжет.","Тёмный фон: рассказ частично скрыт."],"caution":"Не путай Эглона с его отцом Артом. Портрет в образе Юдифи предполагается, личность модели не установлена. Разные страницы музея дают 1690 и 1698 как год придворного назначения; одна дата здесь не навязана. Дата около 1678 также приблизительна. Конкретный свободный файл пока не подтверждён.","sources":[["Национальная галерея: NG2535 и возможный портретный характер","https://www.nationalgallery.org.uk/paintings/eglon-hendrik-van-der-neer-judith"],["Национальная галерея: биография и иная дата назначения","https://www.nationalgallery.org.uk/artists/eglon-hendrik-van-der-neer"]],"works":[],"pendingWorks":[{"key":"ng:NG2535","title":"Юдифь","date":"около 1678","medium":"Масло по дереву, вероятно дубу; 32 × 24,6 см","museum":"Национальная галерея, Лондон","source":"https://www.nationalgallery.org.uk/paintings/eglon-hendrik-van-der-neer-judith","reason":"Музейный оригинал установлен; условия использования конкретного файла репродукции не подтверждены"}],"editorialStatus":"text_only_image_file_and_rights_pending"},"cornelis_de_man":{"name":"Корнелис де Ман","latin":"Cornelis de Man","life":"1621–1706","tag":"Нидерланды · шахматы и пространственный интерьер","aliases":["Корнелис де Ман","Cornelis de Man","Корнелис де Манн","Kornelis de Man"],"bio":["Де Ман родился и умер в Делфте. Музей Будапешта отмечает, что с 1661 года значительную часть его жанровых работ составляют состоятельные горожане в элегантных домах.","«Шахматисты», около 1670, продолжают интерес Вермеера и де Хоха к точной перспективе и свету. При этом жесты у де Мана более театральны, а материалы переданы подчеркнуто роскошно."],"technique":["Масло по холсту; 97,5 × 85 см, инвентарь 320. Внизу справа подпись CDMan. Мужчина и женщина находятся у шахматного столика, партия, по мнению музея, близится к завершению.","Кошка, мехи, лютня и занавесь перед спальным альковом включены в смысловую среду. Свет делит пространство и помогает моделировать фигуры; рука мужчины и взгляд женщины усиливают напряжение."],"innovation":"Игровая ситуация допускает второе, любовное прочтение. Музей видит в ней борьбу тактик и эмоций, но интерпретация не подменяет доказательств о реальном ходе партии.","features":["Шахматный столик: центр взаимодействия.","Точная перспектива: ясная организация комнаты.","Свет: разделяет планы и моделирует фигуры.","Театральные жесты: выразительность отношений.","Реальные фактуры: контраст с условностью поз."],"caution":"Не объявляй победителя по конкретной комбинации или числу ходов: источник этого не устанавливает. Любовная метафора — музейное толкование, не протокол реальной партии. Не смешивай живописный оригинал 320 с гравюрной репродукцией. Страницы найденных файлов не загрузились; условия конкретной репродукции пока не подтверждены.","sources":[["Музей изящных искусств, Будапешт: инвентарь 320","https://www.mfab.hu/artworks/10346/"],["Web Gallery of Art: годы художника и описание","https://www.wga.hu/html_m/m/man/chess_pl.html"],["Wikidata: сопоставление названия, автора и собрания","https://www.wikidata.org/wiki/Q28671092"]],"works":[],"pendingWorks":[{"key":"budapest:320","title":"Шахматисты","date":"около 1670","medium":"Масло по холсту; 97,5 × 85 см","museum":"Музей изящных искусств, Будапешт","source":"https://www.mfab.hu/artworks/10346/","reason":"Музейный оригинал установлен; условия использования конкретного файла репродукции не подтверждены"}],"editorialStatus":"text_only_image_file_and_rights_pending"},"jan_verkolje":{"name":"Ян Верколье","latin":"Jan Verkolje","life":"1650–1693","tag":"Нидерланды · письмо, игра и бытовая интрига","aliases":["Ян Верколье","Jan Verkolje","Ян Верколе","Ян Верколье Старший","Johannes Verkolje","Jan Verkolje I"],"bio":["Верколье родился в Амстердаме и умер в Делфте. Он известен портретами и жанровыми сценами, где нарядные пары играют или музицируют в тщательно устроенном интерьере.","Связанные с живописью рисунки показывают, что фигуры могли использоваться повторно. Однако повторный мотив не доказывает, что одна картина является механической копией другой."],"technique":["«Вестник», 1674: масло по холсту; 59,7 × 53,4 см, инвентарь 865. Подпись I. Verkolje / 1674 находится слева на постаменте у двери.","Офицер и молодая женщина играют в нарды; в момент броска костей появляется посланник с письмом. Тревожный взгляд офицера и блестящий атлас платья делают прерывание игры особенно заметным."],"innovation":"Повседневное занятие становится незавершённым рассказом: зритель видит реакцию раньше, чем узнаёт содержание письма. Мастерство фактуры усиливает интерес к персонажам, не раскрывая развязку.","features":["Прерванная игра: событие меняет ход сцены.","Письмо: источник неизвестной новости.","Взгляд офицера: эмоциональный поворот.","Блестящий атлас: складки, швы и заломы.","Подпись у двери: имя включено в интерьер."],"caution":"Содержание письма неизвестно: плохая новость предполагается по реакции, а не прочитана в тексте. Не путай Яна с его сыном Николасом. Картина относится к NK Collection; военная история владения требует точного пересказа, не вывода о современном споре о реституции. Полная страница конкретного файла не загрузилась; репродукция не подключена.","sources":[["Маурицхёйс: 865, сюжет, подпись и провенанс","https://www.mauritshuis.nl/en/our-collection/artworks/865-the-messenger"],["Рейксмюсеум: отдельный рисунок и повторные фигуры","https://www.rijksmuseum.nl/en/collection/object/Two-Young-Couples-Making-Music-and-Courting-on-a-Terrace--2462b433fd05419d70fa0476dc8479f5"],["Биография и разграничение жанров","https://en.wikipedia.org/wiki/Jan_Verkolje"]],"works":[],"pendingWorks":[{"key":"mauritshuis:865","title":"Вестник","date":"1674","medium":"Масло по холсту; 59,7 × 53,4 см","museum":"Маурицхёйс, Гаага","source":"https://www.mauritshuis.nl/en/our-collection/artworks/865-the-messenger","reason":"Музейный оригинал установлен; условия использования конкретного файла репродукции не подтверждены"}],"editorialStatus":"text_only_image_file_and_rights_pending"}};
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(batch);
})();

;
/* artists-batch-64.js */
(()=>{'use strict';
const batch={"thomas_de_keyser":{"name":"Томас де Кейзер","latin":"Thomas de Keyser","life":"1596/1597–1667","tag":"Нидерланды · портрет человека за делом","aliases":["Томас де Кейзер","Thomas de Keyser","Томас де Кейсер","Томас де Кайзер"],"bio":["Де Кейзер был сыном амстердамского архитектора и скульптора Хендрика де Кейзера. До приезда Рембрандта в 1631–1632 годах он и Николас Элиас входили в число самых востребованных портретистов Амстердама.","Писал и небольшие тщательно отделанные портреты, и крупные групповые композиции. После 1640 года активнее занимался торговлей камнем, и количество его картин сократилось."],"technique":["1627, масло по дубовой доске; 92,4 × 69,3 см, NG212. Гюйгенс сидит у стола и принимает сообщение от молодого человека. Полнофигурная композиция включает их в комнату, а не изолирует на нейтральном фоне.","Китаррон, архитектурные планы, земной и небесный глобусы напоминают о музыке, науках и государственных обязанностях модели. Слабая монограмма и дата находятся на передней части камина."],"innovation":"Портрет становится рассказом о способе жизни и интеллектуальных интересах. Не только лицо, но и обстановка создаёт образ дипломата и советника штатгальтера Фредерика Хендрика.","features":["Сообщение в руке: модель показана за делом.","Полные фигуры: человек связан с пространством комнаты.","Глобусы: земная и небесная сферы.","Музыкальный инструмент: личные интересы модели.","Планы: архитектура как часть интеллектуального мира."],"caution":"Роль второго персонажа не установлена: секретарь, паж или слуга остаются вариантами. Не переносить на него имя Гюйгенса. Место изображённого интерьера не доказано как точная комната дома модели. Старый комментарий файла называет холст, но текущий музейный паспорт — дубовую доску. PD-Art проверен; визуальный просмотр и браузерная загрузка — нет.","sources":[["Национальная галерея: NG212 и предметы","https://www.nationalgallery.org.uk/paintings/thomas-de-keyser-portrait-of-constantijn-huygens-and-his-clerk"],["Музейный каталог: неизвестный молодой человек","https://www.nationalgallery.org.uk/paintings/catalogues/maclaren-and-brown-1991/portrait-of-constantijn-huygens-and-his-clerk"],["Национальная галерея: биография","https://www.nationalgallery.org.uk/artists/thomas-de-keyser"],["Конкретный файл и PD-Art","https://commons.wikimedia.org/wiki/File:Thomas_de_Keyser_-_Portret_van_Constantijn_Huygens_en_zijn_secretaris.jpg"]],"works":[{"key":"ng:NG212","title":"Константейн Гюйгенс и его предполагаемый секретарь","originalTitle":"Portrait of Constantijn Huygens and his (?) Clerk","date":"1627","medium":"Масло по дубовой доске; 92,4 × 69,3 см","museum":"Национальная галерея, Лондон","source":"https://www.nationalgallery.org.uk/paintings/thomas-de-keyser-portrait-of-constantijn-huygens-and-his-clerk","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thomas%20de%20Keyser%20-%20Portret%20van%20Constantijn%20Huygens%20en%20zijn%20secretaris.jpg?width=800","zoom":"https://commons.wikimedia.org/wiki/Special:FilePath/Thomas%20de%20Keyser%20-%20Portret%20van%20Constantijn%20Huygens%20en%20zijn%20secretaris.jpg?width=1600","imageSource":"https://commons.wikimedia.org/wiki/File:Thomas_de_Keyser_-_Portret_van_Constantijn_Huygens_en_zijn_secretaris.jpg","license":"PD-Art по полной странице конкретного файла; общественное достояние в США, возможны ограничения в иных юрисдикциях","imageVisuallyReviewed":false,"look":"Проследи движение сообщения от молодого человека к Гюйгенсу. Найди глобусы, архитектурные планы и музыкальный инструмент. Предметы раскрывают интересы дипломата, но не устанавливают имя второго персонажа."}],"pendingWorks":[],"editorialStatus":"museum_sources_pd_art_file_checked_browser_check_pending"},"bartholomeus_van_der_helst":{"name":"Бартоломеус ван дер Хелст","latin":"Bartholomeus van der Helst","life":"1613–1670","tag":"Нидерланды · гладко написанный парадный портрет","aliases":["Бартоломеус ван дер Хелст","Bartholomeus van der Helst","Бартоломеус ван дер Гельст","Бартоломей ван дер Хелст","Ван дер Хелст"],"bio":["Ван дер Хелст родился в Харлеме и с 1636 года документирован в Амстердаме, где провёл основную карьеру. Его обучение у Николаса Элиаса возможно, но не установлено.","Он стал одним из ведущих амстердамских портретистов. Музей противопоставляет его постепенно сглаживавшуюся манеру более свободному позднему письму Рембрандта; различие отражает вкусы заказчиков, не универсальную шкалу качества."],"technique":["«Девочка в бледно-голубом платье с веером из страусиных перьев», 1645: масло по холсту; NG1248. Поза и веер выражают усвоенный парадный жест, который ребёнок исполняет немного неловко.","Свет падает на атлас и лицо. Платье одновременно выглядит холодным серо-голубым и содержит тёплые белые, жёлтые и красные мазки; выразительность цвета не сводится к одному пигменту."],"innovation":"Детский портрет показывает социальную роль и живую индивидуальность, не делая ребёнка взрослым. Небольшая неуверенность жеста может сосуществовать с дорогой тканью и продуманной репрезентацией.","features":["Парадная поза: ребёнок усваивает взрослый жест.","Страусиный веер: дорогой аксессуар.","Свет на атласе: передача блеска ткани.","Сложный голубой: тёплые мазки внутри холодного впечатления.","Мягкая моделировка: менее заметный мазок."],"caution":"Личность и возраст девочки неизвестны. Не подменять NG1248 портретом Верспронка 1641 года: совпадение голубого платья не означает одну модель или одного автора. Застенчивость — впечатление от образа, не установленный характер человека. Это работа 1645-го, не взрослая модель из портрета 1644 года. Свободный файл пока не подтверждён.","sources":[["Национальная галерея: NG1248 и неопределённая модель","https://www.nationalgallery.org.uk/paintings/bartholomeus-van-der-helst-portrait-of-a-girl"],["Национальная галерея: биография","https://www.nationalgallery.org.uk/artists/bartholomeus-van-der-helst"],["Для различения: взрослая женщина, NG1937","https://www.nationalgallery.org.uk/paintings/bartholomeus-van-der-helst-portrait-of-a-lady-in-black-satin-with-a-fan"]],"works":[],"pendingWorks":[{"key":"ng:NG1248","title":"Девочка в бледно-голубом платье с веером из страусиных перьев","date":"1645","medium":"Масло по холсту","museum":"Национальная галерея, Лондон","source":"https://www.nationalgallery.org.uk/paintings/bartholomeus-van-der-helst-portrait-of-a-girl","reason":"Музейный оригинал установлен; конкретный свободный файл репродукции не подтверждён"}],"editorialStatus":"text_only_image_file_and_rights_pending"},"johannes_verspronck":{"name":"Йоханнес Верспронк","latin":"Johannes Cornelisz Verspronck","life":"около 1600/1603–1662","tag":"Нидерланды · детский портрет и социальная роль","aliases":["Йоханнес Верспронк","Johannes Cornelisz Verspronck","Иоганнес Верспронк","Ян Корнелис Верспронк","Johannes Verspronck","Jan Cornelisz Verspronck"],"bio":["Верспронк работал в Харлеме и известен прежде всего портретами. Музейное техническое исследование рассматривает его картины 1641–1653 годов как самостоятельную линию рядом с живописью Франса Халса.","«Девочка в голубом платье», 1641, подписана и датирована. Её популярность не устраняет пробела в документах: установить имя ребёнка и его семью пока не удалось."],"technique":["Масло по холсту; 82 × 66,7 см, SK-A-3064. Ребёнок держит перьевой веер и показан по модели парадного женского портрета своего времени.","Кружево, жемчуг и украшения подчёркивают праздничный костюм. По замечанию музея, только выражение лица выдаёт, что девочка играет роль взрослой дамы, а не действительно принадлежит к взрослой возрастной группе."],"innovation":"Исторический детский портрет одновременно индивидуализирует человека и показывает ожидания его среды. Одежда помогает понять социальную репрезентацию, но не устанавливает личность и точный возраст.","features":["Взрослый тип позы: парадная репрезентация ребёнка.","Голубое платье: главный цветовой акцент.","Перьевой веер: аксессуар как часть роли.","Кружево и жемчуг: тонкая передача дорогих вещей.","Детское лицо: отличие человека от исполняемой роли."],"caution":"Предполагаемые шесть–десять лет — оценка, не документированный возраст. Не смешивай SK-A-3064, 1641, с NG1248 ван дер Хелста, 1645. В старой подписи файла ширина 66,5 см; здесь использован текущий паспорт 66,7. Выбран полный скан без рамы и без современной перекраски платья. PD-Art проверен; визуальный просмотр и браузерная загрузка — нет.","sources":[["Рейксмюсеум: SK-A-3064, подпись и модель","https://www.rijksmuseum.nl/en/collection/object/Portrait-of-a-Girl-Dressed-in-Blue--3cf51ea4e1336fd4cf075b3e29a1e519"],["Рейксмюсеум: пояснение о детском портрете","https://www.rijksmuseum.nl/en/story/portrait-girl-in-blue"],["Музейное техническое исследование","https://bulletin.rijksmuseum.nl/article/download/9839/10335"],["Конкретный файл Google Art Project и PD-Art","https://de.wikipedia.org/wiki/Datei:Johannes_Cornelisz._Verspronck_-_Portret_van_een_meisje_in_het_blauw_-_Google_Art_Project.jpg"]],"works":[{"key":"rijks:SK-A-3064","title":"Девочка в голубом платье","originalTitle":"Portrait of a Girl Dressed in Blue","date":"1641","medium":"Масло по холсту; основа 82 × 66,7 см","museum":"Рейксмюсеум, Амстердам","source":"https://www.rijksmuseum.nl/en/collection/object/Portrait-of-a-Girl-Dressed-in-Blue--3cf51ea4e1336fd4cf075b3e29a1e519","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Johannes%20Cornelisz.%20Verspronck%20-%20Portret%20van%20een%20meisje%20in%20het%20blauw%20-%20Google%20Art%20Project.jpg?width=800","zoom":"https://commons.wikimedia.org/wiki/Special:FilePath/Johannes%20Cornelisz.%20Verspronck%20-%20Portret%20van%20een%20meisje%20in%20het%20blauw%20-%20Google%20Art%20Project.jpg?width=1600","imageSource":"https://de.wikipedia.org/wiki/Datei:Johannes_Cornelisz._Verspronck_-_Portret_van_een_meisje_in_het_blauw_-_Google_Art_Project.jpg","license":"PD-Art по полной странице конкретного файла; общественное достояние в США, возможны ограничения в иных юрисдикциях","imageVisuallyReviewed":false,"look":"Сравни взрослый парадный костюм с выражением детского лица. Найди кружево, жемчуг и перьевой веер. Не угадывай имя модели по сходству с другими детскими портретами."}],"pendingWorks":[],"editorialStatus":"museum_sources_pd_art_file_checked_browser_check_pending"},"nicolaes_eliasz_pickenoy":{"name":"Николас Элиас Пикеной","latin":"Nicolaes Eliasz Pickenoy","life":"1588 — 1650/1656 по Рейксмюсеуму","tag":"Нидерланды · парный портрет","aliases":["Николас Элиас Пикеной","Nicolaes Eliasz Pickenoy","Николас Элиасз Пикеной","Николас Пикеной","Nicolaes Eliasz. Pickenoy","Nicolas Eliasz"],"bio":["Пикеной работал в Амстердаме и вместе с де Кейзером был одним из самых востребованных портретистов до приезда Рембрандта. Его наследие включает индивидуальные и большие групповые портреты.","Пара портретов Маертена Рея и Марии Свартенхонт датирована 1627 годом. Музей считает стилистическую атрибуцию Пикеною очень убедительной; зеркальная связь пары важна для прочтения отдельной доски."],"technique":["«Мария Йоахимс Свартенхонт», 1627: масло по дереву; SK-A-699. Овальный поясной портрет показывает сидящую женщину с перчатками в правой руке; её супруг изображён на отдельной парной доске SK-A-698.","Надпись вверху справа сообщает возраст 27 и дату 1627. Поздняя этикетка на обороте называет Марию Свартенхонт и семейную связь, помогая сопоставить изображение с провенансом."],"innovation":"Портрет не всегда был самостоятельным одиночным предметом: парная композиция выражает супружескую связь. Атрибуция автора и идентификация модели требуют разных видов доказательств — стиля, надписей и документов.","features":["Овальный формат: компактное обрамление фигуры.","Перчатки: жест и предмет внутри парадной позы.","Парность: образ связан с портретом супруга.","Возрастная надпись: отдельна от подписи художника.","Этикетка оборота: документальная история предмета."],"caution":"Годы 1598–1631 в музейном названии относятся к модели, не к Пикеною. Биографические даты художника в разных музейных текстах расходятся, включая 1590/1591 как рождение; расхождение не выдано за точность. Возраст и год не равны авторской подписи. Не подставлять лишь приписанный Пикеною портрет Питера ван Сона. Свободный файл пока не подтверждён.","sources":[["Рейксмюсеум: SK-A-699, надписи и атрибуция","https://www.rijksmuseum.nl/en/collection/object/Portrait-of-Maria-Joachimsdr-Swartenhont-1598-1631--9db06f414efbfa4ebaf53ae2a51096ae"],["Рейксмюсеум: отличающаяся датировка жизни","https://www.rijksmuseum.nl/en/collection/object/Portrait-of-Pieter-van-Son-c-1590-1654--4f668eb0d1073625bed2de350a1161c0?tab=catalogue"],["Исследование групповых портретов Пикеноя","https://jhna.org/articles/amsterdam-civic-guard-portraits-within-outside-new-rijksmuseum-part-i/"]],"works":[],"pendingWorks":[{"key":"rijks:SK-A-699","title":"Портрет Марии Йоахимс Свартенхонт","date":"1627","medium":"Масло по дереву","museum":"Рейксмюсеум, Амстердам","source":"https://www.rijksmuseum.nl/en/collection/object/Portrait-of-Maria-Joachimsdr-Swartenhont-1598-1631--9db06f414efbfa4ebaf53ae2a51096ae","reason":"Музейный оригинал установлен; конкретный свободный файл репродукции не подтверждён"}],"editorialStatus":"text_only_image_file_and_rights_pending"},"jan_van_ravesteyn":{"name":"Ян ван Равестейн","latin":"Jan Antonisz van Ravesteyn","life":"около 1572–1657","tag":"Нидерланды · бюстовой портрет и придворный заказ","aliases":["Ян ван Равестейн","Jan Antonisz van Ravesteyn","Ян Антонис ван Равестейн","Ян Антонисз ван Равестейн","Jan Anthonisz van Ravesteyn","Jan Anthonisz. van Ravesteyn"],"bio":["Равестейн работал в Гааге и получал заказы на индивидуальные и групповые портреты. Серия офицеров, начатая, вероятно, для принца Морица в 1611 году, стала важной частью его успеха.","В его окружении и мастерской создавались повторения портретов. Поэтому авторская работа, произведение мастерской и поздняя копия не должны превращаться в одинаковую безусловную атрибуцию."],"technique":["«Мужской портрет, предположительно Ян Дублет», 1634: масло по дереву; основа 67,2 × 57,2 см, SK-A-1950. Фигура показана бюстом с поворотом вправо.","Музей принимает авторство Равестейна, но осторожно определяет личность как Яна Дублета, сеньора Синт-Анналанда и генерального сборщика средств. Профессиональная биография возможной модели не заменяет доказательства её имени."],"innovation":"Один портрет может иметь разную степень определённости по автору, времени и модели. Принятая атрибуция не делает предположительное отождествление человека достоверным.","features":["Бюст: внимание сосредоточено на лице.","Поворот вправо: основа позы.","Деревянная доска: материальный носитель.","Дата 1634: время конкретного портрета.","Предположительное имя: предел идентификации."],"caution":"Имя Ян Дублет должно оставаться с оговоркой. Даты 1580–1650 в заглавии относятся к предполагаемой модели. Глубина 6,5 см измерена с рамой и не названа толщиной доски. Не смешивай SK-A-1950 с другим «Мужским портретом» SK-C-240 или офицером Маурицхёйса 414, отнесённым к художнику и мастерской. Свободный файл пока не подтверждён.","sources":[["Рейксмюсеум: SK-A-1950 и степень уверенности в имени","https://www.rijksmuseum.nl/en/collection/object/Portrait-of-a-Man-possibly-Jan-Doublet-1580-1650--fec34cac39f24bbad710ad6cb58de055"],["Рейксмюсеум: другой мужской портрет","https://www.rijksmuseum.nl/en/collection/object/Portrait-of-a-Man--86a6a89e0896287d513d6cccdecf2004"],["Маурицхёйс: отдельная работа художника и мастерской","https://www.mauritshuis.nl/en/our-collection/artworks/414-portrait-of-an-officer"]],"works":[],"pendingWorks":[{"key":"rijks:SK-A-1950","title":"Мужской портрет, предположительно Ян Дублет","date":"1634","medium":"Масло по дереву; основа 67,2 × 57,2 см","museum":"Рейксмюсеум, Амстердам","source":"https://www.rijksmuseum.nl/en/collection/object/Portrait-of-a-Man-possibly-Jan-Doublet-1580-1650--fec34cac39f24bbad710ad6cb58de055","reason":"Музейный оригинал установлен; конкретный свободный файл репродукции не подтверждён"}],"editorialStatus":"text_only_image_file_and_rights_pending"}};
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(batch);
})();

