/* artists-batch-69.js */
(()=>{'use strict';
const M='https://www.mskgent.be/',H='https://imagehub.mskgent.be/',B={};
function add(id,name,latin,life,aliases,bio,technique,innovation,features,caution,page,inv,n,title,originalTitle,date,width,height,photographer,look,extra=[]){const source=M+page,manifest=H+'iiif/3/'+n+'/manifest.json',base=H+'iiif/2/public%2F'+n+'.tif';B[id]={name,latin,life,tag:'Фландрия · натюрморт и анималистика XVII века',aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources:[['MSK Gent: '+inv+' и музейное описание',source],['Официальный IIIF: автор, объект, изображение и права',manifest],...extra],pendingWorks:[],editorialStatus:'official_iiif_manifest_rights_checked_browser_pending',works:[{key:'msk:'+inv,title,originalTitle,date,medium:'Масляная живопись; материал основы здесь не уточнён',museum:'Музей изящных искусств, Гент',source,image:base+'/full/800,/0/default.jpg',zoom:base+'/full/1600,/0/default.jpg',imageSource:manifest,imageWidth:width,imageHeight:height,license:'Public Domain Mark 1.0 по официальному IIIF-манифесту MSK Gent; обозначение общественного достояния, не CC0',rightsURI:'https://creativecommons.org/publicdomain/mark/1.0/',creditLine:'Museum of Fine Arts Ghent (MSK Gent), '+inv+(photographer?'; photograph '+photographer:''),rightsNote:'MSK Gent предлагает заказывать цветокодированные TIFF через Art in Flanders и выражает пожелание получить три экземпляра печатной или коммерческой публикации.',imageVisuallyReviewed:false,look}]};}
add('adriaen_van_utrecht','Адриан ван Утрехт','Adriaen van Utrecht','1599–1652',['Адриан Утрехтский','Adrian van Utrecht'],
['Несмотря на фамилию, художник был фламандцем и работал в Антверпене. Его наследие включает роскошные пищевые натюрморты, рынки, кухни и животных.','«Рыбная лавка» прежде украшала пространство над камином кухни гентского аббатства Святого Петра. Монументальный натюрморт связан с реальным назначением помещения.'],
['Около 1640, S-10. Большое разнообразие рыбы и морепродуктов демонстрирует богатство моря, а не точный ассортимент конкретной лавки. Монограмма AW находится справа на бочке.','Пока торговка беседует с покупателем, молодой вор срезает её кошелёк. Эта жанровая вставка связывает пищевое изобилие с потерей бдительности.'],
'Пищевой натюрморт превращается в действие с несколькими уровнями смысла. Музей допускает и аллегорию Воды, и нравственное прочтение человеческих отношений.',
['Рыбное изобилие: разнообразие форм.','Морепродукты: материальная тема моря.','Торговый разговор: бытовой эпизод.','Кошелёк и вор: скрытое действие.','Бочка с монограммой: имя внутри сцены.'],
'Не записывай ван Утрехта автоматически в утрехтскую школу. На странице коллекции дата около 1640, в манифесте указано 1640: приблизительность сохранена. Эротическое толкование рыб — музейная интерпретация, не универсальное значение любой рыбы. Размеры изображения ниже — пиксели, не сантиметры. Визуальная и браузерная проверки не выполнены.',
'en/collection/s-10','S-10',6362,'Рыбная лавка','Fishmonger’s Stall','около 1640',6973,4989,'Hugo Maertens','Найди переговоры у прилавка и незаметное действие с кошельком. Сравни богатство натюрморта с маленькой человеческой интригой.',
[['Биография и круг жанров','https://en.wikipedia.org/wiki/Adriaen_van_Utrecht']]);
add('pieter_boel','Питер Буль','Pieter Boel','1622–1674',['Питер Бул','Питер Боэл','Peter Boel'],
['Буль известен охотничьими сценами, натюрмортами и исследованиями животных. Заказы Людовика XIV на рисунки и живописные этюды затем использовались для шпалерных проектов.','Его искусство связано с кругом Снейдерса и Фейта. Музейные страницы называют обоих в связи с обучением; точная последовательность ученичества здесь не утверждается.'],
['«Натюрморт с совой и охотничьими трофеями», 1907-A: точный год в паспорте не указан. Рядом с добычей находится живая сова у клетки.','Историческая охота с подсадной совой поясняет присутствие птиц и ловушки. Ваза с пьяным Вакхом предлагает зрительную параллель потере свободы из-за собственных желаний.'],
'Живое животное и охотничья добыча образуют не просто перечень видов. Музей читает сцену как предупреждение о желаниях, которые делают человека уязвимым.',
['Живая сова: центр смысловой связи.','Клетка: тема ограничения свободы.','Охотничья добыча: связь с промыслом.','Вакх на вазе: изображение внутри изображения.','Птицы: движение вокруг приманки.'],
'Музейная мораль — интерпретация картины, не утверждение об особой нравственной природе животных. Исторический сюжет не является современной инструкцией по охоте. 1907 в инвентаре обозначает поступление, не создание. Не приписывай картину Фейту только по сходству темы. Визуальная и браузерная проверки не выполнены.',
'en/collection/1907-a','1907-A',445,'Натюрморт с совой и охотничьими трофеями','Still Life with an Owl and a Hunting Trophy','XVII век; точный год не указан',6927,4969,'Hugo Maertens','Сопоставь сову и клетку с изображением Вакха на вазе. Различи наблюдение животных и предлагаемый музеем нравственный смысл.',
[['MSK Gent: другая версия биографического пояснения','https://www.mskgent.be/en/collection/1907-f']]);
add('david_de_coninck','Давид де Конинк','David de Coninck','около 1643/1645 — 1699 или позднее по НГ',['Давид де Конинг','David de Koninck'],
['Де Конинк родился в Антверпене, учился у Питера Буля и работал в нескольких европейских центрах. Национальная галерея указывает длительный римский период и документированное пребывание в Брюсселе в 1699 году.','Охотничьи натюрморты связаны с традицией Фейта, но животные в саду были отдельной любимой темой художника. Она позволяет сравнивать анималистику с изображением добычи.'],
['«Животные в саду», S-63: точная дата в паспорте не указана. Каталог перечисляет кроликов, птиц, попугая и павлина в садовом пространстве.','Деревья и кусты, фонтан, ограждение и садовая скульптура соединяют естественную жизнь с рукотворной средой. Такая сцена не равна документальному списку животных одного реального сада.'],
'Животные становятся самостоятельными действующими лицами. Композиционные привычки натюрморта перенесены в обжитый пейзаж, где природа и человеческое устройство сада сосуществуют.',
['Кролики: животные ближнего мира.','Декоративные птицы: разнообразие видов.','Садовая скульптура: человеческий след.','Фонтан и ограждение: устройство пространства.','Деревья: связь сада с пейзажем.'],
'Точная дата смерти художника спорна; разные сводки дают более поздние документальные границы. Не путай Давида с Филипсом или Саломоном Конинком. Из музейных ключевых слов нельзя вывести отдельное аллегорическое значение каждого животного. Не переносить дату другой картины на S-63. Визуальная и браузерная проверки не выполнены.',
'en/collection/s-63','S-63',6845,'Животные в саду','Animals in a Garden','XVII век; точный год не указан',5425,4049,'Dominique Provost','Рассмотри соседство разных животных и искусственное устройство сада. Найди фонтан и скульптурные детали, не объявляя каждую птицу символом без доказательств.',
[['Национальная галерея: документальные даты','https://www.nationalgallery.org.uk/artists/david-de-coninck']]);
add('jan_van_den_hecke_the_elder','Ян ван ден Хекке Старший','Jan van den Hecke I','1619/1620–1684',['Ян ван ден Хеке Старший','Jan van den Hecke the Elder','Jan I van den Hecke'],
['Ван ден Хекке работал в Антверпене; документирован как ученик в 1636–1637 и мастер гильдии в 1641–1642 годах. Был также рисовальщиком и офортистом.','Его старший сын стал художником Ян ван ден Хекке II. Одинаковые имена и близкие жанры требуют проверки поколения автора, а не только фамилии.'],
['«Натюрморт с ракообразными, фруктами и лютней», 1902-I, относится к XVII веку без точного года. Крупные пищевые формы соединены с музыкальным инструментом.','Музейный каталог выделяет омара, яблоки, лимон, виноград, драпировку и посуду. Это подтверждённые предметные опоры, не готовая единственная аллегорическая программа.'],
'Музыкальный инструмент может входить в натюрморт наряду с пищей. Для толкования важны вся композиция и её история, а не одно присутствие лютни.',
['Омар: крупная форма натюрморта.','Фрукты: яблоки, лимон и виноград.','Лютня: музыкальный предмет среди пищи.','Драпировка: мягкая поверхность.','Посуда: связь предметных групп.'],
'Текущая атрибуция — Jan I van den Hecke. В библиографии 1937 года сохранено старое имя Лодевейка ван дер Хелста; его не следует выдавать за нынешнее авторство. Лютня сама по себе не превращает любое изображение в vanitas. Полные даты и физические размеры работы не придуманы. Визуальная и браузерная проверки не выполнены.',
'collectie/1902-i','1902-I',332,'Натюрморт с ракообразными, фруктами и лютней','Still Life with Crustacea, Fruits and a Lute','XVII век; точный год не указан',3829,2733,'','Сравни твёрдый панцирь, гладкие плоды, ткань и музыкальный инструмент. Затем обрати внимание на музейную историю атрибуции и не подменяй старым именем современный паспорт.',
[['Биографическая сводка: даты и различение отца и сына','https://de.wikipedia.org/wiki/Jan_van_den_Hecke_I']]);
add('frans_van_cuyck_de_myerhop','Франс ван Кёйк де Мейерхоп','Frans van Cuyck de Myerhop','1640–1689',['Франс ван Кейк де Мейерхоп','Frans van Cuyck de Mierhop','Frans van Cuyck'],
['Гентский живописец родился в Брюгге и умер в Генте. Музей подчёркивает его дворянское положение и отсутствие членства в живописной гильдии.','Его манеру сопоставляют с наследием Фейта: тёплой земляной палитрой, светотенью и фактурой. В выбранной работе письмо сдержаннее и ближе к Питеру Булю.'],
['«Натюрморт с фруктами», 1923-N: плоды размещены на скале у тёмного пейзажа. Музей перечисляет персики, виноград, гранаты, сливы и айву в нидерландском тексте.','Более гладкая отделка сдерживает энергичное барочное воздействие. Вне изобразительного поля, внизу, каталог отмечает имя MYERHOP. F.'],
'Сходство мотива не делает живописную манеру одинаковой. Фрукты на природе позволяют сравнить сильное импасто школы Фейта с более гладким вариантом.',
['Скала: опора вместо накрытого стола.','Тёмный пейзаж: среда натюрморта.','Разные плоды: разнообразие поверхностей.','Сдержанный мазок: отличие от сильного импасто.','MYERHOP. F: подпись в каталоге.'],
'В английском музейном тексте pears, в нидерландском kweeperen — айва; различие перевода сохранено, визуальная проверка не выполнена. 1923 — год длительной передачи OCMW, не дата создания. Дворянское положение не является доказательством конкретного учителя. Подпись не заменяет отсутствующий год. Браузерная загрузка не проверена.',
'en/collection/1923-n','1923-N',3807,'Натюрморт с фруктами','Still Life with Fruit','XVII век; точный год не указан',9747,7799,'Cedric Verhelst','Сопоставь поверхность скалы, кожуру плодов и тёмный пейзаж. Сравни более гладкое письмо с густой фактурой других фламандских натюрмортов.');
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

;
/* artists-batch-70.js */
(()=>{'use strict';
const B={},M='https://www.mskgent.be/en/collection/1886-a',N='https://www.nga.gov/artworks/76210-roses-and-tulip-glass-vase',V='https://www.wikidata.org/wiki/Q118984751',J='https://www.museothyssen.org/en/collection/artists/monnoyer-jean-baptiste/bouquet-chamomile-french-roses-and-other-flowers',F='https://www.metmuseum.org/art/collection/search/189540';
function add(id,name,latin,life,aliases,bio,technique,innovation,features,caution,sources,pendingWorks=[],works=[]){B[id]={name,latin,life,tag:'Европа · цветочный натюрморт XVII–XVIII веков',aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources,pendingWorks,works,editorialStatus:works.length?'official_iiif_manifest_rights_checked_browser_pending':'text_only_image_file_and_rights_pending'};}
function pending(key,title,date,medium,museum,source){return {key,title,date,medium,museum,source,reason:'Объект установлен по указанным источникам; свободный файл изображения пока не подтверждён'};}
add('daniel_seghers','Даниэл Сегерс','Daniël Seghers','1590–1661',['Даниэль Сегерс','Даниэл Зегерс','Daniel Seghers'],
['Антверпенский художник-иезуит учился у Яна Брейгеля Старшего и специализировался на цветах. Его манера отличалась точным наблюдением, тонким мазком и согласованием красок.','Сегерс развивал цветочную гирлянду вокруг каменного картуша. Центральную фигуру святого нередко писал другой мастер, но выбранная работа 1886-A имеет пустой центр.'],
['«Цветочная гирлянда»: масло по холсту; 129,5 × 97,6 см. Внизу слева подпись Daniël Seghers Soc.tis JESV., связанная с Обществом Иисуса.','Цветы собраны независимо от срока цветения. Музей отмечает частую связь выбора растений со святым в центре, но здесь самого изображения внутри картуша нет.'],
'Гирлянда может быть частью совместной религиозной картины и одновременно самостоятельной демонстрацией мастерства цветочного живописца.',
['Каменный картуш: рамка для изображения.','Пустой центр: подтверждён музеем.','Разные сезоны: искусственно составленный венок.','Тонкий мазок: точность отдельных цветов.','Подпись иезуита: связь с религиозной средой.'],
'Не путай Даниэла с Герардом Сегерсом. Причина пустого центра не указана: не объявляй работу автоматически незаконченной. Не подставляй гирлянду с Магдалиной, где авторство фигуры предположительно связано с Корнелисом Схютом. 1886 — год покупки, не создания. Визуальная и браузерная проверки не выполнены.',
[['MSK Gent: 1886-A и пустой картуш',M],['Официальный IIIF: объект и PDM 1.0','https://imagehub.mskgent.be/iiif/3/254/manifest.json'],['Для сравнения: другая гирлянда','https://www.mskgent.be/en/collection/1953-n']],[],
[{key:'msk:1886-A',title:'Цветочная гирлянда с пустым картушем',originalTitle:'Floral Wreath',date:'XVII век; точный год не указан',medium:'Масло по холсту; 129,5 × 97,6 см',museum:'Музей изящных искусств, Гент',source:M,image:'https://imagehub.mskgent.be/iiif/2/public%2F254.tif/full/800,/0/default.jpg',zoom:'https://imagehub.mskgent.be/iiif/2/public%2F254.tif/full/1600,/0/default.jpg',imageSource:'https://imagehub.mskgent.be/iiif/3/254/manifest.json',imageWidth:5061,imageHeight:6787,license:'Public Domain Mark 1.0 по официальному IIIF-манифесту; обозначение общественного достояния, не CC0',rightsURI:'https://creativecommons.org/publicdomain/mark/1.0/',creditLine:'Museum of Fine Arts Ghent (MSK Gent), 1886-A; photograph Hugo Maertens',rightsNote:'MSK Gent выражает пожелание получить три экземпляра печатной или коммерческой публикации; цветокодированные TIFF доступны для заказа через Art in Flanders.',imageVisuallyReviewed:false,look:'Рассмотри цветы и каменный картуш отдельно. Пустой центр не заполняй воображаемым святым: музей подтверждает отсутствие центральной сцены.'}]);
add('jan_philip_van_thielen','Ян Филип ван Тилен','Jan Philips van Thielen','1618–1667',['Ян Филипс ван Тилен','Jan Philip van Thielen'],
['Ван Тилен начинал обучение у Теодора Ромбоутса, затем работал с Сегерсом. Писал самостоятельные букеты и гирлянды, сотрудничая с мастерами центральных фигур.','Его цветы часто яснее отделены друг от друга, чем у Сегерса. Пример NGA позволяет сопоставить такую манеру с маленьким подписанным изображением в стеклянной вазе.'],
['«Розы и тюльпан в стеклянной вазе», около 1650–1660: масло по дереву, 1992.51.4. Внизу в центре подпись Van. Thielen.','Исходная доска измеряется от 32 × 23,4 до 32,1 × 23,9 см из-за неровных краёв. Поздние деревянные дополнения и укрепление увеличивают общий размер предмета.'],
'Небольшой самостоятельный букет показывает, что автор гирлянд не ограничивался рамкой для чужой фигуры. Различие размеров основы и поздней конструкции важно для паспорта.',
['Розы и тюльпан: названные цветы.','Стеклянная ваза: отдельный материальный мотив.','Ясные формы: общая особенность манеры.','Малый формат: камерная картина.','Подпись внизу: авторская надпись.'],
'Не путай ван Тилена с его дочерьми-художницами. Толщина 1,5 см дана вместе с добавлениями и укреплением, не как толщина первоначальной доски. Нельзя переносить атрибуцию частной картины на NGA 1992.51.4. Страница найденной репродукции не загрузилась; свободный файл пока не подтверждён.',
[['NGA: 1992.51.4, подпись и размеры',N],['Биография и сотрудничество','https://en.wikipedia.org/wiki/Jan_Philip_van_Thielen']],
[pending('nga:1992.51.4','Розы и тюльпан в стеклянной вазе','около 1650–1660','Масло по дереву; исходная доска около 32 × 24 см','Национальная галерея искусства, Вашингтон',N)]);
add('gaspar_peeter_verbruggen_the_elder','Гаспар Петер Вербрюгген Старший','Gaspar Peeter Verbruggen the Elder','1635–1681',['Гаспар Питер Вербрюгген Старший','Gaspar Pieter Verbruggen I','Gaspar Peeter de Verbruggen the Elder'],
['Фламандский мастер специализировался на цветах и гирляндах. Его картины могли включать вазу, нишу, фигуру или религиозный образ в цветочном обрамлении.','Сын с тем же именем тоже стал цветочным живописцем. Поэтому обозначения Старший и Младший должны сохраняться при сопоставлении музейных объектов.'],
['«Цветочная композиция», R.1919-55, относится к собранию Ipswich Borough Council. Art UK датирует её после 1658; Wikidata сопоставляет автора, инвентарь и холст.','Дата после 1658 не равна 1659. Название Flower Piece распространено и встречается также у неизвестных авторов, последователей и сына Вербрюггена.'],
'Надёжное разграничение одноимённых художников и предметов предшествует стилевому сравнению. Сама общность цветочного жанра не устанавливает руку автора.',
['Цветочный жанр: предмет картины.','Холст: материал основы по каталожным данным.','После 1658: открытая датировка.','R.1919-55: идентификация предмета.','Старший мастер: отличие от сына.'],
'Не подставляй Flower Piece из Elizabethan House Museum: это работа Младшего 1664–1730. Вариант Paisley относится лишь к стилю Старшего. Сведения о текущем объекте сопоставлены по Art UK и Wikidata, не по перепродаже репродукций. Конкретный свободный файл пока не подтверждён.',
[['Art UK: музейные работы Старшего','https://artuk.org/discover/artists/de-verbruggen-the-elder-gaspar-peeter-16351681'],['Wikidata: объект и инвентарь',V],['Для различения: наследие Младшего','https://commons.wikimedia.org/wiki/Category:Gaspar_Peeter_Verbruggen_(II)']],
[pending('ipswich:R1919-55','Цветочная композиция','после 1658 по Art UK','Масло по холсту','Colchester and Ipswich Museums Service, Ipswich Borough Council Collection',V)]);
add('jean_baptiste_monnoyer','Жан-Батист Моннуайе','Jean-Baptiste Monnoyer','1636–1699',['Жан Батист Моннуайе','Жан-Батист Моннойе','Jean Baptiste Monnoyer'],
['Моннуайе обучался в Антверпене, работал во Франции и Англии. Его цветы предназначались не только для самостоятельных картин, но и для дворцового декора и шпалер.','Гравированные сборники распространяли композиции среди мастеров тканей и вышивки. Маленькие парные букеты Тиссена отличаются от его больших декоративных урн более тонкой отделкой.'],
['«Букет с ромашками, французскими розами и другими цветами»: без даты по паспорту, масло по холсту; 37 × 34,4 см, CTB.1987.6.','Музей описывает пару скромных букетов, перевязанных голубой лентой, на тёмном фоне. В них соединены весенние и летние растения, вероятно по сохранённым натурным рисункам.'],
'Натуралистический вид не означает, что весь букет одновременно стоял перед художником. Архив рисунков помогал соединять сезонно несовместимые растения.',
['Камерность: небольшое полотно.','Голубая лента: связывает букет.','Тёмный фон: выделяет цветы.','Разные сезоны: продуманная комбинация.','Тонкая отделка: отличие от большого декора.'],
'Дата s.f. означает отсутствие датировки, не конкретный год. Ботанический перечень в тексте относится к обоим парным букетам: не переносить все виды на каждый. Не подменяй картину гравюрой из книги Моннуайе. Свободный файл и условия фотографии пока не подтверждены.',
[['Музей Тиссена: CTB.1987.6 и описание пары',J],['Dumbarton Oaks: декор и распространение гравюр','https://www.doaks.org/resources/online-exhibits/robert-and-monnoyer/jean-baptiste-monnoyer'],['Метрополитен: отдельная гравюра, не выбранный холст','https://www.metmuseum.org/art/collection/search/626200']],
[pending('thyssen:CTB.1987.6','Букет с ромашками, французскими розами и другими цветами','без даты по музейному паспорту','Масло по холсту; 37 × 34,4 см','Собрание Кармен Тиссен, Мадрид',J)]);
add('jean_baptiste_belin_de_fontenay','Жан-Батист Белен де Фонтене Старший','Jean-Baptiste Belin de Fontenay the Elder','1653–1715',['Жан Батист Белен де Фонтене','Jean-Baptiste Blin de Fontenay','Jean-Baptiste Belin de Fontenay I'],
['Белен де Фонтене родился в Кане и умер в Париже. Он был связан с Моннуайе как ученик и зять, работал с цветочным декором королевских резиденций.','Выбранная картина Метрополитен-музея находится в отделе европейской скульптуры и декоративного искусства. Такой контекст отличает её от ботанической иллюстрации.'],
['«Ваза с цветами», конец XVII века: масло по холсту; 73 × 86,7 см, 07.225.274. Музей классифицирует её как декоративную живопись.','Горизонтальный формат и цветочный предмет позволяют сопоставить её с маленьким вертикальным букетом ван Тилена. Точное первоначальное помещение выбранной картины в приведённом паспорте не установлено.'],
'Цветочная картина существует между самостоятельным натюрмортом и оформлением интерьера. Биография придворного мастера не доказывает королевское происхождение каждой его работы.',
['Цветочная ваза: основной предмет.','Горизонталь: формат 73 × 86,7 см.','Холст: живописная основа.','Декоративная классификация: музейный контекст.','Конец XVII века: осторожная датировка.'],
'Не путай Старшего с сыном 1688–1730. Номер 07.225.274 и дар Моргана 1906 года относятся к истории коллекции, не к созданию. Не выдавай эту прямоугольную картину за круглый вазон Louvre INV 8926 диаметром 95 см. API с конкретным изображением не загрузился; общая политика Open Access не заменяет проверку файла.',
[['Метрополитен: 07.225.274 и классификация',F],['Для различения: круглая картина Лувра','https://collections.louvre.fr/en/ark:/53355/cl010236665'],['Биографическая сводка: семья и дворцовые заказы','https://en.wikipedia.org/wiki/Jean-Baptiste_Belin']],
[pending('met:189540','Ваза с цветами','конец XVII века','Масло по холсту; 73 × 86,7 см','Метрополитен-музей, Нью-Йорк',F)]);
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

;
/* artists-batch-71.js */
(()=>{'use strict';
const N='https://www.nationalgallery.org.uk/',R='https://www.rijksmuseum.nl/en/collection/object/',B={};
function add(id,name,latin,life,tag,aliases,bio,technique,innovation,features,caution,sources,key,title,date,medium,museum,source,work=null){B[id]={name,latin,life,tag,aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources,works:work?[work]:[],pendingWorks:work?[]:[{key,title,date,medium,museum,source,reason:'Музейный оригинал установлен; свободный файл репродукции не подключён'}],editorialStatus:work?'museum_cc0_file_checked_browser_pending':'text_only_image_file_and_rights_pending'};}
add('pieter_claesz','Питер Клас','Pieter Claesz','1597/1598–1660','Нидерланды · монохромный банкетный натюрморт',['Питер Клаас','Клас'],
['Клас поселился в Харлеме к 1617 году и стал ведущим мастером банкетного натюрморта. В приглушённой палитре он исследовал свет, фактуру и перспективу; позднее стал использовать более выразительные цвета.','Некоторые завтраки выглядят как случайно оставленный стол, но предметы тщательно отобраны и расположены. Картина 1935.300 показывает роскошное, хорошо сохранившееся угощение, а не vanitas с явными знаками распада.'],
['Масло по дереву; 48 × 76,9 см, AIC 1935.300. На ножевом лезвии — связанная монограмма PC. Вантаж сочетается с лаконичными повседневными сосудами и пищей.','Лимон, оливки, сладости и кружевная дамастовая скатерть демонстрируют дорогие товары. Олово, стекло, хрустящий хлеб и влажная кожура лимона различаются светом и фактурой.'],
'Натюрморт совмещает зрительное удовольствие и знание о международной торговле. Повреждённая или увядающая пища могла усиливать тему бренности, но здесь хорошо сохранённые предметы подчёркивают богатство.',
['Монограмма PC: подпись на лезвии ножа.','Дамаст: кружевной край скатерти.','Китайская чаша Wanli: импортная посуда.','Олово и стекло: разные отражающие поверхности.','1620–1630: широкий музейный интервал датировки.'],
'Музей даёт общий интервал 1620–1630, не точный год 1625 из вторичных сайтов. Не путай 1935.300 с более ранними завтраками Класа. AIC прямо обозначает этот файл CC0; правило относится к изображению указанного произведения, а не ко всем изображениям натюрмортов.',
[['Art Institute of Chicago: 1935.300 и CC0','https://www.artic.edu/artworks/21682/still-life'],['Art Institute: условия открытого доступа','https://www.artic.edu/open-access/open-access-images'],['Национальная галерея: биография',N+'artists/pieter-claesz']],
'aic:21682','Натюрморт','1620–1630','Масло по панели; 48 × 76,9 см','Art Institute of Chicago','https://www.artic.edu/artworks/21682/still-life',
{key:'aic:21682',title:'Натюрморт',originalTitle:'Still Life',date:'1620–1630 по музею; около 1625 в заголовке файла',medium:'Масло по панели; 48 × 76,9 см',museum:'Art Institute of Chicago',source:'https://www.artic.edu/artworks/21682/still-life',image:'https://www.artic.edu/iiif/2/6b2e2df2-993c-e29b-320e-16c9fa61af02/full/843,/0/default.jpg',zoom:'https://www.artic.edu/iiif/2/6b2e2df2-993c-e29b-320e-16c9fa61af02/full/1686,/0/default.jpg',imageSource:'https://www.artic.edu/artworks/21682/still-life',license:'CC0 1.0 Public Domain Designation по странице Art Institute of Chicago',imageVisuallyReviewed:false,look:'Найди лимон, оливки, сладости и кружевной край скатерти. Сравни холодный отблеск олова с прозрачностью стекла. Монограмма PC находится на лезвии ножа; музей считает предметы скорее демонстрацией достатка, чем образами упадка.'});
add('willem_claesz_heda','Виллем Клас Хеда','Willem Claesz. Heda','1594–1680','Нидерланды · тональный банкетный натюрморт',['Виллем Хеда','Хеда'],
['Хеда жил и работал в Харлеме. Вместе с Класом он стал одним из главных мастеров почти монохромного ontbijtje — банкетного натюрморта с тщательно расставленными предметами.','Его композиции ценились за способность передавать металл, стекло, дамаст и пищу ограниченным диапазоном серых и коричневых тонов.'],
['«Натюрморт с позолоченной чашей», 1635: масло по панели; 87,8 × 112,6 см, SK-A-4830. Картина подписана HEDA. 1635 на ткани справа.','Олово, серебро, дамаст, стекло и перламутр различаются нюансами серого; жёлтые и охристые акценты поддерживают равновесие. Рёмер, tazza, хлеб, устрицы и хлебные сосуды выстроены по диагоналям.'],
'Ограниченный цвет не упрощает предметы, а делает различие поверхностей главным зрительным событием. Музей считает эту большую композицию одной из самых представительных работ Хеды.',
['Подпись HEDA: 1635 на ткани.','Почти монохромная палитра: серые тона.','Позолоченная чаша: яркий акцент.','Опрокинутая tazza: повторяющийся мотив Хеды.','Перламутр и дамаст: точная игра отражений.'],
'Не смешивай SK-A-4830 с «Натюрмортом с серебряной tazza» 1630 года SK-C-1694 или крабами NG1469. Датировка и подпись для выбранного предмета точны; файл репродукции пока не подключён.',
[['Рейксмюсеум: SK-A-4830, подпись и описание',R+'Still-Life-with-a-Gilt-Cup--4617db9a8506653eb2437fc6bde903fd'],['Рейксмюсеум: техническая статья о tazza','https://www.rijksmuseum.nl/en/collection/SK-C-1694/catalogus-entry'],['Национальная галерея: сравнительный натюрморт с крабом',N+'paintings/willem-claesz-heda-still-life-pewter-and-silver-vessels-and-a-crab']],
'rijks:SK-A-4830','Натюрморт с позолоченной чашей','1635','Масло по панели; 87,8 × 112,6 см','Рейксмюсеум, Амстердам',R+'Still-Life-with-a-Gilt-Cup--4617db9a8506653eb2437fc6bde903fd')
add('aelbert_cuyp','Аэлберт Кёйп','Aelbert Cuyp','1620–1691','Нидерланды · золотистый речной пейзаж',['Альберт Кёйп','Альберт Кейп','Aelbert Cuyp'],
['Кёйп родился и работал в Дордрехте, писал портреты, пейзажи, натюрморты и животных. Он стал самым известным представителем семьи художников Кёйпов.','Итальянские путешествия местных художников, включая Яна Бота, помогли направить его интерес к большим светлым пейзажам с атмосферой Рима.'],
['«Речной пейзаж с всадником и крестьянами», около 1658–1660: масло по дубу; 123 × 241 см, NG6522. Подпись A cuijp находится справа внизу.','Пастух ведёт животных к реке, путники едут по грунтовой дороге, а конный всадник резко смотрит за пределы картины. Рельеф и дальняя вода формируют широкий маршрут взгляда.'],
'Солнечный свет создаёт гармонию, но выразительный всадник в алом плаще нарушает спокойствие. Его движение и взгляд дают намёк на возможное событие за кадром, не раскрывая его.',
['Золотистый свет: атмосфера южного пейзажа.','Всадник: тёмный акцент и взгляд за кадр.','Река и холмы: широкий путь через картину.','Пастух и животные: обычная жизнь в пейзаже.','Подпись художника: A cuijp справа внизу.'],
'Пейзаж воображаем: горный масштаб не соответствует низменному ландшафту Нидерландов, хотя Кёйп мог использовать наблюдения и зарисовки реальных мест. Картина, вероятно, была уменьшена по высоте после 1764 года; музей приводит нынешний размер 123 × 241 см. Не называй её буквальной картой окрестностей Дордрехта.',
[['Национальная галерея: NG6522, размер и история',N+'paintings/aelbert-cuyp-river-landscape-with-horseman-and-peasants'],['Национальная галерея: каталог 1991, провенанс и уменьшение холста',N+'paintings/catalogues/maclaren-and-brown-1991/river-landscape-with-horseman-and-peasants'],['Национальная галерея: биография',N+'artists/aelbert-cuyp']],
'ng:NG6522','Речной пейзаж с всадником и крестьянами','около 1658–1660','Масло по дубу; 123 × 241 см','Национальная галерея, Лондон',N+'paintings/aelbert-cuyp-river-landscape-with-horseman-and-peasants')
add('herman_saftleven','Херман Сафтлевен','Herman Saftleven','1609–1685','Нидерланды · рельефный речной пейзаж',['Херман Сафтлевен Младший','Herman Saftleven the Younger'],
['Сафтлевен родился в Роттердаме и в 1632 году переехал в Утрехт. Он писал пейзажи, портреты и натюрморты; его индивидуальный стиль сложился в рейнских видах после путешествия по Германии.','Эти пейзажи узнаваемы по округлым скалам, оголённым каменным стенам и замкам на вершинах. Экономные зелёные и коричневые тона придают местности особую фактуру.'],
['«Рейнский пейзаж с башнями замка», около 1660: масло по дубу; 38,7 × 50 см, NG991. Подпись HSaftleven находится внизу справа.','Река и дорога изгибаются среди скал; небольшие группы путников и фигур у замка задают масштаб. Горный рельеф повторяет опыт художника, который посещал Рейнскую область в 1650-е годы.'],
'Пейзаж показывает наблюдение натуры не через обилие цвета, а через структуру породы, путь и башни. Вымышленность отдельных видов сохраняется, даже если в основе лежит реальный опыт путешествий.',
['Округлые скалы: характерный рельеф.','Рейнские башни: архитектура на вершине.','Изгиб реки: ведёт взгляд в глубину.','Малые путники: масштаб местности.','Подпись HSaftleven: авторская отметка.'],
'NG991 не следует смешивать с более поздними рисунками Рейна или городскими видами Утрехта. Дата около 1660 приблизительна, но подпись присутствует. Не каждый каменный пейзаж Сафтлевена изображает одну и ту же реальную долину.',
[['Национальная галерея: NG991 и рельеф',N+'paintings/herman-saftleven-a-rhine-landscape-with-castle-towers'],['Национальная галерея: биография',N+'artists/herman-saftleven']],
'ng:NG991','Рейнский пейзаж с башнями замка','около 1660','Масло по дубу; 38,7 × 50 см','Национальная галерея, Лондон',N+'paintings/herman-saftleven-a-rhine-landscape-with-castle-towers')
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

;
/* artists-batch-72.js */
(()=>{'use strict';
const N='https://www.nationalgallery.org.uk/',B={};
function add(id,name,latin,life,tag,aliases,bio,technique,innovation,features,caution,num,title,originalTitle,date,medium,slug,look,artistSlug){const source=N+'paintings/'+slug;B[id]={name,latin,life,tag,aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources:[['Национальная галерея: '+num,source],...(artistSlug?[['Национальная галерея: биография',N+'artists/'+artistSlug]]:[])],works:[],pendingWorks:[{key:'ng:'+num,title,originalTitle,date,medium,museum:'Национальная галерея, Лондон',source,look,reason:'Музейный оригинал установлен; свободный файл репродукции и права на него не проверены, изображение не подключено'}],editorialStatus:'text_only_image_file_and_rights_pending'};}
add('jan_lingelbach','Ян Лингельбах','Jan Lingelbach','1622–1674','Нидерланды · жанровая сцена и пейзаж',['Johannes Lingelbach','Лингельбах'],
['Лингельбах родился во Франкфурте, а затем его семья переехала в Амстердам. Национальная галерея характеризует его как мастера фигур: он, вероятно, дописывал людей в пейзажах других художников.','В «Крестьянах, нагружающих телегу сеном» сельская жизнь превращена в множество небольших историй. Галерея связывает подобные сцены со вкусами городских покупателей и отмечает влияние Филипса Ваувермана.'],
['Картина 1664 года написана маслом на холсте, подписана и датирована. Группы людей распределены так, чтобы зритель мог переходить от одного эпизода к другому.','Белая лошадь — один из повторяющихся мотивов, связывающих Лингельбаха с Вауверманом. Но внимание удерживает не только животное: жесты и действия фигур задают разные повествовательные центры.'],
'Пейзаж здесь становится пространством рассказа: зритель не просто узнаёт сельскую местность, а сопоставляет действия людей. Это особенность выбранной картины, а не заявление, что Лингельбах изобрёл жанр.',
['Множество эпизодов: рассмотри каждую группу отдельно.','Телега с сеном: найди главное трудовое действие.','Белая лошадь: сравни её заметность с маленькими фигурами.','Жесты путников: музей предполагает, что пара спрашивает дорогу.','Собаки и мальчик: небольшой конфликт оживляет общую сцену.'],
'Выбрана подписанная и датированная NG837. Не подменяй её «Римской уличной сценой с игроками в карты» NG6640: у той музей сохраняет атрибуцию «возможно, Лингельбах». Сельская сцена рассчитана на зрителя и не является нейтральной фиксацией крестьянского быта.',
'NG837','Крестьяне, нагружающие телегу сеном','Peasants loading a Hay Cart','1664','Масло на холсте; 70 × 88,7 см','jan-lingelbach-peasants-loading-a-hay-cart',
'Проследи путь от погрузки сена к паре, предположительно спрашивающей дорогу, а затем к мальчику, который пытается остановить драку собак. Отделяй видимое действие от музейного предположения о разговоре путников.','jan-lingelbach');
add('meindert_hobbema','Мейндерт Хоббема','Meindert Hobbema','1638–1709','Нидерланды · пейзаж',['Мейндерт Гоббема','Хоббема'],
['Хоббема — голландский пейзажист. Национальная галерея отмечает, что после получения постоянной оплачиваемой работы он стал писать значительно меньше.','«Аллея в Мидделхарнисе» создана в 1689 году, примерно через двадцать лет после того, как живопись перестала быть его основной профессией. Это поздняя работа, чьё устройство заметно отличается от многих его лесных пейзажей.'],
['Масло на холсте. Дорога и повторяющиеся стволы направляют взгляд к глубине картины, а высокие вертикали деревьев заставляют одновременно смотреть вверх.','Композиция не замыкается на центральном проходе: боковая дорога и открытые участки местности уводят взгляд в стороны. Так движение к горизонту сочетается с рассматриванием окружающего пространства.'],
'Знакомый мотив дороги организован как система разнонаправленных зрительных движений. Прямая перспектива не превращает картину в схему: боковые выходы сохраняют широту пейзажа.',
['Сходящаяся дорога: проследи её направление в глубину.','Ряд стволов: сравни интервалы и размеры деревьев.','Высокие вертикали: посмотри, как они связывают землю и небо.','Боковой поворот: найди выход из центральной аллеи.','Открытые поля: сопоставь широту местности с узким коридором дороги.'],
'Выбрана лондонская NG830, датированная 1689 годом, а не уменьшенная копия. Не переноси описание этой необычной композиции на всё творчество Хоббемы. Здесь намеренно не добавлены неподтверждённые размеры и ботанические пояснения.',
'NG830','Аллея в Мидделхарнисе','The Avenue at Middelharnis','1689','Масло на холсте','meindert-hobbema-the-avenue-at-middelharnis',
'Сначала следуй взглядом по дороге к дальнему плану. Затем найди боковой поворот и открытые поля: они выводят взгляд из центрального коридора. Сравни движение в глубину с вертикальным ритмом деревьев.','meindert-hobbema');
add('philips_wouwerman','Филипс Вауверман','Philips Wouwerman','1619–1668','Нидерланды · лошади и жанровый пейзаж',['Филипс Воуверман','Philip Wouwerman','Вауверман'],
['Вауверман известен изображениями лошадей и сценами с людьми в пейзаже. Национальная галерея особенно отмечает его умение передавать шерсть животных, мягкость глаз и ощущение мышц под кожей.','В небольшой картине с белой лошадью и стариком, собирающим хворост, человек и животное показаны перед наступлением холода. Здесь конный мотив служит не парадному зрелищу, а сцене повседневного выживания.'],
['Картина 1650-х годов написана маслом на дереве, вероятно дубе, и подписана. Светлая лошадь выделяется на линии горизонта, а старик пригнулся среди растительности.','Нарастающие облака, теряющее листья дерево и развевающаяся грива объединяют разные части картины ощущением ветра и приближающейся зимы. Простая верёвочная упряжь подчёркивает будничность сцены.'],
'Яркий мотив белой лошади соединён с неброским человеческим трудом и суровой погодой. Пейзаж становится условием жизни персонажей, а не только фоном.',
['Белая лошадь: главный световой акцент на горизонте.','Пригнувшийся старик: найди, как он собирает и связывает ветки.','Женщина с младенцем: рассмотри фигуры позади него.','Облака и дерево: сравни признаки приближающегося холода.','Верёвочная упряжь: противопоставь простое снаряжение парадному конному образу.'],
'1650-е — десятилетие, а не точный год; дуб указан музеем предположительно. Версия о моральном назначении картины и её размещении в тёплом городском доме — музейная гипотеза, не установленное намерение заказчика.',
'NG881','Белая лошадь и старик, связывающий хворост','A White Horse, and an Old Man binding Faggots','1650-е','Масло на дереве, вероятно дубе; 31,8 × 26,3 см','philips-wouwerman-a-white-horse-and-an-old-man-binding-faggots',
'Сравни заметную белую лошадь с тёмной, пригнувшейся фигурой старика. Затем найди женщину с младенцем и проследи, как облака, ветви и грива создают общее ощущение ветра.');
add('frans_van_mieris_the_elder','Франс ван Мирис Старший','Frans van Mieris the Elder','1635–1681','Нидерланды · Лейден · тонкая жанровая живопись',['Франс ван Мирис','Frans van Mieris','Frans van Mieris I'],
['Ван Мирис родился и работал в Лейдене, учился у Абрахама ван ден Темпела и Геррита Доу. Он был одним из успешных жанровых и портретных мастеров своего времени.','Крошечная «Женщина в красной кофте, кормящая попугая» пользовалась большим успехом и многократно копировалась. Простое прерванное занятие стало поводом для чрезвычайно подробной передачи тканей и предметов.'],
['Масло на меди; 22,5 × 17,3 см. Музей отмечает почти незаметные мазки и тонкость передачи фактур на гладкой основе.','Женщина протягивает серому попугаю миндаль. Напёрсток на пальце показывает, что она прервала шитьё. Красная одежда, ткани и отделка стула получают различимую материальность в очень небольшом формате.'],
'Незначительное действие становится сложным зрительным опытом: внимательность к жесту соединена с демонстрацией мастерства в передаче поверхностей. Это разбор конкретной картины, не утверждение о первенстве художника.',
['Миндаль в руке: найди предмет взаимодействия женщины и птицы.','Напёрсток: след прерванного шитья.','Красная кофта: сравни ткань с другими поверхностями.','Серый попугай: сопоставь оперение с гладкостью кожи.','Отделка стула: рассмотри мелкие детали на малом формате.'],
'Моделью предположительно была жена художника Кюнера ван де Кок; это не бесспорное отождествление. Около 1663 года — приблизительная дата. Основа — медь, не дерево. Не путай Франса Старшего с Виллемом ван Мирисом или поздними копиями по его композициям.',
'NG840','Женщина в красной кофте, кормящая попугая','A Woman in a Red Jacket feeding a Parrot','около 1663','Масло на меди; 22,5 × 17,3 см','frans-van-mieris-the-elder-a-woman-in-a-red-jacket-feeding-a-parrot',
'Найди напёрсток и миндаль: эти две детали связывают шитьё с кормлением птицы. Затем сопоставь ткань одежды, кожу руки, оперение и отделку стула. Малый размер оригинала особенно важен для оценки тонкости работы.','frans-van-mieris-the-elder');
add('jan_van_goyen','Ян ван Гойен','Jan van Goyen','1596–1656','Нидерланды · речной пейзаж',['Jan Josephsz. van Goyen','Ван Гойен'],
['В выбранном «Речном пейзаже» ван Гойен объединяет воду, огромное небо и повседневную жизнь прибрежного поселения. Сдержанные цветовые отношения поддерживают спокойствие сцены.','Национальная галерея относит картину к нескольким вариантам одного вида, которые художник писал в течение своей карьеры. Деревня при этом не идентифицирована.'],
['Масло на дереве, вероятно дубе; 66 × 96,5 см. Мягкие приглушённые цвета сейчас дополнительно изменены пожелтевшим лаком, о чём предупреждает музей.','Небольшая лодка, паром с пассажирами и тяжёлой повозкой, коровы у воды и церковный шпиль связывают широкий пейзаж с отдельными человеческими занятиями.'],
'Спокойствие возникает не из отсутствия событий: движение лодок и жизнь берегов включены в протяжённое пространство воды и неба. Неброские тональные отношения позволяют соединить разные мотивы.',
['Обширное небо: сравни его масштаб с поселением.','Малая лодка: проследи направление движения и рябь воды.','Паром с повозкой: найди пассажиров и двух лошадей.','Коровы у берега: отметь близкий план.','Церковный шпиль: найди вертикальный акцент среди крыш.'],
'Не называй деревню конкретным установленным местом: музей прямо сообщает, что она не опознана. Пожелтевший лак влияет на нынешний цвет, поэтому репродукция не позволяет безоговорочно судить об исходной палитре. Дуб указан предположительно.',
'NG151','Речной пейзаж','A River Landscape','1645','Масло на дереве, вероятно дубе; 66 × 96,5 см','jan-van-goyen-a-river-landscape',
'Сопоставь небольшую движущуюся лодку с паромом, на котором стоит тяжёлая повозка. Затем найди коров и шпиль: эти разномасштабные детали соединяют ближний берег, реку и дальнюю деревню.');
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

;
/* artists-batch-73.js */
(()=>{'use strict';
const N='https://www.nationalgallery.org.uk/',B={};
function add(id,name,latin,life,aliases,tag,bio,technique,innovation,features,caution,key,title,originalTitle,date,medium,museum,source,look,extra=[]){B[id]={name,latin,life,tag,aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources:[[museum+': '+title,source],...extra],works:[],pendingWorks:[{key,title,originalTitle,date,medium,museum,source,look,reason:'Музейный оригинал установлен; свободный файл репродукции и права на него не проверены. Изображение не подключено.'}],editorialStatus:'text_only_image_file_and_rights_pending'};}
add('jan_porcellis','Ян Порселлис','Jan Porcellis','около 1584–1632',['Ян Порцеллис','Порселлис'],'Нидерланды · тональная морская живопись',
['Порселлис — мастер морского пейзажа, родившийся около 1584 года в Генте и умерший в 1632 году в Зутервауде. Его работы позволяют рассматривать море не только как место действия кораблей, но и как изменчивую среду.','Музей Бойманса — ван Бёнингена противопоставляет его подход ранним маринистам, любившим изображать определённые суда: в выбранной картине главным становится состояние воздуха, воды и ветра. Это музейная оценка его роли, а не безусловное доказательство единоличного изобретения атмосферной марины.'],
['«Устье реки в штормовую погоду», около 1630: масло на дереве; 58 × 80,5 см. Серые цветовые отношения не исключают богатства оттенков: важны переходы между водой, воздухом и дальними судами.','Крупная гребная лодка на переднем плане сопоставлена с гораздо меньшими кораблями у горизонта. Разница масштабов создаёт ощущение огромного пространства, не требуя подробного изображения каждого дальнего судна.'],
'Акцент смещается с узнаваемости отдельного корабля на общее состояние морского пространства. Тональные отношения и масштаб предметов работают вместе: изображение кажется сдержанным по цвету, но протяжённым и атмосферным.',
['Серая гамма: ищи различия оттенков, а не отсутствие цвета.','Крупная лодка: отметь её близость к зрителю.','Малые корабли: сопоставь их с лодкой переднего плана.','Дальний горизонт: проследи размах пространства.','Ветер и воздух: рассматривай суда как части общей среды.'],
'Около 1630 года — приблизительная дата. Не смешивай Яна с Юлиусом Порселлисом. Карточка относится к музейному предмету 1675 (OK); утверждение о первенстве художника в передаче атмосферы принадлежит музейному описанию и здесь не превращается в универсальный исторический факт.',
'boijmans:1675-OK','Устье реки в штормовую погоду','An Estuary in Stormy Weather','около 1630','Масло на дереве; 58 × 80,5 см','Музей Бойманса — ван Бёнингена, Роттердам','https://www.boijmans.nl/en/collection/artworks/2633/An-Estuary-in-Stormy-Weather/Jan-Porcellis',
'Сравни величину гребной лодки переднего плана с кораблями на горизонте. Затем посмотри, как сдержанные серые оттенки объединяют воду и воздух: пространственный размах возникает из отношений между планами, а не из подробного перечня судов.',[['Музей: Ян Порселлис','https://www.boijmans.nl/collectie/kunstenaars/14574/jan-porcellis']]);
add('simon_de_vlieger','Симон де Влигер','Simon de Vlieger','около 1601–1653',['Симон де Флигер','Simon Jacobsz. de Vlieger'],'Нидерланды · морской пейзаж',
['Де Влигер принадлежал к старшему поколению голландских маринистов XVII века. Морские картины были востребованы в стране, где торговля, военная безопасность и повседневные перевозки зависели от судов и водных путей.','Национальная галерея отмечает влияние его умения передавать состояния моря и устройство кораблей на Яна ван де Каппелле и Виллема ван де Велде Младшего. Поэтому его полезно рассматривать как самостоятельного мастера и как связующее звено между поколениями.'],
['«Голландский военный корабль и различные суда при ветре», около 1638–1645: масло на дереве, вероятно дубе; 41,2 × 54,8 см. Сильный ветер натягивает паруса, но вода остаётся сравнительно спокойной.','Фрегат справа на среднем плане и транспортное судно слева стараются идти как можно ближе к направлению ветра. Небольшая открытая лодка переднего плана движется по ветру: разные положения парусов превращают состояние погоды в читаемую систему действий.'],
'Убедительность возникает из связи среды и конструкции: ветер виден по парусам, а положение каждого судна объясняет его способ движения. Техническая наблюдательность поддерживает ощущение живой морской среды.',
['Натянутые паруса: найди признаки сильного ветра.','Фрегат справа: сравни его курс с транспортным судном слева.','Открытая лодка: отметь движение по ветру.','Спокойная вода: сопоставь её с напряжёнными парусами.','Суда на горизонте: проследи постепенное уменьшение форм.'],
'Рейнская дельта у Роттердама — вероятное, а не установленное место действия. Дуб указан предположительно, дата приблизительна. По музею, подпись находилась на куске дерева слева внизу, но потемневшая краска сделала её неразборчивой; не обещаем, что зритель сможет прочитать её по репродукции.',
'ng:NG3025','Голландский военный корабль и различные суда при ветре','A Dutch Man-of-war and Various Vessels in a Breeze','около 1638–1645','Масло на дереве, вероятно дубе; 41,2 × 54,8 см','Национальная галерея, Лондон',N+'paintings/simon-de-vlieger-a-dutch-man-of-war-and-various-vessels-in-a-breeze',
'Сравни паруса фрегата справа и транспортного судна слева с небольшой открытой лодкой переднего плана. Какие суда идут против направления ветра, а какие используют его? Относительно спокойная вода при сильном ветре помогает музею предполагать защищённую акваторию.');
add('jan_van_de_cappelle','Ян ван де Каппелле','Jan van de Cappelle','1626–1679',['Ян ван де Капелле','Jan van de Capelle'],'Нидерланды · морской пейзаж и отражения',
['Ван де Каппелле — один из ведущих голландских маринистов XVII века. В выбранной работе спокойная вода и отражения соединены с драматическим небом и церемониальным эпизодом.','Он создавал морские виды в помещении, пользуясь зарисовками и воображением. Национальная галерея подчёркивает, что для него гармоническая композиция могла быть важнее точной фиксации каждого судна.'],
['NG965, 1650: масло на дереве, вероятно дубе; 85,5 × 114,5 см. Картина подписана и датирована. Почти неподвижная вода сохраняет светлые отражения, тогда как тёмные облака создают напряжение.','Художник удлинил мачты ради изящества; небо не просто повторяется в воде, а контрастирует с ней. Дым салюта и быстро гребущая лодка справа добавляют действие в почти безветренную сцену.'],
'Реальные типы судов становятся материалом для свободно устроенной картины. Сопоставление светящейся воды и угрожающих облаков показывает, что морской пейзаж может быть убедительным без буквального совпадения всех природных и технических деталей.',
['Светлая вода: рассмотри почти неподвижные отражения.','Тёмные облака: сравни их с поверхностью моря.','Удлинённые мачты: проследи изящество вертикалей.','Пушечный дым: найди источник салюта.','Лодка справа: сравни её поспешность с общей неподвижностью.'],
'Это NG965, 1650 год, не сходная по названию NG966 середины 1660-х. Салют не доказывает изображение боя. Предположение, что выстрел приветствует отъезд важного пассажира, принадлежит музею; точный статус человека и ведомственная принадлежность яхты не установлены. Дуб указан предположительно.',
'ng:NG965','Голландская яхта, стреляющая салют, среди судов на якоре','A Dutch Yacht firing a Salute as a Barge pulls away, and Many Small Vessels at Anchor','1650','Масло на дереве, вероятно дубе; 85,5 × 114,5 см','Национальная галерея, Лондон',N+'paintings/jan-van-de-cappelle-a-shipping-scene-with-a-dutch-yacht-firing-a-salute',
'Начни со светлой воды, затем переведи взгляд на тяжёлые облака. Найди дым салюта и удаляющуюся лодку справа. Слева на пароме находятся пассажиры и две лошади: сравни эту будничную переправу с официальной яхтой.');
add('willem_van_de_velde_the_younger','Виллем ван де Велде Младший','Willem van de Velde the Younger','1633–1707',['Виллем ван де Вельде Младший','Willem van de Velde II'],'Нидерланды · морская живопись и корабельная точность',
['Виллем ван де Велде Младший работал в художественной семье: его отец, Виллем Старший, создавал подробные рисунки судов, а брат Адриан стал пейзажистом. Национальная галерея отмечает использование сыном корабельных рисунков отца в живописи.','«Голландская яхта, стреляющая салют» — наиболее крупная и сложная из его картин в собрании Национальной галереи. Обычная морская церемония превращена в представительное зрелище с кораблями, чиновниками, флагами и музыкантами.'],
['NG978, 1661: масло на холсте; 90 × 126 см. Картина подписана и датирована. Низкая точка зрения раскрывает огромное небо; вертикальные мачты уравновешивают сложный рисунок парусов и рангоута.','В центре государственная яхта с гербами Голландии и Амстердама салютует приближающимся чиновникам. Дым выстрела, трубачи и лодки соединены с точной передачей устройства судов.'],
'Точность корабельного изображения не исключает композиционного спектакля: технические подробности, гербы и движения людей делают церемонию одновременно убедительной и торжественной. Это характеристика выбранной картины, не универсальная формула всех работ мастера.',
['Низкий горизонт: отметь масштаб открывшегося неба.','Прямые мачты: найди опоры сложной композиции.','Государственная яхта: рассмотри центральное судно.','Салют и трубачи: сопоставь зрительные знаки церемонии.','Частная яхта справа: найди отличающийся вымпел.'],
'Не смешивай Младшего с его отцом Виллемом Старшим или братом Адрианом. Инициалы W/VV на вымпеле справа позволяют музею предполагать семейную яхту, но отождествление фигур с художниками остаётся спорным. Возможный маршрут чиновников к флоту также не установлен окончательно.',
'ng:NG978','Голландская яхта, стреляющая салют','A Dutch Yacht surrounded by Many Small Vessels, saluting as Two Barges pull alongside','1661','Масло на холсте; 90 × 126 см','Национальная галерея, Лондон',N+'paintings/willem-van-de-velde-a-dutch-yacht-saluting',
'Найди государственную яхту в центре, дым салюта и лодку чиновников рядом. Сравни официальный церемониал с посадкой людей на маленькую яхту справа. Инициалы на вымпеле — основание для гипотезы, а не доказанный групповой портрет семьи.');
add('ludolf_bakhuizen','Людолф Бакхёйзен','Ludolf Bakhuizen','1630/1631–1708',['Людольф Бакхёйзен','Людольф Бакхейзен','Ludolf Backhuysen'],'Нидерланды · морской пейзаж и непогода',
['Бакхёйзен специализировался на морских видах. Выбранная работа соединяет военные корабли и обычные транспортные суда на ветреной акватории Зёйдерзе.','Национальная галерея выделяет его способность передавать глубину, силу и неспокойное движение воды. Но важным героем NG204 становится не только флот: транспортное судно с пассажирами показывает повседневную жизнь среди опасной стихии.'],
['«Голландские военные корабли у Энкхёйзена», 1683: масло на холсте; 100,5 × 136,5 см. Картина подписана и датирована. Просвет солнца выделяет белые гребни волн, оставляя ближнюю воду почти тёмной.','Наклоны судов, натянутые паруса и высокая масса облаков передают давление ветра. Город вдалеке читается по стройной башне Зёйдеркерк, а мелкие человеческие действия создают контраст с тревожным морем.'],
'Сила воды проявляется не только в величине волн, но и в их взаимодействии с корпусами, светом и людьми. Сопоставление непогоды с невозмутимостью пассажиров делает морской вид ещё и наблюдением за привычками жизни на воде.',
['Белые гребни: проследи освещённый участок моря.','Тёмная ближняя вода: сравни её с солнечным просветом.','Наклонённые суда: найди разные реакции на волнение.','Башня вдали: отыщи ориентир Энкхёйзена.','Пассажиры транспорта: найди женщину, занятую едой.'],
'Не называй сцену конкретным установленным сражением. Музей обсуждает повреждение мачты, но не знает, отправляются ли военные корабли в бой или возвращаются. NG204 относится к Энкхёйзену; это не другая работа Бакхёйзена с неопределённым видом у Дордрехта. Год рождения в музейной записи дан как 1630/1631.',
'ng:NG204','Голландские военные корабли у Энкхёйзена','Dutch Men-of-war and Small Vessels in a Fresh Breeze off Enkhuizen','1683','Масло на холсте; 100,5 × 136,5 см','Национальная галерея, Лондон',N+'paintings/ludolf-bakhuizen-dutch-men-of-war-off-enkhuizen',
'Сравни белые гребни волн с тёмной водой переднего плана. Затем найди транспортное судно с пассажирами и женщину, которая ест суп: её спокойствие особенно заметно рядом с качкой и напряжёнными парусами.');
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

