/* artists-batch-74.js */
(()=>{'use strict';
const N='https://www.nationalgallery.org.uk/',R='https://www.rmg.co.uk/collections/objects/',B={};
function add(id,name,latin,life,aliases,tag,bio,technique,innovation,features,caution,key,title,originalTitle,date,medium,museum,source,look){B[id]={name,latin,life,tag,aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources:[[museum+': '+title,source]],works:[],pendingWorks:[{key,title,originalTitle,date,medium,museum,source,look,reason:'Музейный оригинал установлен; свободный файл репродукции и права на него не проверены. Изображение не подключено.'}],editorialStatus:'text_only_image_file_and_rights_pending'};}
add('willem_van_de_velde_the_elder','Виллем ван де Велде Старший','Willem van de Velde the Elder','XVII век',['Виллем ван де Вельде Старший','Willem van de Velde I'],'Нидерланды и Англия · морская живопись пером',
['Ван де Велде Старший прежде всего рисовал корабли и наблюдал действия флотов. Его сын Виллем Младший стал партнёром в семейной мастерской морской живописи.','С 1653 года Старший официально сопровождал голландский флот. При первом сражении у Схоневелда он делал зарисовки уже с английской стороны; картину закончил через одиннадцать лет после события.'],
['Гризайль пером и кистью на холсте; 54,4 × 74,6 см. Тонкая линия передаёт оснастку и множество корабельных подробностей, а кисть помогает обозначить тени, облака и волны.','Высокая точка зрения превращает бой в панораму. Основные столкновения расположены на среднем плане; разные направления движения эскадр сведены в тщательно устроенную композицию.'],
'Наблюдения очевидца переработаны в подробную ретроспективную панораму. Живопись пером соединяет возможности рисунка с масштабом и завершённостью самостоятельной картины.',
['Высокая точка: проследи обзор всей акватории.','Тонкая линия: сравни мачты и снасти.','Средний план: найди главные столкновения.','Встречные курсы: проследи направления эскадр.','Монохромные тона: сравни корабли, воду и дым.'],
'1673 год относится к сражению, 1684 — к созданию картины. Не смешивай Старшего с Младшим из батча 73. Музейная схема идентификации судов сохранилась лишь частично разборчивой; не обещаем прочитать все названия по репродукции.',
'rmg:BHC0305','Первое сражение при Схоневелде, 28 мая 1673 года','The First Battle of Schooneveld, 28 May 1673','1684; изображено сражение 1673 года','Гризайль: перо и кисть на холсте; 54,4 × 74,6 см','Национальный морской музей, Гринвич',R+'rmgc-object-11797',
'Начни с общей панорамы, затем найди основные столкновения на среднем плане. Сравни линейную передачу снастей с тональными участками воды и облаков. Картина основана на наблюдениях, но написана не непосредственно во время боя.');
add('hendrick_dubbels','Хендрик Дюббелс','Hendrick Dubbels','1621–1707',['Хендрик Дуббелс','Hendrik Dubbels'],'Нидерланды · штиль и морские отражения',
['Дюббелс был успешным голландским маринистом и обучал Людолфа Бакхёйзена. Он писал и штормы, но особенно известен спокойной водой, отражениями и цветом неба.','В выбранной картине безветрие не означает полного отсутствия действия: один человек наблюдает за судами с берега, а на яхте слева продолжаются работа с парусом и церемония салюта.'],
['Масло на холсте; 48,3 × 48,1 см. Утренняя позолота на парусах сочетается с многочисленными голубыми оттенками неба и почти зеркальной водой.','Поникший флаг, едва движущийся парус и праздная команда справа показывают отсутствие ветра. Поза человека на берегу направляет взгляд мимо неподвижных судов к горизонту.'],
'Состояние погоды передаётся через поведение людей, ткани парусов и отражения. Небольшие действия сохраняют жизненность сцены, не разрушая общего спокойствия.',
['Поникший флаг: найди признак безветрия.','Золотистый парус: рассмотри складки справа.','Отражение шверта: сопоставь форму над и под водой.','Человек на берегу: проследи направление его взгляда.','Салют слева: найди дым и работающих моряков.'],
'Около 1660–1670 — приблизительный интервал. Побережье возле Гааги и повод салюта предположительны. Мысли сидящего человека неизвестны: музей предлагает возможные прочтения, а не установленную историю персонажа.',
'ng:NG2587','Голландская яхта и другие суда в штиль у берега','A Dutch Yacht and Other Vessels Becalmed near the Shore','около 1660–1670','Масло на холсте; 48,3 × 48,1 см','Национальная галерея, Лондон',N+'paintings/hendrick-dubbels-a-dutch-yacht-and-other-vessels-becalmed-near-the-shore',
'Сравни неподвижность яхты справа с работой моряков и салютом слева. Затем найди отражение шверта и складок паруса: как вода повторяет формы, не становясь отдельным сюжетом?');
add('abraham_storck','Абрахам Сторк','Abraham Storck','1644–1708',['Abraham Sturckenburg','Сторк'],'Нидерланды · воображаемый речной вид',
['Сторк создавал идеализированные речные и морские сцены. Национальная галерея подчёркивает: подробное знание судов сочеталось у него со свободным устройством местности.','В «Речном виде» утренние занятия рыбаков, наблюдателей и моряков объединены спокойным светом. Картина выглядит правдоподобно, хотя берега не соответствуют определённому реальному месту.'],
['Масло на холсте; 58,4 × 73,7 см. Восходящее солнце скрыто парусами военного корабля; свет выделяет складки ткани и почти не нарушенные отражения.','Различимы прибрежная яхта, тяжёлая баржа и официальная яхта с гербом Голландии. Мягкое свечение неба музей сравнивает скорее со средиземноморской, чем с североевропейской атмосферой.'],
'Точность отдельного предмета не гарантирует топографической точности целого. Узнаваемые суда становятся частью романтически устроенного пространства и утренней атмосферы.',
['Солнце за парусами: найди источник свечения.','Разные суда: сравни яхту и тяжёлую баржу.','Герб Голландии: отметь официальный характер яхты.','Спокойная вода: сопоставь суда с отражениями.','Дальний храм: рассмотри архитектурный ориентир.'],
'Подписанная NG146 датирована примерно 1690–1700 годами. Храм может напоминать собор Святого Лаврентия в Роттердаме, но остальная местность воображаема. Не называй картину документальным видом Роттердама.',
'ng:NG146','Речной вид','A River View','около 1690–1700','Масло на холсте; 58,4 × 73,7 см','Национальная галерея, Лондон',N+'paintings/abraham-storck-a-river-view',
'Сравни детальность судов с обобщённой мягкостью неба и берегов. Найди храм вдалеке: сходство одной постройки с реальным памятником не делает весь пейзаж топографически точным.');
add('bonaventura_peeters_the_elder','Бонавентура Петерс Старший','Bonaventura Peeters the Elder','XVII век; умер в 1652',['Бонавентура Питерс Старший','Bonaventura Peeters I'],'Фландрия · морской пейзаж и непогода',
['Петерс работал в Антверпене и в 1634 году вступил в гильдию Святого Луки. Музей связывает его небольшие морские картины со спросом состоятельных покупателей на живопись для домашних интерьеров.','В сцене с моряками под скалой природная угроза не заканчивается катастрофой: люди защищены укрытием, а суда остаются на мелководье. Это иной исход непогоды, чем кораблекрушение.'],
['Картина 1640-х годов, размер изображения 33,2 × 45,7 см; подписана B. P. Косые полосы дождя пересекают чёрные облака, а гладкая вода написана серебристо-серыми тонами.','Тесная группа людей под скалой противопоставлена открытому морю. Справа появляется радуга, отражённая в воде; скалистый навес создаёт убежище внутри угрожающей среды.'],
'Драматическая природа соединена с наблюдением за жестами и отношениями людей. Радуга позволяет читать сцену не только как угрозу, но и как возможность благополучного исхода.',
['Косой дождь: проследи направление полос.','Скалистый навес: найди границу защищённого места.','Группа людей: сравни жесты и занятия.','Свёрнутые паруса: посмотри на стоящие лодки.','Радуга справа: найди её отражение в воде.'],
'Материал основы в использованной записи явно не указан, поэтому не добавляем его по догадке. Рыбаки — более убедительное музейное прочтение, чем прежняя версия о контрабандистах. Значение радуги неоднозначно. Не смешивай Старшего с племянником-тёзкой; ранняя жизнь художника в море лишь предполагается.',
'rmg:BHC0759','Морской пейзаж с моряками, укрывающимися от ливня','Seascape with Sailors Sheltering from a Rainstorm','1640-е','Живопись; основа и связующее не уточнены в использованной записи; 33,2 × 45,7 см','Национальный морской музей, Гринвич',R+'rmgc-object-12251',
'Найди людей под скалой, лодки со свёрнутыми парусами и радугу справа. Сравни угрозу чёрных облаков с сохранностью судов и защищённостью людей. Не своди радугу к единственному доказанному символическому значению.');
add('reinier_nooms','Рейнир Номс','Reinier Nooms','XVII век',['Рейнир Зееман','Рейнир Зеэман','Reinier Zeeman'],'Нидерланды · морская батальная живопись',
['Номс известен также как Зееман. Музей связывает его живопись с голландской реалистической традицией и отмечает живую палитру; биографические сведения требуют осторожности.','Выбранная картина относится к Первой англо-голландской войне 1652–1654 годов. Она показывает действие и спасение людей, но конкретное сражение музей не идентифицирует.'],
['Масло на холсте; 101,6 × 152,4 см. Центральный голландский корабль ведёт огонь с обоих бортов, связывая противоположные части композиции.','Справа видны корма и красный флаг тонущего английского корабля. Небольшие лодки приближаются к людям среди обломков; слева показан ещё один английский корабль с резной кормой.'],
'Батальная картина соединяет крупный масштаб столкновения с малым масштабом человеческого спасения. Положение судов, огонь и лодки создают несколько связанных центров действия.',
['Центральный корабль: найди стрельбу с двух бортов.','Красные флаги: сопоставь английские суда.','Резная корма слева: рассмотри подробности корабля.','Тонущее судно справа: найди оставшуюся над водой корму.','Спасательные лодки: проследи путь к людям среди обломков.'],
'Около 1654 года — дата создания, 1652–1654 — период войны. Конкретный бой неизвестен. Сохраняем варианты Номс и Зееман: музей отдельно обсуждает проблему документального подтверждения имени Nooms. Не выводим морскую биографию исключительно из прозвища.',
'rmg:BHC0273','Сражение Первой англо-голландской войны 1652–1654 годов','A Battle of the First Dutch War, 1652-54','около 1654','Масло на холсте; 101,6 × 152,4 см','Национальный морской музей, Гринвич',R+'rmgc-object-11765',
'Проследи движение от центрального корабля к двум английским судам, затем переключись на лодки и людей среди обломков. Сравни историю военного столкновения с историей спасения.');
B.reinier_nooms.sources.push(['Royal Museums Greenwich: оговорка об имени','https://www.rmg.co.uk/collections/objects/rmgc-object-144260']);
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

;
/* artists-batch-75.js */
(()=>{'use strict';
const N='https://www.nationalgallery.org.uk/',B={};
function add(id,name,latin,life,aliases,tag,bio,technique,innovation,features,caution,key,title,originalTitle,date,medium,museum,source,look,extra=[]){B[id]={name,latin,life,tag,aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources:[[museum+': '+title,source],...extra],works:[],pendingWorks:[{key,title,originalTitle,date,medium,museum,source,look,reason:'Музейный оригинал установлен; свободный файл репродукции и права на него не проверены. Изображение не подключено.'}],editorialStatus:'text_only_image_file_and_rights_pending'};}
add('paulus_potter','Паулюс Поттер','Paulus Potter','1625–1654',['Паулус Поттер','Пауль Поттер'],'Нидерланды · животные в пейзаже',
['Поттер стал одним из успешных мастеров голландской живописи животных. Спрос на сельские сцены сочетался с хозяйственной значимостью скотоводства: сыр и масло были важными экспортными товарами Голландской республики.','В 1647 году, в возрасте 22 лет, он написал и небольшую лондонскую картину с быком перед грозой, и знаменитого большого «Быка», ныне в Маурицхёйсе. Эти разные по масштабу работы позволяют увидеть, как животное становилось главным героем, а не дополнением к человеческому действию.'],
['NG2583: масло на дереве, предположительно дубе; 46,3 × 37,8 см. Бык выделен силуэтом на самом светлом участке грозового неба; взгляд направлен к зрителю. Ветер гнёт ивы, а в средней дали проходит полоса дождя.','Две коровы и две овцы продолжают кормиться или отдыхать. Небольшой участок полевых цветов вокруг поваленного ствола образует спокойный передний план и отодвигает животных глубже, усиливая пространственное устройство картины.'],
'Животные получают самостоятельную выразительность и почти героическое присутствие. Разница между настороженным быком и спокойными спутниками создаёт драматизм без пастуха, человеческого происшествия или архитектурного фона.',
['Силуэт рогов: найди светлый просвет за быком.','Прямой взгляд: отметь обращение животного к зрителю.','Ветер и дождь: сравни ивы и средний план.','Спокойное стадо: сопоставь позы коров и овец с быком.','Цветы у ствола: найди тихий передний план.'],
'Картина подписана и датирована 1647 годом. Дуб указан предположительно. Национальная стойкость и благополучие — возможное символическое прочтение, предложенное музеем, а не доказанный замысел. Не путай NG2583 с большим «Быком» из Маурицхёйса.',
'ng:NG2583','Коровы и овцы в грозовом пейзаже','Cattle and Sheep in a Stormy Landscape','1647','Масло на дереве, предположительно дубе; 46,3 × 37,8 см','Национальная галерея, Лондон',N+'paintings/paulus-potter-cattle-and-sheep-in-a-stormy-landscape',
'Сравни настороженный взгляд быка со спокойными позами остальных животных. Затем найди дождь вдалеке и цветы у поваленного ствола: как противоположные состояния природы распределены по пространственным планам?');
add('nicolaes_berchem','Николас Берхем','Nicolaes Berchem','1620–1683',['Николас Бергхем','Николас Беркхем','Nicolaes Pietersz. Berchem'],'Нидерланды · итальянизирующий пейзаж',
['Берхем родился в Харлеме и был сыном мастера натюрморта Питера Класа. Основную часть карьеры он работал в Харлеме; его поездку в Италию в 1640-х годах Национальная галерея считает вероятной, но не установленной безусловно.','Его пасторали соединяют южный свет, руины и горы с крепкими голландскими животными. Итальянизирующие пейзажи высоко ценились коллекционерами XVIII и начала XIX века; позднее изменение вкусов временно оттеснило их как якобы недостаточно «голландские».'],
['NG820: масло на дереве, предположительно дубе; 47,1 × 38,7 см. Резкий перспективный ракурс делает разрушенную арку огромной по сравнению с людьми и стадом. Мягкий вечерний свет раскрывает старые камни и растительность среди руин.','Животные расположены веером, позволяя увидеть тела с разных сторон. Красная юбка женщины на осле — единственное ярко-красное пятно: оно оживляет приглушённые тона и выделяет фигуру среди тёплого света.'],
'Пастораль возникает из соединения разнородных наблюдений и мотивов: античная руина, южная местность, характерные животные и жанровое действие образуют убедительный художественный мир, а не обязательную запись одного места.',
['Ракурс арки: проследи, почему она кажется высокой.','Вечерний свет: найди тени на выветренном камне.','Стадо веером: сравни повороты тел животных.','Красная юбка: найди единственный ярко-красный акцент.','Женщина на осле: сопоставь её положение с мужчинами внизу.'],
'Дата предположительная: 1655–1660; картина подписана. Дуб и итальянская поездка также требуют оговорок. Жест женщины допускает разные прочтения. Руина и горы не дают основания назвать изображение точным видом определённого итальянского места.',
'ng:NG820','Крестьяне у разрушенного акведука','Peasants with Four Oxen and a Goat at a Ford by a Ruined Aqueduct','предположительно 1655–1660','Масло на дереве, предположительно дубе; 47,1 × 38,7 см','Национальная галерея, Лондон',N+'paintings/nicolaes-berchem-peasants-by-a-ruined-aqueduct',
'Сначала сравни масштаб арки, людей и животных. Затем найди красную юбку и посмотри, как маленькое цветовое пятно меняет равновесие всей сцены. Отделяй видимый жест женщины от возможного объяснения разговора.',[['Национальная галерея: биография Берхема',N+'artists/nicolaes-berchem']]);
add('adriaen_van_de_velde','Адриан ван де Велде','Adriaen van de Velde','1636–1672',['Адриан ван де Вельде','Adrian van de Velde'],'Нидерланды · пастораль и животные',
['Адриан начинал в семейной мастерской вместе с отцом Виллемом Старшим и старшим братом Виллемом Младшим. В отличие от прославленных маринистов, он выбрал пейзаж и при этом сотрудничал с братом, дописывая фигуры в некоторых его картинах.','«Ферма с сухим деревом» написана в 1658 году, когда художнику было 22 года. Национальная галерея отмечает зрелость композиции и влияние Паулюса Поттера на изображение весомых, выразительных животных.'],
['Масло на холсте; 54,2 × 62,5 см. Три отдельные группы людей и животных объединены широким участком тёплого солнечного света. Синяя юбка доярки оживляет коричневые, кремовые и серые тона и связывает землю с небом.','Сухой дуб резко выделяется на фоне неба, но плющ смягчает нижние ветви, а мягкие облака и побеги соседних ив ослабляют суровость силуэта. Рога серого быка подчёркивают его силу и телесный вес, позволяя сравнить приём с Поттером.'],
'Тихая сцена не лишена композиционной сложности: самостоятельные эпизоды связываются светом и цветом. Спокойствие возникает из согласования фигур, животных и среды, а не из полного отсутствия движения.',
['Три группы: раздели сцену на небольшие эпизоды.','Тёплый свет: найди общее освещённое пространство.','Синяя юбка: сравни акцент с цветом неба.','Сухой дуб и плющ: сопоставь жёсткий и мягкий контуры.','Серый бык: рассмотри силуэт рогов и массу тела.'],
'NG867 подписана и датирована 1658 годом. Это Адриан, не Виллем Старший и не Виллем Младший. Версия, что ветви у дерева заготовлены на растопку, обозначена музеем как вероятная; сухое дерево само по себе не доказывает единственный аллегорический смысл.',
'ng:NG867','Ферма с сухим деревом','A Farm with a Dead Tree','1658','Масло на холсте; 54,2 × 62,5 см','Национальная галерея, Лондон',N+'paintings/adriaen-van-de-velde-a-farm-with-a-dead-tree',
'Найди доярку, мужчину с корзиной и отдыхающих животных. Проследи, как свет соединяет три группы. Затем сравни рога серого быка с быком Поттера: что меняется при переходе от грозового напряжения к спокойствию фермы?');
add('karel_dujardin','Карел Дюжарден','Karel Dujardin','1626–1678',['Карел Дюжардин','Карел дю Жарден','Karel du Jardin'],'Нидерланды · итальянизирующая пастораль',
['Дюжарден был одним из ведущих мастеров итальянизирующего пейзажа, писал животных, портреты и религиозные сцены. Национальная галерея отмечает влияние Поттера; обучение у Берхема известно по биографу Хаубракену и не должно терять эту атрибуцию сведений.','Для пасторалей он использовал мотивы зарисовок окрестностей Рима, сочетая их в воображаемые сцены. В выбранной картине наблюдение за животными соединяется с короткой человеческой историей: мальчик играет с собакой, стараясь не разбудить пастушку.'],
['NG826: масло на холсте; 34,6 × 39,7 см. Солнечный свет сквозь листву выделяет морду овцы и подробно написанную кудрявую шерсть. Зелёные оттенки меняются от переднего плана до лёгкой кроны и выжженной травы вдали.','Пастушка уронила принадлежности для прядения; мальчик приложил палец к губам, заставляя собаку выпрашивать угощение. Серебристое ясное небо отличается от мягкого золотистого свечения многих пасторалей Берхема и Бота.'],
'Тщательная фактура и необычные, наблюдённые позы придают идеализированному пейзажу земную достоверность. Небольшие жесты превращают состояние отдыха в рассказ, который зритель восстанавливает по деталям.',
['Шерсть овцы: рассмотри дробный свет на завитках.','Спящая пастушка: найди опущенную руку.','Прялочные принадлежности: заметь прерванное занятие.','Палец у губ: свяжи жест мальчика с игрой собаки.','Серебристое небо: сравни его с золотым светом Берхема.'],
'Картина подписана и датирована 1656 годом. Это воображаемая композиция, не буквальный вид Римской Кампаньи. Возможное изменение пигмента могло сделать некоторые растения голубоватее: нынешний цвет не обязательно исходный. Усталость от жары — музейное объяснение сна, а не документально установленный эпизод.',
'ng:NG826','Домашние животные с мальчиком и спящей пастушкой','Farm Animals in the Shade of a Tree, with a Boy and a Sleeping Herdswoman','1656','Масло на холсте; 34,6 × 39,7 см','Национальная галерея, Лондон',N+'paintings/karel-dujardin-farm-animals-with-a-boy-and-herdswoman',
'Начни с освещённой шерсти овцы, затем найди прерванное прядение и палец мальчика у губ. Как фактура животных и человеческие жесты помогают почувствовать короткую паузу в повседневной жизни?',[['Национальная галерея: биография Дюжардена',N+'artists/karel-dujardin']]);
add('jan_asselijn','Ян Асселейн','Jan Asselijn','1610–1652',['Ян Асселейн','Ян Асселин'],'Нидерланды · животное и драматическое действие',
['В этой карточке Асселейн представлен «Лебедем под угрозой», а не всем разнообразием своего творчества. Рейксмюсеум хранит также его итальянские виды, сцены с руинами и другие пейзажные произведения.','Картина стала первым приобретением Национальной художественной галереи, предшественницы Рейксмюсеума, в 1800 году. К тому времени её уже воспринимали через политическую аллегорию, возникшую позднее первоначальной сцены с животными.'],
['Масло на холсте, около 1650 года; музейный номер SK-A-4. Лебедь защищает гнездо с яйцами от собаки: раскрытые крылья и вытянутая шея делают движение главным содержанием композиции.','Светлая птица противопоставлена угрожающему противнику и окружающей среде. Жест защиты связывает животное с конкретным пространством гнезда, поэтому напряжение имеет ясную видимую причину, не требующую политической расшифровки.'],
'Изображение животного приобретает масштаб драматического действия. История последующего восприятия показывает, как выразительный природный мотив может получить новый общественный смысл, не совпадающий с доказанным исходным замыслом.',
['Раскрытые крылья: проследи размах защитного движения.','Вытянутая шея: найди направление противостояния.','Собака: рассмотри источник угрозы.','Гнездо и яйца: определи, что защищает птица.','Политические надписи: отдели позднее прочтение от сцены животных.'],
'Около 1650 года — приблизительная дата. Рейксмюсеум прямо относит политическое толкование к последующим столетиям: лебедя связывали с Яном де Виттом, убитым в 1672 году. Не выдаём это за установленный замысел Асселейна. Отметка Public domain в записи объекта не заменяет проверку конкретного файла репродукции.',
'rijks:SK-A-4','Лебедь под угрозой','The Threatened Swan','около 1650','Масло на холсте','Рейксмюсеум, Амстердам','https://www.rijksmuseum.nl/en/collection/object/The-Threatened-Swan--22040f90565e730131983a44a85b989f',
'Сначала прочитай сцену без надписей: лебедь, собака, гнездо. Затем отдельно рассмотри политическое объяснение, которое позднее закрепилось за картиной. Чем различаются изображённое действие и история его интерпретации?',[['Рейксмюсеум: рассказ о произведении','https://www.rijksmuseum.nl/en/stories/one-hundred-masterpieces/story/threatened-swan']]);
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

;
/* artists-batch-76.js */
(()=>{'use strict';
const N='https://www.nationalgallery.org.uk/',B={};
function add(id,name,latin,life,aliases,tag,bio,technique,innovation,features,caution,num,title,originalTitle,date,medium,slug,look,extra=[]){const source=N+'paintings/'+slug;B[id]={name,latin,life,tag,aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources:[['Национальная галерея: '+num,source],...extra],works:[],pendingWorks:[{key:'ng:'+num,title,originalTitle,date,medium,museum:'Национальная галерея, Лондон',source,look,reason:'Музейный оригинал установлен; свободный файл репродукции и права на него не проверены. Изображение не подключено.'}],editorialStatus:'text_only_image_file_and_rights_pending'};}
add('hendrick_avercamp','Хендрик Аверкамп','Hendrick Avercamp','1585–1634',['Хендрик Аверкамп','Хендрик Аверкам','Hendrik Avercamp'],'Нидерланды · зимний пейзаж и жизнь на льду',
['Аверкамп специализировался на зимних сценах и большую часть жизни провёл в Кампене. Замёрзшие водоёмы у него становятся общей площадкой для работы, развлечений и столкновений разных характеров.','«Зимняя сцена с конькобежцами у замка» относится к раннему периоду, около 1608–1609 годов. Национальная галерея подчёркивает: изображённый город воображаемый, а не буквальный вид Кампена.'],
['Масло на дереве, предположительно дубе; 40,7 × 40,7 см. Высокая точка зрения позволяет охватить большой участок льда, город и даль. Многочисленные маленькие фигуры превращают панораму в набор отдельных историй.','Художник готовил фигуры в тщательных рисунках, иногда подкрашенных акварелью, а затем переносил их в картину экономными мазками. Жесты, костюмы и положение тел различают персонажей даже тогда, когда они повернуты к зрителю спиной.'],
'Зимний пейзаж становится пространством общественной жизни. Панорамный обзор соединён с точными наблюдениями за отдельными людьми: зритель свободно переходит от общей картины к маленьким происшествиям.',
['Высокий обзор: проследи протяжённость льда и города.','Розоватый замок: найди заметную архитектурную массу.','Нарядная пара: сравни одежду с практичностью движения на льду.','Погоня со снежками: найди эпизод возле дома слева.','Парные фигуры в центре: проследи ритм движения.'],
'Около 1608–1609 — приблизительная дата; картина подписана. Дуб указан предположительно. Не выдавай вымышленный город за Кампен и не принимай каждый эпизод за документ реального происшествия. Объяснение странной позы человека у проруби неизвестно: музей предлагает вопросы, а не установленный ответ.',
'NG1346','Зимняя сцена с конькобежцами у замка','A Winter Scene with Skaters near a Castle','около 1608–1609','Масло на дереве, предположительно дубе; 40,7 × 40,7 см','hendrick-avercamp-a-winter-scene-with-skaters-near-a-castle',
'Начни с общего вида, затем выбери три маленьких эпизода: показ нарядов, снежки и движение парами. Сравни, сколько характера художник передаёт поворотом тела и несколькими мазками.',[['Национальная галерея: биография',N+'artists/hendrick-avercamp']]);
add('esaias_van_de_velde','Эсайас ван де Велде','Esaias van de Velde','1587–1630',['Эсаяс ван де Велде','Эсайас ван де Вельде'],'Нидерланды · ранний атмосферный пейзаж',
['Эсайас работал в Харлеме и Гааге и был прежде всего пейзажистом. Национальная галерея относит его к ранним мастерам, изменившим подход к зимнему виду: вместо обилия занимательных эпизодов важнее становится ощущение присутствия в определённую погоду.','Подписанный и датированный «Зимний пейзаж» 1623 года позволяет сопоставить этот подход с Аверкампом. Люди остаются существенными, но не превращают всю картину в многолюдное представление.'],
['Масло на дереве, предположительно дубе; 25,9 × 30,4 см. Мягкие приглушённые краски передают холод, остатки снега и серую замёрзшую реку. Слабая полоса голубого в небе и тень дерева на стене дома сообщают о кратком солнечном просвете.','Точка зрения всё ещё немного приподнята, но уже находится примерно на уровне церкви противоположного берега. Немногие фигуры связывают зрителя с местностью, не отвлекая от целостного вида.'],
'Переход от панорамного зрелища к переживанию среды происходит через понижение точки зрения, сокращение числа персонажей и тонкую работу с погодой. Это ранний пример направления, а не утверждение о единоличном изобретении художника.',
['Остатки снега: найди белые участки у деревьев и дома.','Серая река: сравни её цвет с небом.','Тень на стене: найди след краткого солнца.','Игроки в колф слева: отметь небольшой эпизод на льду.','Церковь на дальнем берегу: сопоставь её уровень с точкой зрения.'],
'1623 — точная музейная дата, а наступление весны — прочтение признаков погоды, не известный календарный день. Желтовато-зелёные оттенки дальних деревьев могут напоминать ранние почки, но музей сохраняет оговорку. Не смешивай Эсайаса с Виллемами или Адрианом ван де Велде.',
'NG6269','Зимний пейзаж','A Winter Landscape','1623','Масло на дереве, предположительно дубе; 25,9 × 30,4 см','esaias-van-de-velde-a-winter-landscape',
'Найди тень дерева на стене: сам солнечный диск не показан, но освещение можно восстановить по следу. Затем сравни редкие фигуры и точку зрения с многолюдной панорамой Аверкампа.',[['Национальная галерея: биография',N+'artists/esaias-van-de-velde']]);
add('aert_van_der_neer','Арт ван дер Нер','Aert van der Neer','1603/1604–1677',['Аэрт ван дер Нер','Аерт ван дер Нер','Арт ван дер Неер'],'Нидерланды · зимний пейзаж и вечерний свет',
['Ван дер Нер специализировался на особых состояниях освещения: рассвете, сумерках, лунной ночи, а также на зимних пейзажах. Выбранная картина соединяет замёрзшую реку с драматическим вечерним небом.','В середине XVII века суровые зимы надолго сковывали водоёмы Нидерландов, и такие виды были востребованы художниками и заказчиками. Но композиции ван дер Нера не следует принимать за точную регистрацию конкретного дня и места.'],
['NG969: масло на дереве, предположительно дубе; 26,4 × 40,5 см. Глубокий зеленоватый лёд отражает небо, а тёмные облака окрашены рыжеватыми отсветами невидимого заката.','Широкие тёмные мазки в верхней части неба намекают на усиливающийся ветер. Разрозненные небольшие фигуры, в том числе одиночные игроки в колф, тщательно размещены ради общего впечатления, а не случайно попали в поле зрения.'],
'Состояние неба и его отражение определяют эмоциональный строй зимнего вида. На фоне широкого пространства одиночные фигуры действуют иначе, чем плотная толпа у Аверкампа: атмосфера становится самостоятельным содержанием картины.',
['Зеленоватый лёд: найди цветовое отражение неба.','Рыжие облака: проследи отсвет невидимого заката.','Широкие мазки вверху: сравни их с тихими фигурами.','Одиночные игроки: найди фигуры по краям композиции.','Городской силуэт: проследи границу зданий и облаков.'],
'Около 1665 — приблизительная дата; картина подписана. Город не идентифицирован, дуб указан предположительно. Разобщённость фигур — наблюдение о композиции, не диагноз персонажей. Расчистка в 1969 году выявила позднюю запись нижней части присевшей фигуры справа: нынешний вид связан также с историей реставрации.',
'NG969','Замёрзшая река у города вечером','A Frozen River by a Town at Evening','около 1665','Масло на дереве, предположительно дубе; 26,4 × 40,5 см','aert-van-der-neer-a-frozen-river-by-a-town-at-evening',
'Сравни цвет льда с облаками и отыщи, откуда мог бы идти закатный свет. Затем проследи расстояния между фигурками: как их разобщённость меняет настроение по сравнению со сценой Аверкампа?',[['Национальная галерея: биография',N+'artists/aert-van-der-neer']]);
add('isack_van_ostade','Исак ван Остаде','Isack van Ostade','1621–1649',['Исаак ван Остаде','Isaack van Ostade','Isaac van Ostade'],'Нидерланды · зимний пейзаж и сельская жизнь',
['Исак был младшим братом и учеником Адриана ван Остаде. Он начинал с крестьянских сцен и позднее создавал атмосферные зимние пейзажи, но умер молодым, в 1649 году.','В «Зимней сцене» 1640-х годов зима показана не праздником катания, а условиями труда и повседневного передвижения. Музей противопоставляет этот мир нарядным и оживлённым сценам Аверкампа.'],
['NG848: масло на дереве, предположительно дубе; 48,8 × 40 см. Ветхий дом на пригорке и хрупкий мост выделяются на фоне серого неба; под мостом открывается далёкий вид на замёрзшую реку.','Серебристый свет и мелкие блёстки инея придают сияние бедной обстановке. Белая лошадь, тянущая тяжёлые сани вверх по берегу, сохраняет энергию среди опущенных голов и усталых движений других животных.'],
'Трудность сельской жизни не исключает световой красоты. Вместо множества забав композиция предлагает несколько напряжённых действий, а морозный блеск и движение вверх усложняют первоначальное впечатление уныния.',
['Ветхий дом: рассмотри крышу и следы инея.','Мост: найди рамку для дальнего вида.','Старик с коньками: сопоставь усилие и наблюдающего мальчика.','Белая лошадь: проследи движение саней вверх.','Блёстки инея: сравни сияние льда с серыми облаками.'],
'1640-е — десятилетие, не установленный год; картина подписана. Дуб предположителен. Стойкость людей и надежда на весну — музейная интерпретация, а не документированная программа. Не подменяй NG848 «Трактиром у замёрзшей реки» NG963: тот сейчас относится к последователю. Исак и Адриан — разные художники.',
'NG848','Зимняя сцена','A Winter Scene','1640-е','Масло на дереве, предположительно дубе; 48,8 × 40 см','isack-van-ostade-a-winter-scene',
'Сначала найди действия, требующие усилия: надевание коньков, движение саней, подъём по берегу. Затем отыщи светящиеся участки инея и белую лошадь. Как художник избегает однообразно мрачного впечатления?',[
['Национальная галерея: работа раннего периода',N+'paintings/isack-van-ostade-the-interior-of-a-barn-with-two-peasants'],['Национальная галерея: NG963 — последователь',N+'paintings/follower-of-isack-van-ostade-an-inn-by-a-frozen-river']]);
add('arent_arentsz','Арент Арентсз.','Arent Arentsz.','1585/1586–1631',['Арент Арентс','Арент Арентсз','Arent Arentsz','Cabel'],'Нидерланды · рыбаки и речной пейзаж',
['Арентсз. родился и работал в Амстердаме, писал пейзажи с крестьянами и рыбаками переднего плана. Национальная галерея относит его к последователям Аверкампа; прозвище Cabel связывает с названием семейного дома.','«Рыбаки у замка Мёйден» показывает, как жанровые фигуры могут стать главными героями даже в картине с узнаваемым архитектурным памятником. Это не зимняя сцена: она дополняет батч другим способом соединить повседневность и пространство у воды.'],
['Масло на дереве, предположительно дубе; 23,3 × 38,8 см. Три рыбака расположены фризом на переднем плане: тяжёлые сапоги, одежда, позы и лица проработаны значительно отчётливее дальнего пейзажа.','Замок и лодки растворяются в дымке, почти как плоская театральная декорация. При этом ручей, камешки и опоры небольшого мостика переданы тщательно: градации подробности подчинены роли каждого элемента.'],
'Различие между отчётливым передним планом и туманной далью выстраивает иерархию внимания. Узнаваемая архитектура остаётся второстепенной по отношению к человеческому труду, а точное наблюдение сочетается с перестройкой местности.',
['Три рыбака: проследи фризовую расстановку.','Переливание улова: найди связь жестов юноши и старшего мужчины.','Ручей и мостик: рассмотри мелкие предметные детали.','Лодки вдалеке: сопоставь их движение с неподвижными фигурами.','Призрачный замок: сравни резкость дальнего и ближнего планов.'],
'Около 1630 — приблизительная дата; картина подписана. Дуб предположителен. Замок узнаваем и показан с запада, но положение церкви художник изменил ради композиции. Содержимое сумки рыбака и назначение маленькой корзины нельзя считать бесспорно установленными. Не смешивай Арентсз. с Питером Артсеном.',
'NG3533','Рыбаки у замка Мёйден','Fishermen near Muiden Castle','около 1630','Масло на дереве, предположительно дубе; 23,3 × 38,8 см','arent-arentsz-fishermen-near-muiden-castle',
'Сравни отчётливые фигуры рыбаков с дымкой вокруг замка. Затем найди переливание рыбы, ручей и две маленькие фигуры в лодке с сетью: что художник делает главным, а что оставляет на втором плане?',[['Национальная галерея: биография',N+'artists/arent-arentsz']]);
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

