/* artists-batch-77.js */
(()=>{'use strict';
const N='https://www.nationalgallery.org.uk/',B={};
function add(id,name,latin,life,aliases,tag,bio,technique,innovation,features,caution,num,title,originalTitle,date,medium,slug,look){const source=N+'paintings/'+slug;B[id]={name,latin,life,tag,aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources:[['Национальная галерея: '+num,source]],works:[],pendingWorks:[{key:'ng:'+num,title,originalTitle,date,medium,museum:'Национальная галерея, Лондон',source,look,reason:'Музейный оригинал установлен; свободный файл репродукции и права на него не проверены. Изображение не подключено.'}],editorialStatus:'text_only_image_file_and_rights_pending'};}
add('cornelis_vroom','Корнелис Вром','Cornelis Vroom','1591/1592–1661',['Корнелис Хендрикс Вром','Cornelis Hendricksz. Vroom'],'Нидерланды · лесной пейзаж',
['Корнелис был сыном мариниста Хендрика Врома и начал с морских видов, но затем обратился к пейзажу. Работая главным образом в Харлеме, он пользовался признанием и выполнял заказы для влиятельных покровителей.','В картине 1626 года лес перестаёт быть рамой для красивого вида: сам тёмный массив деревьев становится главным предметом. Национальная галерея считает этот ранний пример важным для понимания его новаторского подхода.'],
['Масло на дереве, предположительно дубе; 31,2 × 44,2 см. Изгиб реки, низкая растительность и освещённая песчаная тропинка создают протяжённый передний план; поля за деревьями открывают даль.','Яркое небо освещает листву сзади. Множество маленьких мазков зелёного и коричневого передают прозрачные просветы, освещённые верхушки и почти чёрную глубину леса.'],
'Глубина сохраняется без привычного окна между обрамляющими деревьями: взгляд движется вдоль воды, сквозь листву и к дальним полям. Лес становится самостоятельной средой, а люди и животные занимают подчинённое место.',
['Изгиб реки: проследи путь вдоль леса.','Песчаная тропинка: найди солнечный акцент слева.','Поля за стволами: отыщи скрытую даль.','Просветы листвы: сравни оттенки и плотность тени.','Маленькая лодка: сопоставь масштаб людей и деревьев.'],
'NG3475 подписана и датирована 1626 годом; дуб предположителен. Виды деревьев музей определяет осторожно. Не смешивай Корнелиса с отцом Хендриком: даже крупная выплата от Карла I могла относиться к Корнелису либо его брату Фредерику.',
'NG3475','Пейзаж с рекой у леса','A Landscape with a River by a Wood','1626','Масло на дереве, предположительно дубе; 31,2 × 44,2 см','cornelis-vroom-a-landscape-with-a-river-by-a-wood',
'Сначала проследи изгиб берега, затем найди поля за деревьями. Как художник создаёт глубину, не открывая широкого окна в середине леса? Сравни освещённые листья с почти чёрными участками под кронами.');
add('allart_van_everdingen','Алларт ван Эвердинген','Allart van Everdingen','1621–1675',['Алларт ван Эвердинген','Аллаерт ван Эвердинген','Allaert van Everdingen'],'Нидерланды · скандинавские мотивы и горный поток',
['В 1640-х годах Эвердинген путешествовал по Норвегии и привёз рисунки водопадов, гор и высоких хвойных деревьев, непривычных для равнинной Голландии. Законченные пейзажи он создавал в мастерской.','Национальная галерея отмечает влияние его норвежских мотивов на Якоба ван Рёйсдала. В «Лесопилке у бурного потока» северный рельеф соединён с мельницей, более характерной для голландской среды.'],
['Масло на дереве, предположительно дубе; 44,8 × 60,3 см. Узкий солнечный просвет выделяет соломенную крышу и белую пену стремительного потока. Колесо мельницы остаётся малозаметным: художник сосредоточен на настроении природы.','Серое небо, высокие деревья и резкие скалы создают суровость; тёплые тона земли и осенняя листва слева её смягчают. Изогнутый ствол молодого дуба словно охватывает мельницу.'],
'Реальные впечатления путешествия становятся материалом составного пейзажа. Убедительность воды, света и рельефа не означает, что изображено одно точно установленное норвежское место.',
['Белая пена: найди самый яркий участок воды.','Соломенная крыша: сопоставь её свет с потоком.','Мельничное колесо: отыщи неброский признак постройки.','Высокие хвойные деревья: проследи вертикали на фоне неба.','Осенний дуб слева: сравни тепло листвы с холодным небом.'],
'Около 1670 года — приблизительная дата; картина подписана. Дуб предположителен. Заброшенность мельницы — музейная гипотеза, не установленный факт. Тёмные слои лака затрудняют чтение фигуры женщины и предмета у неё на коленях.',
'NG1701','Лесопилка у бурного потока','A Saw-mill by a Torrent','около 1670','Масло на дереве, предположительно дубе; 44,8 × 60,3 см','allart-van-everdingen-a-saw-mill-by-a-torrent',
'Сопоставь освещённую крышу, белую пену и едва заметное колесо. Почему картина говорит прежде всего о состоянии природы, хотя в названии обозначена хозяйственная постройка?');
add('jan_wijnants','Ян Вейнантс','Jan Wijnants','работал с 1643; умер в 1684',['Ян Вайнантс','Ян Вейнант','Jan Wynants'],'Нидерланды · дюны и сельские дороги',
['Вейнантс родился в Харлеме; к 1660 году работал в Амстердаме, где и умер. Его характерная местность — песчаные холмы и поля между Харлемом и морем. 1643 в музейной биографии обозначает начало известной деятельности, не год рождения.','NG971, вероятно, создана совместно с Яном Лингельбахом, который дописал фигуры и животных после завершения пейзажа. Подобное разделение работы было обычной практикой, а не признаком незавершённости замысла.'],
['Масло на холсте; 40,9 × 53,7 см. Волнистый рельеф, роща, церковь, солнечные участки и объёмные облака располагаются так, чтобы усилить впечатление расстояния.','Красные и коричневые пятна одежды выделяют путников и направляют взгляд по дороге. Два человека и собака на гребне дюны образуют выразительные силуэты на фоне неспокойного неба.'],
'Пространство строится совместной работой рельефа, освещения и фигур. Путники служат не только мерой масштаба, но и последовательными ориентирами для движения взгляда в глубину.',
['Высокая дюна: сравни ближний склон и дальнюю местность.','Дорога: проследи направление движения в глубину.','Роща и церковь: найди дальние ориентиры.','Красная одежда: отметь цветовые акценты среди земли и зелени.','Люди и собака на гребне: рассмотри силуэты.'],
'Дата предположительная: около 1665; картина подписана. Участие Лингельбаха вероятно, а не документально бесспорно. Конкретное место не установлено: пейзаж передаёт характер окрестностей Харлема, но, по музею, переработан ради пространственного эффекта.',
'NG971','Пейзаж с высокой дюной и крестьянами на дороге','A Landscape with a High Dune and Peasants on a Road','предположительно около 1665','Масло на холсте; 40,9 × 53,7 см','jan-wijnants-a-landscape-with-a-high-dune-and-peasants-on-a-road',
'Проследи дорогу, отмечая цветные пятна одежды. Затем сравни фигуры внизу с силуэтами на вершине дюны: как их расположение помогает почувствовать высоту и расстояние?');
add('philips_koninck','Филипс Конинк','Philips Koninck','1619–1688',['Филипп Конинк','Philips de Koninck'],'Нидерланды · панорамный пейзаж',
['Конинк специализировался на обширных панорамах, обычно воображаемых. Национальная галерея выделяет величие и спокойствие этих пространств, где даже ближние человеческие действия выглядят маленькими.','В NG4251 животные и фигуры, вероятно, написаны Адрианом ван де Велде. Это позволяет сопоставить самостоятельную пастораль Адриана из батча 75 с его возможным участием в гораздо более широкой панораме.'],
['Масло на холсте; 101,5 × 146,5 см. Взгляд постепенно обнаруживает людей, животных, дома, церкви, павильоны и башни среди деревьев. Мост в тени ведёт через реку к мельнице.','Дальше солнечный свет выделяет озеро и город на его берегу. Переходы между освещёнными участками и тенью связывают множество мотивов в единую дистанцию, а малая величина фигур усиливает масштаб местности.'],
'Картина рассчитана на длительное путешествие взгляда без одного обязательного центра событий. Множество маленьких открытий сохраняет интерес внутри грандиозного, спокойно устроенного пространства.',
['Малые фигуры: найди работу, разговор и отдых.','Постройки среди деревьев: различи разные типы архитектуры.','Мост в тени: проследи путь через реку.','Мельница: найди связь водного и человеческого пространства.','Освещённое озеро: сопоставь дальний город с ближними мотивами.'],
'Около 1670 — приблизительная дата. Пространство обычно воображаемое; не присваивай дальнему городу неподтверждённое название. Участие Адриана ван де Велде предположительно. Филипс Конинк и Давид де Конинк из батча 69 — разные художники.',
'NG4251','Обширный пейзаж','An Extensive Landscape with Houses in a Wood and a Distant Town','около 1670','Масло на холсте; 101,5 × 146,5 см','philips-koninck-an-extensive-landscape',
'Найди мост и мельницу, затем солнечное озеро с городом. Попробуй пройти картину другим маршрутом: сохраняется ли ощущение единого пространства, если начать не с переднего плана?');
add('frederick_de_moucheron','Фредерик де Мушерон','Frederick de Moucheron','1633–1686',['Фредерик де Мухерон','Frederik de Moucheron'],'Нидерланды · итальянизирующий пейзаж и руины',
['Мушерон создавал идиллические сцены с людьми и животными среди античных руин. Насколько известно Национальной галерее, он не посещал Италию, а составлял виды по рисункам и зарисовкам художников, побывавших там.','NG1352 написана вскоре после его возвращения в Амстердам из Франции. Музей допускает, что французский опыт мог повлиять на северный облик деревьев и прохладное освещение этой воображаемой римской местности.'],
['Масло на холсте; 71 × 65,2 см. Три колонны поддерживают массивные блоки, напоминающие саркофаг. Опоры чуть отклонены от вертикали, создавая тревогу над спокойно сидящими людьми.','Женщина держит младенца, мужчина указывает на освещённую башню, а собака исследует камни. Прохладный свет отличается от мягкого золотистого сияния многих пейзажей Берхема и Бота.'],
'Руины работают не просто как узнаваемый итальянский мотив: их масштаб и неустойчивость противопоставлены безмятежной повседневности. Монументальное прошлое и жизнь в его тени становятся двумя разными временными планами.',
['Три колонны: проверь их почти незаметный наклон.','Каменные блоки: сравни тяжесть с маленькими людьми.','Женщина с младенцем: найди спокойный центр группы.','Указующий мужчина: проследи направление к светлой башне.','Собака среди камней: отметь движение под руинами.'],
'Около 1660 — приблизительная дата; картина подписана. Остатки римского храма — предположение, как и связь прохладного света с Францией. Отсутствие поездки в Италию сформулировано в пределах нынешних знаний музея. Не смешивай Фредерика с его сыном Исааком де Мушероном.',
'NG1352','Пейзаж с античными руинами','A Landscape with Classical Ruins','около 1660','Масло на холсте; 71 × 65,2 см','frederick-de-moucheron-a-landscape-with-classical-ruins',
'Сравни едва наклонённые колонны со спокойствием женщины и стада. Затем найди жест мужчины и собаку: замечают ли персонажи ту угрозу, которую зрителю предлагает устройство руины?');
B.jan_wijnants.sources.push(['Национальная галерея: биография',N+'artists/jan-wijnants']);
B.frederick_de_moucheron.sources.push(['Национальная галерея: биография',N+'artists/frederick-de-moucheron']);
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

