/* artists-batch-83.js */
(()=>{'use strict';
const N='https://www.nationalgallery.org.uk/',B={};
function add(id,name,latin,life,aliases,tag,bio,technique,innovation,features,caution,num,title,originalTitle,date,medium,slug,look){const source=N+'paintings/'+slug;B[id]={name,latin,life,tag,aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources:[['Национальная галерея: '+num,source]],works:[],pendingWorks:[{key:'ng:'+num,title,originalTitle,date,medium,museum:'Национальная галерея, Лондон',source,look,reason:'Музейный оригинал установлен; свободный файл репродукции и права на него не проверены. Изображение не подключено.'}],editorialStatus:'text_only_image_file_and_rights_pending'};}
add('annibale_carracci','Аннибале Карраччи','Annibale Carracci','1560–1609',['Аннибале Каррачи'],'Италия · Болонья и Рим · композиция и чувство',
['Аннибале неоднократно возвращался к теме оплакивания Христа, особенно в последнее десятилетие жизни. Лондонская картина соединяет строго организованную композицию с различными человеческими реакциями на утрату.','Музей связывает её построение с «Оплакиванием» Корреджо в Парме, которое художник мог изучить в 1580-х годах. Работа с предшественниками здесь важнее идеи изолированного изобретения нового стиля.'],
['Масло на холсте; 92,8 × 103,2 см. Композиция держится на сильных диагоналях; положения Христа и теряющей сознание Марии перекликаются, связывая их структурно и эмоционально.','Холодные голубые тона уступают тёплым оттенкам лиц, красной одежде и золотистым волосам. Направления взглядов переводят внимание от Марии к женщинам позади и затем к Магдалине, которая возвращает его к Христу.'],
'Формальная ясность не ослабляет переживание, а направляет его. Зритель последовательно сопоставляет разные реакции, сохраняя целостность группы.',
['Диагонали тел: сравни положения Христа и Марии.','Рука Марии: найди контакт с плечом сына.','Холодные и тёплые тона: проследи переход цвета.','Взгляды женщин: восстанови маршрут внимания.','Магдалина справа: сопоставь жест с остальными реакциями.'],
'Около 1604 — приблизительная дата. Некоторые женские фигуры отождествляются предположительно. Картина сжимает мотивы разных эпизодов после Распятия, а не иллюстрирует один буквальный евангельский рассказ. Название «Три Марии» не является бесспорным перечнем всех изображённых.',
'NG2923','Оплакивание Христа («Три Марии»)','The Dead Christ Mourned (The Three Maries)','около 1604','Масло на холсте; 92,8 × 103,2 см','annibale-carracci-the-dead-christ-mourned-the-three-maries',
'Проследи диагонали и взгляды по кругу от переднего плана к задним фигурам и обратно. Как разные выражения скорби объединяются благодаря расположению тел и смене холодных и тёплых цветов?');
add('agostino_carracci','Агостино Карраччи','Agostino Carracci','1557–1602',['Агостино Каррачи'],'Италия · подготовительный рисунок для фрески · конец XVI века',
['Агостино был старшим братом Аннибале и двоюродным братом Людовико. В росписях галереи Палаццо Фарнезе он участвовал в большом проекте, которым в целом руководил Аннибале.','Картон с Кефалом и Авророй — завершающая полноразмерная стадия подготовки одного из изображений потолка. Начатый в 1597 году цикл посвящён любви богов и опирается на античные и ренессансные образцы.'],
['Уголь и белый мел на бумаге; 202,5 × 398,8 см. Рисунок разрезали на участки, соответствующие свежей штукатурке, которую можно было расписать за один рабочий сеанс. Контуры переводили острым инструментом.','Аврора вталкивает сопротивляющегося Кефала в колесницу; Амур рассыпает лепестки. Собака и копьё обозначают охотника, а спящая фигура справа уравновешивает движение главной группы.'],
'Картон раскрывает связь замысла, натурального масштаба и технологии фрески. Он показывает рабочее устройство монументальной живописи, а не является уменьшенным самостоятельным вариантом потолочной сцены.',
['Колесница слева: найди направление действия.','Сопротивление Кефала: сравни движения двух главных фигур.','Амур с лепестками: проследи центральный мотив.','Собака и копьё: найди атрибуты охотника.','Полный масштаб: соотнеси рисунок с переносом на потолок.'],
'Около 1599 — приблизительная дата и ещё XVI век. Это рисунок, не масло и не сама фреска. Текущая запись связывает основное исполнение с Агостино; участие Аннибале, особенно в собаке, вероятно. Пожилой персонаж справа может быть Тифоном либо Океаном. Распределение авторства в исследованиях менялось.',
'NG147','Кефал, уносимый Авророй на колеснице','Cephalus carried off by Aurora in her Chariot','около 1599; конец XVI века','Уголь и белый мел на бумаге; полноразмерный картон; 202,5 × 398,8 см','agostino-carracci-cephalus-carried-off-by-aurora-in-her-chariot',
'Сравни движущуюся группу слева со спокойной фигурой справа. Затем представь рисунок на свежей штукатурке: почему художнику требовались полноразмерные контуры и деление работы на участки?');
add('ludovico_carracci','Людовико Карраччи','Ludovico Carracci','1555–1619',['Лодовико Карраччи','Людовико Каррачи'],'Италия · поздняя болонская живопись и психологическое напряжение',
['Людовико был двоюродным братом Аннибале и Агостино. Его поздняя «Сусанна и старцы» показывает, почему болонскую живопись нельзя свести к спокойному равновесию и единой формуле классицизма.','Картина предназначалась кавалеру Тито Бузио из Реджо. Письмо от 14 июня 1616 года говорит о почти завершённой работе; через пять дней её закончили и отправили заказчику.'],
['Масло на холсте; 146,6 × 116,5 см. Крупные фигуры тесно сдвинуты к зрителю. Неуравновешенная композиция и движения в противоположных направлениях создают ощущение угрозы.','Сильное освещение выделяет Сусанну и протянутые руки старцев; лица мужчин остаются в тени. Сад сведён к немногим необходимым элементам, включая фонтан и классический постамент.'],
'Жесты и светотень делают давление и сопротивление читаемыми без обилия декораций. Это драматическое развитие композиционного языка, а не отказ от тщательно рассчитанного построения.',
['Тесная группа: отметь близость к зрителю.','Диагональ: сравни наклоны фигур.','Встречные движения: проследи давление и отстранение.','Свет и тень: сопоставь лица и руки.','Садовый фон: найди минимальные признаки места действия.'],
'NG28 подписана и датирована 1616 годом. Сюжет — о домогательстве и шантаже, не взаимном ухаживании. Моральная роль освещения объяснена музеем, а не является физическим доказательством характера человека. Не смешивай Людовико с двумя братьями Карраччи.',
'NG28','Сусанна и старцы','Susannah and the Elders','1616','Масло на холсте; 146,6 × 116,5 см','ludovico-carracci-susannah-and-the-elders',
'Рассмотри движения рук и противоположные наклоны фигур без подробного пересказа насилия. Как теснота и контраст света помогают показать уязвимость героини и давление на неё?');
add('domenichino','Доменикино','Domenichino','1581–1641',['Доменико Дзампьери','Domenico Zampieri'],'Италия · классический пейзаж и композиционная преемственность',
['Доменикино учился у Аннибале Карраччи и неоднократно обращался к его композиционным решениям. «Пейзаж с укреплённым городом» тесно связан с «Бегством в Египет» учителя из дворца Альдобрандини.','Картина, вероятно, создана около 1634–1635 годов, во время возвращения художника в Рим. В отличие от повествовательных пейзажей, здесь нет одного достоверно определённого главного события.'],
['Масло на холсте; 113,2 × 197 см. На переднем плане рыбак разбирает улов, за ним наблюдают женщина с цветами и гитарой и ребёнок. Река, лодки, пастух и путники образуют несколько самостоятельных эпизодов.','Красные и белые пятна одежды связывают фигуры по всей картине. Лодочник — повторяющийся у Доменикино мотив, заимствованный у Аннибале; общая структура подчинена идеализированному пасторальному пространству.'],
'Пейзаж строится как осмысленная художественная среда, а не случайный вид с натуры. Уважительное повторение композиции учителя сочетается с новым распределением мелких действий и отсутствием обязательного единого сюжета.',
['Рыбак слева: найди начало цепочки занятий.','Женщина и ребёнок: сопоставь наблюдение и игру.','Лодочники справа: проследи движение по реке.','Пастух со стадом: найди средний план.','Красное и белое: проверь связи между разрозненными фигурами.'],
'Около 1634–1635 — предположительная дата. Не присваивай городу неподтверждённое имя и не объявляй всю сцену «Бегством в Египет» только из-за сходства с Аннибале. Некоторые рисунки могут быть подготовительными, но их связь с картиной также не бесспорна.',
'NG6629','Пейзаж с укреплённым городом','Landscape with a Fortified Town','около 1634–1635','Масло на холсте; 113,2 × 197 см','domenichino-landscape-with-a-fortified-town',
'Выбери маршрут от рыбака к лодкам и стаду. Затем ищи красные и белые пятна одежды: как они объединяют эпизоды, которые не складываются в один установленный рассказ?');
add('guercino','Гверчино','Guercino','1591–1666',['Джованни Франческо Барбьери','Giovanni Francesco Barbieri','Il Guercino'],'Италия · ранняя монументальная живопись и наблюдение натуры',
['Гверчино был преимущественно самоучкой, но его ранний язык сформировался рядом с художественными центрами Феррары и Болоньи. Особенно важен пример Людовико Карраччи и его внимание к изучению натуры.','«Илия, питаемый воронами» написан в 1620 году для кардинала Якопо Серры до поездки Гверчино в Рим. Раннюю светотень и приглушённую палитру нельзя автоматически переносить на всё позднее творчество художника.'],
['Масло на холсте; 195 × 156,5 см. Фигура пророка превышает натуральную величину и занимает почти всё пространство. Неудобный поворот тела, выступающая нога и поднятое лицо связывают монументальность с физическим усилием.','Направленный свет пересекает фигуру; тяжёлая драпировка позволяет ощутить скрытое под ней тело. Седая борода, меховая подкладка, холодный камень и отражающая поверхность ручья различаются фактурой.'],
'Библейский герой остаётся телесно убедительным человеком. Пустая миска и прорванная одежда объясняют нужду, а обращение к птицам связывает физическое ожидание пищи с религиозным доверием.',
['Большая фигура: сопоставь масштаб пророка с далью.','Поворот вверх: проследи ожидание птиц.','Плащ перед собой: найди жест принятия пищи.','Пустая миска: отметь предметный признак голода.','Разные фактуры: сравни бороду, ткань, камень и воду.'],
'1620 подтверждён историей заказа. Образ духовного питания — музейное толкование библейского сюжета. В старых инвентарях картину называли «Святым Павлом Отшельником»; текущая идентификация — Илия. Не смешивай NG6612 с другими пророками и поздними работами Гверчино.',
'NG6612','Илия, питаемый воронами','Elijah fed by Ravens','1620','Масло на холсте; 195 × 156,5 см','guercino-elijah-fed-by-ravens',
'Сравни грандиозный масштаб с неудобным поворотом и пустой миской. Затем найди контрасты фактур: как телесные подробности мешают превратить пророка в отвлечённый символ?');
B.agostino_carracci.sources.push(['Национальная галерея: родственные связи',N+'artists/agostino-carracci']);
B.domenichino.sources.push(['Национальная галерея: школа Карраччи',N+'artists/annibale-carracci']);
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

;
/* artists-batch-84.js */
(()=>{'use strict';
const N='https://www.nationalgallery.org.uk/',B={};
function add(id,name,latin,life,aliases,tag,bio,technique,innovation,features,caution,key,title,originalTitle,date,medium,museum,source,look){B[id]={name,latin,life,tag,aliases:[name,latin,...aliases],bio,technique,innovation,features,caution,sources:[[museum+': '+title,source]],works:[],pendingWorks:[{key,title,originalTitle,date,medium,museum,source,look,reason:'Музейный оригинал установлен; свободный файл репродукции и права на него не проверены. Изображение не подключено.'}],editorialStatus:'text_only_image_file_and_rights_pending'};}
add('giovanni_lanfranco','Джованни Ланфранко','Giovanni Lanfranco','1582–1647',['Джованни ди Стефано Ланфранко'],'Италия · религиозная живопись и совместное авторство',
['Ланфранко представлен здесь произведением, которое NGA относит одновременно к Орацио Джентилески и Джованни Ланфранко. Эта карточка не отменяет участие Орацио, уже включённого в батч 81.','Музейная запись указывает два этапа: около 1617–1618 и около 1621–1627. В инвентаре 1741 года картина описана как работа Ланфранко с головами Джентилески; формулировка принадлежит истории документирования объекта.'],
['Масло на холсте; 87,5 × 108 см. Сильный свет справа выделяет музыкантшу и ангела на тёмном фоне. Женщина наклоняет голову к небольшому органу, пальцы лежат на клавишах.','Красное платье, зеленоватые рукава и голубая одежда ангела различаются в локальном освещении. Ангел держит нотный лист: две строки содержат ноты, третья оставлена пустой.'],
'Картина объединяет свет, цвет и совместное действие музыкантши с ангелом. История её атрибуции помогает отделить единство видимого образа от сложного процесса создания.',
['Свет справа: проследи освещённые лица и руки.','Клавиши: найди положение пальцев.','Нотный лист: сравни заполненные и пустую строки.','Цвет одежд: сопоставь красный, зелёный и голубой.','Орган в ракурсе: проследи глубину узкого инструмента.'],
'Это NGA 1961.9.73 с совместным авторством, не бесспорно единоличная работа Ланфранко. Два интервала дат не сведены к одному году. Ранний владелец Натале Ронданини указан предположительно; инвентарное описание не заменяет технического исследования всех частей картины.',
'nga:46172','Святая Цецилия и ангел','Saint Cecilia and an Angel','около 1617–1618 и около 1621–1627','Масло на холсте; 87,5 × 108 см','Национальная галерея искусства, Вашингтон','https://www.nga.gov/artworks/46172-saint-cecilia-and-angel',
'Сопоставь руки на клавишах и лист, который держит ангел. Затем проследи действие света справа. Не пытайся уверенно распределить авторство отдельных мазков только по небольшой репродукции.');
B.giovanni_lanfranco.pendingWorks[0].attribution='Орацио Джентилески и Джованни Ланфранко — совместное авторство по NGA';
add('pietro_da_cortona','Пьетро да Кортона','Pietro da Cortona','1596–1669',['Пьетро Берреттини','Pietro Berrettini'],'Италия · раннее римское барокко',
['Кортона был живописцем, скульптором и архитектором, особенно известным иллюзорными фресковыми декорациями. «Святая Цецилия» относится к раннему этапу, до его ведущего положения при покровителях Барберини.','В начале 1620-х он общался с антикваром Кассиано даль Поццо, поощрявшим изучение античной скульптуры и архитектуры. Классический храм в глубине картины связывает этот интерес с образом святой, жившей в Риме III века.'],
['Масло на холсте; 143,5 × 108,9 см. Цецилия сидит у стола, держа пальмовую ветвь и нотный лист. Слева показан переносной орган, справа ангел опирается на арфу.','Венок из красных и белых роз расположен перед нимбом; из тени за занавесью выглядывает ещё одна фигура. Тёплая палитра, свободное письмо и драпировки близки ранним фрескам Кортоны в Палаццо Маттеи.'],
'Музыкальные атрибуты, легенда и античная архитектура согласованы в камерном религиозном образе. Раннее произведение раскрывает путь к барокко иначе, чем поздняя монументальная декорация.',
['Пальмовая ветвь: найди знак мученичества.','Нотный лист: сопоставь с органом слева.','Арфа справа: рассмотри позу ангела.','Венок роз: отдели его от нимба.','Храм вверху: найди исторический ориентир.'],
'1620–1625 — музейный интервал, не точный год. Картину прежде приписывали Доменикино, затем неизвестному римскому художнику; текущая атрибуция — Кортона. Венок и пальма объясняются через христианскую легенду, а не как документальная запись события.',
'ng:NG5284','Святая Цецилия','Saint Cecilia','1620–1625','Масло на холсте; 143,5 × 108,9 см','Национальная галерея, Лондон',N+'paintings/pietro-da-cortona-saint-cecilia',
'Сравни музыкальные предметы, венок и пальмовую ветвь. Затем найди античный храм. Как разные подробности соединяют музыку, легенду и представление об историческом Риме?');
add('andrea_sacchi','Андреа Сакки','Andrea Sacchi','1599/1600–1661',['Андреа Сакки'],'Италия · камерная религиозная композиция',
['Сакки работал главным образом в Риме и знал живопись Караваджо. В выбранной картине близкие полуфигуры и резкое освещение создают ощущение общего со зрителем пространства.','Святые Антоний и Франциск жили с разницей более семисот лет. Их соседство строится не как историческая встреча, а как сопоставление двух форм сосредоточенной религиозной жизни.'],
['Масло на холсте; 61 × 78 см. Антоний на переднем плане держит книгу, словно выступающую из плоскости картины; его рука готова перевернуть страницу.','Франциск находится чуть глубже, скрестив руки и подняв взгляд. Яркий косой свет слева объединяет фигуры, но различие поз подчёркивает их отдельные состояния.'],
'Простая композиция оказывается содержательным сопоставлением: чтение и внутреннее обращение вверх существуют рядом без прямого разговора. Небольшое число фигур усиливает различимость жестов.',
['Книга впереди: проследи эффект близости.','Т-образный посох: найди атрибут Антония.','Чёрное и коричневое: сравни монашеские одежды.','Скрещённые руки: сопоставь позу Франциска с чтением.','Косой свет: найди общий источник слева.'],
'До 1627 — верхняя граница датировки, не точный год. Предполагаемый заказ братьев Барберини не доказан. Сходная картина Бернини, вероятнее всего, объединена с этой позднее: размеры изменяли, а документы не подтверждают первоначальную пару. Религиозные атрибуты не делают изображение исторической встречей.',
'ng:NG6382','Святые Антоний Великий и Франциск Ассизский','Saints Anthony Abbot and Francis of Assisi','до 1627','Масло на холсте; 61 × 78 см','Национальная галерея, Лондон',N+'paintings/andrea-sacchi-saints-anthony-abbot-and-francis-of-assisi',
'Сопоставь книгу и готовую перевернуть страницу руку с поднятым взглядом Франциска. Почему одинаковое освещение и общее пространство не превращают фигуры в участников разговора?');
add('carlo_maratta','Карло Маратта','Carlo Maratta','1625–1713',['Карло Маратти','Carlo Maratti'],'Италия · официальный портрет и позднее римское барокко',
['Маратта приехал в Рим молодым и добился значительного успеха. Ватиканский музей связывает его ведущее положение в художественной жизни города после 1669 года со смертью Пьетро да Кортоны.','Связанный с папским кругом, он писал многочисленные религиозные произведения, но также прославился портретами. «Климент IX» показывает официальную роль модели без отказа от индивидуальной выразительности.'],
['Масло на холсте; 145 × 116 см. Папа сидит на троне, развёрнутый в три четверти. Государственный формат соединён с вниманием к выражению лица.','Музей прямо сопоставляет постановку с «Портретом Иннокентия X» Веласкеса. Заимствованный композиционный образец становится средством самостоятельного портретного решения, а не свидетельством одинакового автора.'],
'Официальный образ власти может сохранять психологическую выразительность. Преемственность портретной позы позволяет сравнить не только внешние атрибуты, но и разные способы представить личность в церемониальном формате.',
['Поворот в три четверти: определи положение корпуса.','Сидящая поза: сопоставь устойчивость и обращение к зрителю.','Трон: найди официальный контекст.','Лицо: сравни индивидуальное выражение с церемониальностью.','Композиционный образец: сопоставь с Веласкесом, не смешивая модели.'],
'Ватиканская картина подписана и датирована 1669 годом; кат. 40460. Это Климент IX Роспильози, не Иннокентий X. Портреты из других собраний нельзя заменять этой версией или переносить их размеры. Психологическая проницательность — музейная оценка, не медицинское заключение о модели.',
'vatican:40460','Портрет папы Климента IX','Portrait of Clement IX','1669','Масло на холсте; 145 × 116 см','Пинакотека Ватикана','https://www.museivaticani.va/content/museivaticani/en/collezioni/musei/la-pinacoteca/sala-xv---secolo-xviii/carlo-maratta--ritratto-di-clemente-ix.html',
'Сравни церемониальную устойчивость сидящей фигуры с выражением лица. Затем отдели сходство постановки с Веласкесом от различия моделей и самостоятельности исполнения.');
add('giovanni_battista_gaulli','Джованни Баттиста Гаулли','Giovanni Battista Gaulli','1639–1709',['Бачиччо','Бачичча','Il Baciccio','Giovanni Battista Gauli'],'Италия · барочная иллюзия и подготовительный эскиз',
['Гаулли, известный как Бачиччо, создал декорацию потолка римской церкви Иль-Джезу. Бернини помог ему получить заказ для главного храма ордена иезуитов.','Принстонская работа — большой подготовительный эскиз, редкий документ создания монументальной росписи. Музей объясняет композицию в связи с религиозной и миссионерской программой заказчика.'],
['Масло на бумаге, наклеенной на холст; 163 × 111 см. Светящиеся группы святых и ангелов обращены к монограмме IHS, обозначающей имя Иисуса.','Противоположное движение фигур в темноту усиливает впечатление сияющего открытого неба. В эскизе уже выражена идея приближения небесного пространства к зрителю и преодоления границы потолка.'],
'Подготовительная живопись передаёт не только расположение фигур, но и общий зрительный напор будущей декорации. Свет, разнонаправленное движение и предполагаемая архитектурная рамка создают иллюзию пространственного прорыва.',
['IHS: найди смысловой центр.','Светящиеся группы: проследи движение к монограмме.','Падение в темноту: сопоставь противоположные направления.','Граница неба: найди эффект раскрывающегося пространства.','Вертикальный формат: соотнеси эскиз с задачей потолочной росписи.'],
'1676–1679 — музейный интервал. Принстонский 2005-34 — не сама фреска и не её фотография. Бумага укреплена на холсте: не сокращаем технику до масла на холсте. Письменная иконографическая программа не сохранилась; связь с Посланием к Филиппийцам объясняет музей. Бачиччо и Гаулли — один автор.',
'princeton:2005-34','Триумф имени Иисуса','The Triumph of the Name of Jesus','1676–1679','Масло на бумаге, наклеенной на холст; 163 × 111 см','Художественный музей Принстонского университета','https://artmuseum.princeton.edu/art/collections/objects/45004',
'Проследи два встречных движения: к сияющей монограмме и от неё в темноту. Что уже решено в эскизе, а что требует реального архитектурного пространства и взгляда снизу?');
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

