/* artists-batch-86.js */
(()=>{'use strict';
const B={},N='https://www.nationalgallery.org.uk/paintings/';
function add(id,name,latin,life,tag,bio,technique,innovation,features,caution,key,title,originalTitle,date,medium,museum,source,look){B[id]={name,latin,life,tag,aliases:[name,latin],bio,technique,innovation,features,caution,sources:[[museum+': '+title,source]],works:[],pendingWorks:[{key,title,originalTitle,date,medium,museum,source,look,reason:'Оригинал установлен; конкретный свободный файл репродукции и его права не проверены.'}],editorialStatus:'text_only_image_file_and_rights_pending'};}
add('luca_giordano','Лука Джордано','Luca Giordano','1634–1705','Италия · барокко · Неаполь и Флоренция',
['«Пещера Вечности» связана с росписями палаццо Медичи-Риккарди во Флоренции, исполненными в 1682–1685 годах. Общая программа прославляет возвышение человечества через Мудрость и Добродетель и включает прославление Медичи.','Двенадцать масляных modelli показывают отдельные части ансамбля; десять находятся в Национальной галерее. Выбранная сцена соответствует одному из коротких концов галереи.'],
['Масло на холсте; 73,1 × 87,5 см. Группы фигур связаны общей аллегорической программой, а змея, кусающая свой хвост, окружает их как знак вечности.','Янус держит руно, из которого Парки прядут нить жизни; Атропос готовится её перерезать. Прометей поднимает факел. Такие детали превращают собрание фигур в рассказ о времени и смертности.'],
'Самостоятельный масляный этюд позволяет изучить устройство большой декоративной программы: отдельные символы работают не порознь, а внутри общей организации пространства.',
['Змея: проследи замкнутый контур.','Янус: рассмотри два направления взгляда.','Парки: найди последовательность работы с нитью.','Ножницы Атропос: отметь момент завершения.','Факел Прометея: сопоставь свет и мифологический смысл.'],
'Начало 1680-х — дата холста, не точные годы росписи. Музей представляет работу как modello, но приводит и гипотезу о позднейшем ricordo. Фигура в капюшоне, вероятно, Демогоргон. Аллегорические толкования не единственно возможные. Не выдаём холст за фрагмент фрески.',
'ng:NG6637','Пещера Вечности','The Cave of Eternity','начало 1680-х','Масло на холсте; 73,1 × 87,5 см','Национальная галерея, Лондон',N+'luca-giordano-the-cave-of-eternity',
'Проследи путь от руна к нити и ножницам. Затем сравни круг Парок с окружающей змеёй: как движение жизни включено в идею вечности?');
add('francesco_solimena','Франческо Солимена','Francesco Solimena','1657–1747','Неаполь · барокко на рубеже XVII–XVIII веков',
['В начале XVIII века Солимена был ведущим живописцем Неаполя. Его «Дидона» переносит историю из первой книги «Энеиды» в монументальную сцену приёма.','Письмо художника 1711 года подтверждает заказ кардинала Винченцо Гримани. Заказчик умер до окончательного расчёта; Солимена продал картину графу Пеллегрино Ферри в Падуе.'],
['Масло на холсте; 207,2 × 310,2 см. Фигуры расположены подобно фризу и обращены к Дидоне; низкая точка зрения усиливает сходство с театральной сценой.','Яркий свет выделяет ткани, доспехи и тело Амура, а сопровождающие отступают в тень. Эней приветствует царицу, но её внимание захвачено ребёнком.'],
'Рассказ строится на разнице знания зрителя и персонажей: нам видны крылья и стрелы Амура, которого Дидона и Эней принимают за Аскания. Свет и жесты делают эту разницу читаемой.',
['Амур: найди скрытую от героев личность.','Руки: сравни приветствие Энея и контакт ребёнка с царицей.','Дары: отметь предметы, которых Дидона не замечает.','Фриз: проследи направление фигур.','Тень: отдели свиту от освещённых участников.'],
'1710 — музейная дата, это уже XVIII век. Влияние оперной постановки вероятно, но конкретный спектакль не доказан. Первоначальное размещение и имперское прочтение сюжета предположительны. В провенансе 1933–1945 остаются пробелы.',
'ng:NG6397','Дидона принимает Энея и Амура под видом Аскания','Dido receiving Aeneas and Cupid disguised as Ascanius','1710','Масло на холсте; 207,2 × 310,2 см','Национальная галерея, Лондон',N+'francesco-solimena-dido-receiving-aeneas-and-cupid-disguised-as-ascanius',
'Сравни доступные зрителю признаки Амура с реакцией Дидоны. Как богатые дары становятся второстепенными перед простым прикосновением?');
add('giovanni_battista_recco','Джованни Баттиста Рекко','Giovanni Battista Recco','XVII век; точные годы жизни спорны','Неаполь · натюрморт и светотень',
['Корпус работ Рекко уточнялся исследованиями 1950–1960-х годов. «Натюрморт с рыбой и устрицами» сыграл важную роль в выделении его самостоятельной манеры.','Произведения путали с натюрмортами Джованни Баттисты Руопполо: оба пользовались инициалами GBR. Авторство выбранной картины музей уверенно связывает с Рекко по сравнительному изучению подписанной работы из Безансона.'],
['Масло на холсте; 100 × 126 см. Сине-серые и белые устрицы противопоставлены оранжево-красной рыбе на тарелке в переднем плане.','Глубокая светотень усиливает перламутр раковин и блеск влажной плоти. Сдержанная организация связывает обыденный мотив с тонким наблюдением фактур.'],
'Разница поверхностей становится основным содержанием натюрморта: зритель различает раковину, влажную плоть и чешую через свет и цвет, а не через сюжетное действие.',
['Перламутр: найди холодный блеск.','Красная рыба: сравни тёплое и холодное.','Тёмный интерьер: оцени силу контраста.','Влажная плоть: отличи её от раковины.','Передний план: проследи сдержанное расположение предметов.'],
'Картина датирована 1653. Прежняя атрибуция Джузеппе Руопполо не равна нынешней. Монограмма GBR сама по себе недостаточна. Шведская карточка даёт 1631–1676, Прадо в тексте о Джузеппе Рекко — 1615–1660; не выбираем молча один интервал. Лак пожелтел, импасто уплощено при дублировании.',
'nationalmuseum:NM759','Натюрморт с рыбой и устрицами','Still life with fish and oysters','1653','Масло на холсте; 100 × 126 см','Национальный музей Швеции, Стокгольм','https://collection.nationalmuseum.se/en/collection/item/17762/',
'Сравни сине-серый блеск устриц с оранжево-красной рыбой. Где оттенок сообщает о материале сильнее, чем контур?');
add('giuseppe_recco','Джузеппе Рекко','Giuseppe Recco','1634–1695','Неаполь · барочный натюрморт',
['Рекко работал с кухонными сценами, рыбой, цветами, фруктами, музыкальными инструментами и предметами vanitas. Прадо отмечает соединение испанских, североевропейских и римских традиций натюрморта.','Выбранная работа происходит из собрания Филиппа V. Поздняя манера художника движется от статичного расположения предметов к более сценической природе на морском берегу.'],
['Масло на холсте. Рыбы, кальмар и большая морская черепаха размещены на прибрежных камнях; в глубине открывается вечернее небо.','Мелкие капли, водоросли, прозрачность воды и серебристая чешуя связывают убедительность деталей с декоративной организацией целого. Панцирь, ласты и морщинистая шея черепахи тщательно различены.'],
'Натюрморт выходит из замкнутого интерьера: берег и небо превращают показ улова в сценическую композицию, не отменяя подробного изучения материалов.',
['Панцирь: рассмотри крупную форму.','Ласты: проследи выход за край камня.','Капли: найди малые световые акценты.','Кальмар: сравни влажную поверхность с чешуёй.','Небо: оцени переход от предметов к пространству.'],
'Около 1680 — стилистическая датировка, не год на подписи. Монограмма G. R. отмечена справа внизу. Джузеппе и Джованни Баттиста Рекко — разные авторы. Размер в этой карточке не уточняется; ключ редакционный, не инвентарный номер Прадо.',
'editorial:giuseppe-recco-fish-turtle-prado','Натюрморт с рыбой и черепахой','Still Life with Fish and Turtle','около 1680','Масло на холсте','Прадо, Мадрид','https://www.museodelprado.es/en/the-collection/art-work/still-life-with-fish-and-turtle/84f04e1a-9210-4fae-945f-b7fe84cc1869',
'Сравни близкую поверхность панциря с открытым небом. Как соседство подробных предметов и дали меняет привычный масштаб натюрморта?');
add('paolo_porpora','Паоло Порпора','Paolo Porpora','1617–1673','Италия · барокко · sottobosco',
['Порпора представлен небольшим натюрмортом-подлеском: земноводные, насекомые, раковины и растения становятся самостоятельным предметом рассматривания.','Музей объясняет sottobosco как крупноплановое изображение природного микромира. Животных обычно изучали отдельно, а затем соединяли в эстетически организованную композицию.'],
['Масло на холсте; 35 × 48 см. Небольшой формат предполагает близкое рассматривание лягушек, роз, раковин и бабочек.','Точность отдельных деталей сочетается с составным устройством сцены. Кажущаяся естественность соседства не доказывает, что перед нами запись одного реального наблюдения.'],
'Натюрморт может изображать живую природу: привычные малозаметные существа получают собственную композицию, где наблюдение и художественный отбор действуют вместе.',
['Лягушки: найди несколько природных форм.','Дикие розы: сравни растение и животное.','Раковины: рассмотри твёрдую поверхность.','Бабочки: сопоставь хрупкость и плотность.','Соседство мотивов: проверь, как детали собраны в целое.'],
'1650-е — музейная датировка. Толкование как борьбы добра и зла принадлежит музейному описанию, не исчерпывает смысл и не заменяет наблюдение. NM 5271 не смешиваем с парной NM 5272 со змеями, мухоморами и чертополохом.',
'nationalmuseum:NM5271','Натюрморт с лягушками, дикими розами, раковинами и бабочками','Still-life with frogs, wild roses, shells and butterflies','1650-е','Масло на холсте; 35 × 48 см','Национальный музей Швеции, Стокгольм','https://collection.nationalmuseum.se/en/collection/item/22321/',
'Сначала раздели изображение на растения, животных и раковины, затем собери их взглядом заново. Что создаёт ощущение единой среды, хотя художник мог изучать мотивы раздельно?');
B.giovanni_battista_recco.sources.push(['Прадо: альтернативные даты Джованни Баттисты в тексте о Джузеппе Рекко',B.giuseppe_recco.sources[0][1]]);
B.paolo_porpora.sources.push(['Национальный музей Швеции: авторство, техника и парные натюрморты','https://www.nationalmuseum.se/en/webtour/konst-p%C3%A5-rymmen-leta-efter-djur-och-annat']);
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

;
/* artists-batch-87.js */
(()=>{'use strict';
const B={},P='https://www.museodelprado.es/en/the-collection/art-work/';
function add(id,name,latin,life,aliases,tag,bio,technique,innovation,features,caution,key,title,originalTitle,date,medium,museum,source,look,coauthors){B[id]={name,latin,life,aliases:[name,latin,...aliases],tag,bio,technique,innovation,features,caution,sources:[[museum+': '+title,source]],works:[],pendingWorks:[{key,title,originalTitle,date,medium,museum,source,look,...(coauthors?{coauthors}:{}),reason:'Музейная запись установлена; конкретный свободный файл репродукции и его права не проверены.'}],editorialStatus:'text_only_image_file_and_rights_pending'};}
add('andrea_vaccaro','Андреа Ваккаро','Andrea Vaccaro','XVII век',[],'Неаполь · барокко и классическая сдержанность',
['Ваккаро соединял неаполитанский натурализм с более упорядоченными формами, связанными с болонским классицизмом. Прадо отмечает созвучие его решений Гвидо Рени и Массимо Станционе.','«Вознесение святого Януария» связано с почитанием покровителя Неаполя после извержения Везувия в 1631 году. Внизу художник подробно показывает город с портом, домами и памятниками.'],
['Масло на холсте; музей датирует работу 1635 годом. Святой в епископском облачении поднимается среди облаков и херувимов, но композиция избегает головокружительного вихря.','Обращённый к свету взгляд, рука у сердца и два сосуда с кровью связывают жесты с религиозным смыслом. Сдержанный цвет поддерживает торжественную, но измеренную интонацию.'],
'Чудесное событие становится понятным через спокойную организацию жестов и связь небесной группы с подробно изображённым городом: эмоциональность не требует стремительного движения.',
['Взгляд: проследи направление к свету.','Рука у сердца: сопоставь жест и внутреннее состояние.','Два сосуда: найди атрибут мученичества.','Облака: оцени сдержанность подъёма.','Город внизу: найди связь святого с Неаполем.'],
'1635 — музейная дата. Спасение города и разжижение крови обозначаем как религиозную традицию, а не доказанные природные события. Связь с композицией Риберы не делает картину копией. Обучение у Джироламо Импарато традиционно предполагается, но не выдаётся за установленный факт.',
'editorial:vaccaro-ascension-gennaro-prado','Вознесение святого Януария','The ascension of Saint Gennaro','1635','Масло на холсте; размеры здесь не уточняются','Прадо, Мадрид',P+'the-ascension-of-saint-gennaro/6f74aeba-63fe-4a69-b78b-daccfb26459e',
'Сравни спокойствие жестов с необычностью небесного события. Затем опусти взгляд к городу: как нижняя часть уточняет смысл заступничества?');
add('aniello_falcone','Аньелло Фальконе','Aniello Falcone','XVII век',[],'Неаполь · античный сюжет для Буэн-Ретиро',
['«Римские атлеты» входят в большой цикл истории Древнего Рима для дворца Буэн-Ретиро в Мадриде. Группа посвящена публичным развлечениям: упражнениям, состязаниям, колесницам и другим зрелищам.','Прадо связывает эти изображения с антикварной литературой и гравюрами: трудами Онофрио Панвинио и Джироламо Меркуриале. Живопись реконструирует античные обычаи через знания XVII века.'],
['Масло на холсте; около 1640. Музей выделяет в сцене приношения атлетов перед состязаниями; это церемония, а не только демонстрация физических упражнений.','Почти квадратный формат следует рассматривать с учётом дворцового ансамбля. Поздняя опись указывает место над окном, но исходная развеска непосредственно не описана.'],
'Историческая картина показывает не только героев и битвы: подготовительная церемония позволяет сопоставить современный художнику дворцовый досуг с воображаемой Античностью.',
['Приношение: найди действие до состязания.','Участники: сопоставь разные роли в церемонии.','Жесты: проследи, как они связывают группу.','Формат: оцени почти квадратную организацию.','Детали обычая: отдели реконструкцию от прямого свидетельства.'],
'Около 1640 — приблизительная дата. Зависимость от учёных реконструкций не означает точной исторической достоверности всех деталей. Размещение над окном известно по описи 1701 года; первоначальная развеска предполагается. Музейное обозначение P92 нормализовано в ключе как P00092.',
'prado:P00092','Римские атлеты','Roman Athletes','около 1640','Масло на холсте; размеры здесь не уточняются','Прадо, Мадрид',P+'roman-athletes/149e8946-1390-44bf-9936-5b705fb3a180',
'Найди приношение перед состязанием. Какие действия отличают церемонию от упражнения? Рассматривай сцену как реконструкцию XVII века, а не документ древнеримского очевидца.');
add('domenico_gargiulo','Доменико Гарджуло','Domenico Gargiulo','XVII век',['Микко Спадаро','Micco Spadaro'],'Неаполь · фигуры в совместной архитектурной композиции',
['«Триумфальный въезд Веспасиана в Рим» — ранний пример сотрудничества Гарджуло и Вивиано Кодацци. Гарджуло написал фигуры, Кодацци — архитектурное окружение.','Полотно входило в цикл для Буэн-Ретиро. Триумфальная процессия объединяет императора, войска, побеждённых и добычу; человеческие группы наполняют архитектурную сцену действием.'],
['Масло на холсте; 1636–1638. Фигуры расположены подобно фризу, а процессуальный ритм ведёт взгляд через композицию.','Архитектура Кодацци соединяет античные и ренессансные мотивы. На этом фоне Гарджуло организует участников так, чтобы зритель различал этапы и роли в шествии.'],
'Совместная картина позволяет увидеть специализацию не как разрыв, а как согласование двух способов построения сцены: человеческого действия и архитектурного пространства.',
['Процессия: проследи её ритм.','Передний план: выдели главные фигуры.','Дальний участник: сравни два предполагаемых императорских образа.','Группы: раздели участников по действиям.','Архитектура: оцени, как она направляет шествие.'],
'Соавторство обязательно: это не единоличная работа Гарджуло. Веспасиан и Тит определены предположительно; музей сохраняет традиционное название. Предположение о парной развеске не равно документу. P237 нормализовано в ключе как P00237. Микко Спадаро — прозвище того же художника.',
'prado:P00237','Триумфальный въезд Веспасиана в Рим','Vespasian’s Triumphal Entry in Rome','1636–1638','Масло на холсте; совместная работа','Прадо, Мадрид',P+'vespasians-triumphal-entry-in-rome/e211c226-ec81-41cd-98b9-52c54000a3c7',
'Проследи шествие как последовательность групп, затем сравни её с архитектурным фоном. Какие задачи решают фигуры Гарджуло, а какие — здания Кодацци?',
[{name:'Доменико Гарджуло',role:'Фигуры'},{name:'Вивиано Кодацци',role:'Архитектура'}]);
add('viviano_codazzi','Вивиано Кодацци','Viviano Codazzi','XVII век',[],'Италия · архитектурная перспектива и реконструкция',
['Кодацци происходил из области Бергамо; его присутствие в Неаполе документировано с 1633 года. В совместных работах с Гарджуло он отвечал за архитектуру, тогда как партнёр писал фигуры.','«Перспективный вид римского амфитеатра» относится к четырём реконструкциям античных зрелищ для Буэн-Ретиро. Музей датирует заказ приблизительно 1638 годом.'],
['Масло на холсте; около 1638. Часть наружной стены словно снята: зритель видит внутреннее устройство здания, а горизонтально расширенная композиция подчёркивает изгиб трибун.','Кодацци обращался к печатным реконструкциям, связанным с Джакомо Лауро и Себастьяно Серлио. Множество крошечных зрителей, написанных Гарджуло, сообщает зданию ощущение огромного масштаба.'],
'Архитектурная живопись не только показывает фасад, но и объясняет устройство пространства. Условный разрез, перспектива и фигуры-масштабы действуют как согласованный способ рассматривания.',
['Снятая стена: найди границу внешнего и внутреннего.','Трибуны: проследи большой изгиб.','Кладка: рассмотри выступающие блоки.','Малые фигуры: оцени масштаб.','Арена: отдели одновременные действия.'],
'Соавторство Гарджуло сохраняется. Это реконструкция, а не точная зарисовка Колизея с натуры. Выбор между конкретными печатными источниками не окончателен. Средневековая башня и изменённые пропорции не позволяют считать вид чистым изображением античного состояния. Размеры и инвентарный номер здесь не уточняются; ключ редакционный.',
'editorial:codazzi-roman-amphitheatre-prado','Перспективный вид римского амфитеатра','Perspective View of a Roman Amphitheatre','около 1638','Масло на холсте; совместная работа','Прадо, Мадрид',P+'perspective-view-of-a-roman-amphitheatre/bd4264e9-07f5-4728-b491-bdfdaaa28c21',
'Найди место, где наружная стена открывает внутренность здания. Как изгиб трибун и маленькие зрители помогают понять его объём? Что отличает такую реконструкцию от обычного городского вида?',
[{name:'Вивиано Кодацци',role:'Архитектура'},{name:'Доменико Гарджуло',role:'Фигуры'}]);
add('francesco_de_mura','Франческо де Мура','Francesco de Mura','XVIII век',[],'Италия · группа фигур и направление взгляда',
['Для знакомства с де Мурой выбрано небольшое полотно «Трое мужчин, смотрящих вверх» из Музея изобразительных искусств в Будапеште. Музей датирует его 1739 годом.','Карточка предлагает рассмотреть, как общее направление взглядов связывает несколько фигур и предполагает предмет внимания за пределами изображения. Это учебный вопрос, не установленное толкование сюжета.'],
['Масло на холсте; 60 × 45 см. Вертикальный формат и три персонажа дают основу для близкого сравнения поворотов головы и распределения внимания.','При рассматривании предлагается сопоставить сходство и различие жестов, направления взглядов и положение фигур. Эти ориентиры не заменяют недостающее музейное объяснение назначения полотна.'],
'Изображённый предмет внимания может оставаться за рамой, тогда как взаимное направление фигур уже создаёт смысловую связь. Здесь это способ анализа, а не заявление о конкретной утраченной композиции.',
['Три фигуры: выдели каждого участника.','Взгляды: сравни их направления.','Головы: сопоставь повороты.','Вертикальный формат: оцени организацию группы.','Вне рамы: проверь, куда направлено внимание.'],
'1739, техника и размер взяты из музейной записи. Названия персонажей, конкретный сюжет и связь с определённой фреской не установлены в проверенных данных. Не называем полотно этюдом к известной росписи. Рисунок «Вознесение Богоматери» 1751 года из Метрополитен-музея — другое произведение. Ключ редакционный по адресу записи.',
'editorial:mfab-12098','Трое мужчин, смотрящих вверх','Three Men looking upwards','1739','Масло на холсте; 60 × 45 см','Музей изобразительных искусств, Будапешт','https://www.mfab.hu/artworks/12098/',
'Сравни направления трёх взглядов. Кажется ли предмет внимания общим? Объясни ответ видимыми признаками, не придумывая имена персонажей или отсутствующий сюжет.');
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

;
/* artists-batch-88.js */
(()=>{'use strict';
const B={};
function add(id,name,latin,life,aliases,tag,bio,technique,innovation,features,caution,key,title,originalTitle,date,medium,museum,source,look){B[id]={name,latin,life,aliases:[name,latin,...aliases],tag,bio,technique,innovation,features,caution,sources:[[museum+': '+title,source]],works:[],pendingWorks:[{key,title,originalTitle,date,medium,museum,source,look,reason:'Музейная запись установлена; конкретный свободный файл репродукции и его права не проверены.'}],editorialStatus:'text_only_image_file_and_rights_pending'};}
add('andrea_di_lione','Андреа ди Лионе','Andrea di Lione','1610–1685',[],'Неаполь · античное зрелище и печатные источники',
['«Слоны в цирке» входят в цикл истории Древнего Рима для Буэн-Ретиро. Художник обращался к антикварной литературе, реконструируя представления, а не документируя собственное присутствие в древнем цирке.','Исходным образцом стала таблица III из Speculum Romanae Magnificentiae Антуана Лафрери, издания 1575 года. Три слона с гравюры точно повторены в известном подготовительном рисунке ди Лионе.'],
['Масло на холсте; около 1640. Животные расположены двумя рядами, трибуны заполнены маленькими зрителями. Четыре танцора и музыканта впереди напоминают фигуры вакхических сцен Пуссена.','Ди Лионе не просто повторяет образец: меняет расположение животных, добавляет пространственную рамку цирка и человеческое действие. Красочный строй связан также с влиянием Кастильоне.'],
'Зрелище рождается из соединения печатной реконструкции, переработанных животных и самостоятельного фигурного переднего плана. Убедительность изображения не равна работе с натуры.',
['Два ряда: проследи расстановку слонов.','Трибуны: найди маленькие фигуры.','Передний план: отдели музыкантов и танцоров.','Цирк: оцени роль архитектурной рамки.','Повторение и изменение: сравни животных внутри группы.'],
'Около 1640 — приблизительная дата. Прежняя датировка 1655 опиралась на ошибочное предположение о слонах с натуры. Конкретное историческое событие не установлено; общая иллюстрация развлечений вероятнее. Участие Фальконе в получении заказа и встречи с Кастильоне предположительны. Ключ редакционный, не инвентарный номер.',
'editorial:di-lione-elephants-prado','Слоны в цирке','Elephants in a Circus','около 1640','Масло на холсте; размеры здесь не уточняются','Прадо, Мадрид','https://www.museodelprado.es/en/the-collection/art-work/elephants-in-a-circus/eed7ed66-4d51-4593-b44c-1f2cb1b1f901',
'Сравни порядок животных и свободное движение людей впереди. Почему впечатление живой сцены ещё не доказывает, что художник видел таких слонов собственными глазами?');
add('giovanni_battista_ruoppolo','Джованни Баттиста Руопполо','Giovanni Battista Ruoppolo','1629–1693',['Джован Баттиста Руопполо','Giovan Battista Ruoppolo'],'Неаполь · натюрморт и пространственная цепочка',
['По описанию бостонского музея, Руопполо прожил всю жизнь в Неаполе и оставил значительную школу последователей. Его повторяющиеся мотивы включают инжир, раскрытые гранаты, виноград и дыню.','В выбранном натюрморте фрукты и мёртвые птицы соединены с пейзажем. Урна, уходящая за верхний край картины, организует предметы, которые изгибаются к переднему плану.'],
['Масло на холсте; 75 × 36,5 см. Узкий вертикальный формат делает движение от высокой урны к ближним предметам важным способом связать композицию.','Для рассматривания предлагается сравнить раскрытый гранат, каскад винограда и шершавую поверхность дыни: разные формы поддерживают общее пространственное движение.'],
'Предметы не просто перечислены, а выстроены в цепочку между глубиной и передним планом. Натюрморт становится упражнением в чтении пространства через последовательность форм.',
['Урна: найди форму, уходящую за верхний край.','Гранаты: рассмотри раскрытые плоды.','Виноград: проследи каскад.','Дыня: сравни её поверхность с ягодами.','Передний план: восстанови путь от урны к зрителю.'],
'Дата произведения в доступной записи не указана; не придумываем точный год. Годы жизни здесь следуют бостонскому музею. Не смешиваем Джованни Баттисту с Джузеппе Руопполо и обоих Рекко. Римское происхождение из старой галереи известно лишь как утверждение надписи на подрамнике, не полностью восстановленный провенанс.',
'mfa:90.82','Натюрморт с фруктами и мёртвыми птицами в пейзаже','Still Life with Fruit and Dead Birds in a Landscape','XVII век; точная дата в доступной записи не указана','Масло на холсте; 75 × 36,5 см','Музей изящных искусств, Бостон','https://collections.mfa.org/objects/31012',
'Начни с урны и проследи предметы к переднему плану. Где композиция изгибается и что удерживает множество разных плодов в едином движении?');
add('giuseppe_ruoppolo','Джузеппе Руопполо','Giuseppe Ruoppolo','около 1639–1710',[],'Неаполь · натюрморт и материальность плодов',
['Метрополитен-музей называет Джузеппе учеником его дяди Джованни Баттисты Руопполо. Их живопись сохраняет ощутимую материальность, отличную от более гладких форм ряда североитальянских натюрмортов.','Свежие и высушенные плоды и орехи в выбранной работе вместе обозначают осень. Музей связывает её свет и материальную убедительность с воздействием Караваджо на неаполитанскую живопись.'],
['Масло на холсте; 76,2 × 128,3 см. Горизонтальный формат позволяет сравнивать разные состояния плодов и различать их поверхности.','Ориентиры для рассматривания — свежесть и сухость, плотность и хрупкость. Это способ проверить музейное наблюдение о материальности на конкретных деталях, а не универсальный рецепт узнавания автора.'],
'Время года передаётся состоянием вещей: свежие и высушенные продукты образуют сезонный рассказ без человеческого действия.',
['Свежие плоды: найди признаки сочности.','Высушенные плоды: сравни состояние поверхности.','Орехи: рассмотри плотность оболочки.','Контрасты: сопоставь соседние фактуры.','Общее изобилие: оцени сезонный смысл группы.'],
'Около 1660–1669 — музейная датировка, не точная дата подписи. Джузеппе — самостоятельный автор, не алиас Джованни Баттисты. Осень — музейное толкование совокупности продуктов. Public Domain в записи подтверждён, но конкретный файл для встраивания ещё не проверен.',
'met:2020.263.10','Натюрморт с фруктами и орехами','Still Life of Fruit and Nuts','около 1660–1669','Масло на холсте; 76,2 × 128,3 см','Метрополитен-музей, Нью-Йорк','https://www.metmuseum.org/art/collection/search/816520',
'Сравни свежие и высушенные плоды. Какие различия видимы в поверхности, а какие приходится предполагать? Затем проверь, как эти наблюдения поддерживают осеннее прочтение.');
add('andrea_belvedere','Андреа Бельведере','Andrea Belvedere','XVII–XVIII века',[],'Неаполь и Мадрид · декоративный цветочный натюрморт',
['Прадо рассматривает выбранную «Вазу с цветами» вместе с парной композицией. Бронзовые сосуды поддерживают пышные букеты, почти заполняющие поверхность обоих полотен.','Музей связывает их исполнение с мадридским пребыванием художника в конце XVII века. Бельведере развивает неаполитанские и римские традиции цветочного натюрморта в сторону сложного декоративного ансамбля.'],
['Масло на холсте; 1694–1700. Контраст фактур и цветов организует обильную растительную массу, не позволяя воспринимать букет только как перечень видов.','Фон светлее внизу и темнеет кверху, усиливая объём цветов. Лёгкость и декоративный размах музей связывает с эффектами, которые станут характерны для XVIII века.'],
'Букет превращается в барочную декорацию: цвет, фактура и фон работают на единое впечатление пышности и объёма.',
['Цветочная масса: оцени заполнение холста.','Контрасты: найди соседние цвета.','Фактуры: сравни разные растения.','Фон: проследи затемнение вверх.','Сосуд: сопоставь опору и раскидистый букет.'],
'Использована конкретная музейная запись по URL, но её соответствие P549 или P550 не установлено в доступных данных. Поэтому ключ редакционный; размеры и декор выбранной вазы не конкретизируются. В паре у P550 тритоны, у P549 херувимы; не переносим их на выбранную работу наугад. Мадридское исполнение — музейное заключение.',
'editorial:belvedere-prado-c1fe28dc','Ваза с цветами','Vase of Flowers','1694–1700','Масло на холсте; размеры здесь не уточняются','Прадо, Мадрид','https://www.museodelprado.es/en/the-collection/art-work/vase-of-flowers/c1fe28dc-7453-45c5-b1a1-983155a7ac9b',
'Проследи изменение фона снизу вверх. Какие цветы выступают вперёд, какие отступают? Объясни объём отношениями цвета и света, не только количеством растений.');
add('abraham_brueghel','Абрахам Брейгель','Abraham Brueghel','1631–1697',['Абрахам Брюгель'],'Фландрия и Италия · римский и неаполитанский натюрморт',
['Музей Бойманса — ван Бёнингена указывает рождение художника в Антверпене и смерть в Неаполе. Выбранные «Фрукты и цветы» помогают проследить связь его римского и неаполитанского периодов.','По музейному описанию, композиция и техника кисти находятся между поздними римскими произведениями и характерными работами неаполитанского периода. Поэтому вероятной считается середина 1670-х годов.'],
['Масло на холсте; 74,9 × 97,3 см. В натюрморте соединены фрукты, цветы и декоративный сосуд; предлагается сравнить формы растительной массы и предметов.','Вместо поиска одного обязательного признака автора карточка предлагает проследить отношения частей: объём букета, устойчивость сосуда и направление плодовой группы. Это учебные ориентиры для сравнения.'],
'Одна композиция позволяет обсуждать культурный обмен и переход между этапами творчества, не сводя живопись к изолированной национальной школе.',
['Фрукты: выдели основную группу.','Цветы: сравни её с растительной массой.','Сосуд: найди композиционную опору.','Масштаб: сопоставь разные предметы.','Кисть: проверь, как написаны соседние поверхности.'],
'Полотно подписано, но не датировано. Около 1675 — стилистическое заключение, не год на холсте. Сохраняем музейные даты жизни 1631–1697; не переносим ошибочную дату смерти 1673 из справочного абзаца Прадо о Бельведере. Абрахама не смешиваем с другими Брейгелями.',
'boijmans:1096-OK','Фрукты и цветы','Fruit and Flowers','около 1675','Масло на холсте; 74,9 × 97,3 см','Музей Бойманса — ван Бёнингена, Роттердам','https://www.boijmans.nl/en/collection/artworks/1589',
'Сначала отдели плоды, цветы и сосуд, затем проследи их связи. Какие переходы объединяют разные материалы в одно пространственное целое?');
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

