/* artists-batch-89.js */
(()=>{'use strict';
const B={};
function add(id,name,latin,life,aliases,tag,bio,technique,innovation,features,caution,key,title,originalTitle,date,medium,museum,source,look){B[id]={name,latin,life,aliases:[name,latin,...aliases],tag,bio,technique,innovation,features,caution,sources:[[museum+': '+title,source]],works:[],pendingWorks:[{key,title,originalTitle,date,medium,museum,source,look,reason:'Музейный оригинал установлен; конкретный свободный файл репродукции и права на него не проверены.'}],editorialStatus:'text_only_image_file_and_rights_pending'};}
add('bernardo_strozzi','Бернардо Строцци','Bernardo Strozzi','1581–1644',[],'Генуя и Венеция · цвет и свободная кисть',
['Строцци происходил из Генуи, а последние годы провёл в Венеции. Выбранная «Аллегория Славы» относится к позднему периоду, поэтому её нельзя считать неизменной формулой всей его живописи.','Крылья и музыкальные инструменты помогают узнать Славу. Художник соединяет её атрибуты с ярким цветовым решением и виртуозно написанной одеждой.'],
['Масло на холсте; 106,7 × 151,7 см. Жёлтая юбка, красный лиф и белая рубашка выделены на тёмном пейзажном фоне.','Свободная кисть особенно заметна в юбке и рубашке. В одной руке золотая труба, в другой деревянный шалмей, предшественник гобоя: это не две одинаковые трубы.'],
'Смысл аллегории объясняют атрибуты, но её зрительная сила создаётся отношениями цвета и характером мазка. Узнавание сюжета не заменяет рассматривание живописи.',
['Жёлтая юбка: рассмотри движение кисти.','Красный лиф: сравни цветовой акцент.','Белая рубашка: проследи свободные мазки.','Инструменты: отличи трубу от шалмея.','Тёмный фон: оцени силу цветового контраста.'],
'Вероятно 1635–1636 — музейная датировка. Наддверное назначение предполагается по формату и точке зрения; заказчик неизвестен. Ранее работу ошибочно приписывали Тьеполо. Принадлежность Гонзага вероятна, а в провенансе 1933–1945 остаются пробелы.',
'ng:NG6321','Аллегория Славы','A Personification of Fame','вероятно 1635–1636','Масло на холсте; 106,7 × 151,7 см','Национальная галерея, Лондон','https://www.nationalgallery.org.uk/paintings/bernardo-strozzi-a-personification-of-fame',
'Отдели атрибуты Славы от способов письма. Как меняется впечатление, когда ты сравниваешь не символы, а жёлтое, красное, белое и тёмный фон?');
add('giovanni_benedetto_castiglione','Джованни Бенедетто Кастильоне','Giovanni Benedetto Castiglione','1609–1664',['Иль Грекетто','Il Grechetto'],'Генуя · экспериментальная кисть в религиозной картине',
['Кастильоне перерабатывал впечатления от ван Дейка, Рубенса и Рембрандта в собственные приёмы рисунка и живописи. Выбранное крупное полотно показывает его эксперименты внутри религиозного образа.','Франциск стоит на скалистом выступе на фоне вечернего неба и обращён к скульптурному распятию. Череп и раскрытая книга образуют самостоятельную предметную группу.'],
['Масло на холсте; 195,6 × 135,3 см. Короткие повторяющиеся диагональные мазки строят одежду святого.','Густое импасто придаёт черепу и раскрытой книге осязаемую материальность. Музей сопоставляет молитвенное состояние святого с предметами, напоминающими о смертности и суете мира.'],
'Один холст объединяет разные способы работы кисти: повторяющийся мазок в одежде и плотную материальность натюрморта. Эксперимент служит не только эффекту, но и противопоставлению духовного состояния и вещей.',
['Одежда: найди повторяющиеся диагонали.','Книга: рассмотри плотность краски.','Череп: сравни форму и поверхность.','Распятие: определи предмет внимания святого.','Вечернее небо: оцени роль силуэта.'],
'Около 1650 — приблизительная дата. Это масло на холсте, не офорт, монотипия или масляный рисунок на бумаге. Иль Грекетто — прозвище того же художника. Символическое толкование книги и черепа приводится по музею.',
'met:2014.270','Святой Франциск в экстазе','Saint Francis in Ecstasy','около 1650','Масло на холсте; 195,6 × 135,3 см','Метрополитен-музей, Нью-Йорк','https://www.metmuseum.org/art/collection/search/647338',
'Сравни диагональный мазок в одежде с импасто книги и черепа. Как смена фактуры помогает различить состояние фигуры и предметный мир?');
add('valerio_castello','Валерио Кастелло','Valerio Castello','1624–1659',[],'Генуя · прозрачность покрывала и материнский жест',
['Генуэзский музей связывает поиски Кастелло с Корреджо, Пармиджанино, Веронезе, Рубенсом, ван Дейком и другими мастерами. Такие ориентиры обозначают художественные модели, а не документированное обучение у каждого из них.','В «Мадонне с покрывалом» Мария накрывает спящего Младенца, стараясь не нарушить его сон. Мягкие пастельные оттенки и подвижная кисть поддерживают интимный характер сцены.'],
['Масло на холсте. Прозрачные слои передают лёгкость покрывала и простыней, более плотные — красную драпировку и одежду Марии.','Удлинённый профиль, тонкие пальцы и изящество движения музей сопоставляет с Пармиджанино; композиционные решения соотносятся также с ван Дейком и переработаны самостоятельно.'],
'Движение может быть едва заметным и всё же организовать картину. Разная плотность письма помогает сделать покрывало лёгким, а осторожный жест — смысловым центром.',
['Покрывало: найди прозрачные слои.','Простыня: сравни лёгкие поверхности.','Красная драпировка: отметь более плотное письмо.','Пальцы: проследи осторожность движения.','Спящий Младенец: сопоставь покой и жест матери.'],
'Около 1650–1655 — каталожный интервал. Размер не уточняется в этой карточке. Не смешиваем Валерио с Бернардо Кастелло. Вместо прежнего кандидата «Христос и сотник» выбран подтверждённый живописный оригинал PB 2877; сведения того кандидата сюда не перенесены.',
'genova:PB2877','Мадонна с покрывалом','Madonna del velo','около 1650–1655','Масло на холсте; размеры здесь не уточняются','Musei di Strada Nuova, палаццо Бьянко, Генуя','https://www.museidigenova.it/en/madonna-veil-about-1650-1655',
'Сравни прозрачность покрывала с плотностью красной ткани. Как различия краски поддерживают осторожное движение, не превращая его в бурный жест?');
add('gregorio_de_ferrari','Грегорио де Феррари','Gregorio de Ferrari','1647–1726',["Gregorio de’ Ferrari"],'Генуя · барочная диагональ и мягкий колорит',
['Выбранное «Не прикасайся ко Мне» показывает встречу воскресшего Христа и Марии Магдалины у гробницы. Музей отмечает превращение торжественного религиозного сюжета в более изящную и чувственную встречу.','С полотном связана парная композиция «Товия и ангел», исполненная Лоренцо, сыном Грегорио. Парность не означает одинакового авторства обеих картин.'],
['Масло на холсте; 130 × 100 см. Поза Христа согласована с диагональным направлением композиции, а жест его руки отвечает руке Магдалины.','Плотная драпировка её платья сопоставлена с воздушным плащом Христа. Мягкая моделировка и пастельные оттенки пейзажа связаны в музейном описании с примером Корреджо.'],
'Движение возникает в ответных жестах и перекличке тканей, а не только в перемещении фигур. Мягкий колорит меняет эмоциональное прочтение традиционного сюжета.',
['Диагональ: проследи направление композиции.','Руки: сопоставь ответные жесты.','Платье: рассмотри плотные складки.','Плащ: сравни воздушность ткани.','Пейзаж: найди мягкие пастельные отношения.'],
'Около 1690 — стилистическая датировка музейной записи, не точный год подписи. Светское или галантное прочтение — музейная интерпретация. PB 1619 не смешиваем с парным полотном Лоренцо. Указание на предвосхищение рококо не превращает всю живопись Грегорио в единый позднейший стиль.',
'genova:PB1619','Не прикасайся ко Мне','Noli me tangere','около 1690','Масло на холсте; 130 × 100 см','Musei di Strada Nuova, Генуя','https://www.museidigenova.it/en/noli-me-tangere',
'Проследи связь двух рук, затем сравни ткани. Как диагональ и разница фактур соединяют движение навстречу и отказ от объятия?');
add('alessandro_magnasco','Алессандро Маньяско','Alessandro Magnasco','1667–1749',[],'Генуя и Флоренция · эстетика законченного эскиза',
['В «Ручной сороке» люди собираются среди живописных руин вокруг мужчины, пытающегося научить птицу петь. Музей подчёркивает необычный, театральный характер сцены.','Картина, вероятно, написана во время работы Маньяско для Медичи во Флоренции. В это время его палитра и техника были созвучны поискам Себастьяно Риччи.'],
['Масло на холсте; 63,5 × 74,9 см. Лёгкое прикосновение кисти сохраняет эскизную подвижность в завершённом произведении.','Музей связывает такую манеру с интересом художников и коллекционеров к эстетике наброска. Быстрое письмо не служит доказательством незавершённости.'],
'Эскизность становится сознательным качеством законченной картины. Наблюдение за небольшим действием соединяет театральный сюжет с живописной подвижностью.',
['Сорока: найди центр небольшого действия.','Мужчина: сопоставь занятие и позу.','Зрители: проследи группу наблюдающих.','Руины: оцени сценическую рамку.','Кисть: сравни лёгкость письма с завершённостью целого.'],
'Около 1707–1708 — музейная дата, уже XVIII век. Флорентийское исполнение вероятно, не документировано в приведённой записи. Театральность не означает изображение конкретного спектакля. Оценка попытки научить птицу петь принадлежит музейному описанию, не орнитологическому исследованию.',
'met:1984.191','Ручная сорока','The Tame Magpie','около 1707–1708','Масло на холсте; 63,5 × 74,9 см','Метрополитен-музей, Нью-Йорк','https://www.metmuseum.org/art/collection/search/436935',
'Сравни лёгкое письмо и организацию группы. Какие признаки целостной композиции мешают принять эту законченную работу за случайный незавершённый набросок?');
B.valerio_castello.sources.push(['Генуэзский каталог: датировка и инвентарь PB 2877','https://catalogo.museidigenova.it/oggetti/196922-madonna-del-velo?i=52']);
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

;
/* artists-batch-90.js */
(()=>{'use strict';
const B={},G='https://www.museidigenova.it/it/';
function add(id,name,latin,life,tag,bio,technique,innovation,features,caution,key,title,originalTitle,date,medium,museum,source,look){B[id]={name,latin,life,tag,aliases:[name,latin],bio,technique,innovation,features,caution,sources:[[museum+': '+title,source]],works:[],pendingWorks:[{key,title,originalTitle,date,medium,museum,source,look,reason:'Музейная запись установлена; конкретный свободный файл репродукции и права на него не проверены.'}],editorialStatus:'text_only_image_file_and_rights_pending'};}
add('giovanni_andrea_de_ferrari','Джованни Андреа де Феррари','Giovanni Andrea De Ferrari','1598–1669','Генуя · цвет и политическая аллегория',
['«Правосудие» и «Умеренность» де Феррари входили в цикл кардинальных добродетелей для личной комнаты дожа в Палаццо Дукале. Другие части написали Андреа Ансальдо и Доменико Фьязелла.','Музей связывает заказ цикла с третьим и четвёртым десятилетиями XVII века. Обычно аллегории хранятся в Sala Giunta Vecchia Палаццо Дориа-Турси; временный показ в 2026 году не меняет их происхождение.'],
['Масло на холсте; 270 × 172 см. Большой вертикальный формат позволяет обсуждать соотношение фигуры и пространства в аллегорической картине.','Вместо догадки о непроверенных атрибутах предлагается сравнить цветовые группы, свет, жесты и устройство композиции. Учебные вопросы не подменяют подробного музейного разбора.'],
'Добродетель становится частью политического ансамбля. Смысл отдельной картины раскрывается через её отношения с соседними аллегориями и назначение комнаты.',
['Фигура: найди главный центр внимания.','Цвет: сравни крупные группы.','Свет: проследи выделенные участки.','Жест: проверь его роль в композиции.','Вертикальный формат: оцени распределение пространства.'],
'1620–1630-е относятся к заказу цикла, не являются точным годом на выбранном холсте. Не приписываем все четыре картины де Феррари. Не смешиваем его с Орацио и Грегорио де Феррари. Инвентарный номер не установлен; ключ редакционный.',
'editorial:genova-giovanni-andrea-giustizia','Аллегория Правосудия','Allegoria della giustizia','1620–1630-е; интервал заказа цикла','Масло на холсте; 270 × 172 см','Муниципальное собрание Генуи, Палаццо Дориа-Турси',G+'allegoria-della-giustizia',
'Сравни цвет, свет и жест, затем вспомни другие добродетели цикла. Чем меняется смысл картины, когда её рассматривают как часть оформления покоев дожа?');
add('gioacchino_assereto','Джоаккино Ассерето','Gioacchino Assereto','1600–1649','Генуя · тихий драматизм светотени',
['«Исав продаёт первородство» музей относит примерно к 1640 году. В прошлом столетии картина находилась в сакристии генуэзской церкви Аннунциата-дель-Вастато.','В поздней живописи Ассерето музей отмечает более спокойные позы и новую интимность, соединённую с обдуманной монументальностью. Выбранная работа помогает увидеть развитие манеры, а не один неизменный рецепт.'],
['Масло на холсте; 98 × 124 см. Сцена частично возникает из глубокой тени; коричневый тон проникает в цвета фигур.','Освещение в музейном описании названо внутренним, а не исходящим из определённого естественного или искусственного источника. Спокойные позы заменяют чрезмерное выразительное напряжение.'],
'Драматизм может быть сосредоточенным и тихим. Тень, сдержанная поза и ясность группы создают напряжение без бурного движения.',
['Тёмный фон: найди границу видимого.','Коричневый тон: проследи его в цветах.','Позы: оцени спокойствие участников.','Свет: проверь, можно ли указать источник.','Группа: сопоставь интимность и монументальность.'],
'Около 1640 — музейная датировка, не прочитанная подпись. Внутренний свет — аналитическая формулировка, не утверждение о сверхъестественном свечении. Не переносим описание позднего примера на все произведения художника. Ключ редакционный.',
'editorial:genova-assereto-esau','Исав продаёт первородство','Esaù vende la primogenitura','около 1640','Масло на холсте; 98 × 124 см','Musei di Genova, Генуя',G+'esau-vende-la-primogenitura',
'Найди участки, где цвет почти растворяется в коричневой тени. Как спокойствие поз меняет ощущение важности происходящего?');
add('orazio_de_ferrari','Орацио де Феррари','Orazio De Ferrari','1606–1657','Генуя · полукруг фигур и ясный центр',
['Орацио был учеником Андреа Ансальдо. В его работах музей отмечает также влияние ван Дейка, Рубенса и Рени; влияние не означает обучения у каждого из этих мастеров.','«Христос и женщина, обвинённая в прелюбодеянии» создана в 1650 году и приобретена в 1959-м. Музей относит её к зрелым произведениям, где средний или большой формат соответствует повествовательным задачам автора.'],
['Масло на холсте; 147 × 186 см. Христос и женщина находятся в центре, остальные участники расположены вокруг полукругом.','Яркие светлые цвета помогают прочитать группу. Архитектурное основание справа, показанное в ракурсе, измеряет глубину пространства.'],
'Сложный эпизод становится читаемым благодаря пространственной организации: центр удерживает смысл, полукруг распределяет участников, архитектурная деталь уточняет глубину.',
['Центр: выдели Христа и женщину.','Полукруг: проследи порядок фигур.','Цвета: сравни светлые акценты.','Основание справа: рассмотри ракурс.','Глубина: сопоставь людей и архитектуру.'],
'1650 — музейная дата. Происхождение картины до приобретения в 1959 году неизвестно; не достраиваем провенанс. Орацио — самостоятельный художник, не вариант имени Джованни Андреа или Грегорио. Ключ редакционный.',
'editorial:genova-orazio-cristo-adultera','Христос и женщина, обвинённая в прелюбодеянии','Cristo e l’adultera','1650','Масло на холсте; 147 × 186 см','Musei di Strada Nuova, Генуя',G+'cristo-e-ladultera',
'Проследи полукруг участников и найди архитектурное основание справа. Как эти два решения соединяют ясный центр и убедительную глубину?');
add('sinibaldo_scorza','Синибальдо Скорца','Sinibaldo Scorza','1589–1631','Генуя · живая природа и тонкий мазок',
['Скорца родился в Вольтаджо и работал в Генуе. Он внимательно изучал животных: иногда включал их в религиозные или мифологические композиции, а иногда делал единственным сюжетом.','«Два голубя и дрозд» — маленькое тондо из Musei di Strada Nuova. Музей сопоставляет его наблюдательность с ломбардским натурализмом и с реалистическими рисунками автора.'],
['Масло на холсте; диаметр 21 см. Три птицы переданы тонкими аккуратными мазками, отмечающими мельчайшие светотеневые переходы.','Приглушённые коричневые, серые и белые оттенки требуют близкого рассматривания. Малый круглый формат делает различия соседних тонов важнее внешней сюжетной сложности.'],
'Небольшая группа живых существ может стать самостоятельным содержанием картины. Наблюдение проявляется в различиях тонов и поверхностей, а не только в узнаваемости вида.',
['Три птицы: отдели каждого участника.','Коричневое: найди тонкие переходы.','Серое: сравни соседние оттенки.','Белое: проследи светотень.','Круглый формат: оцени собранность группы.'],
'Точная дата не указана; используем общий период деятельности, не выдуманный год. Фотографическая точность — современная музейная метафора, не технология XVII века. Не противопоставляем всю фламандскую живопись живой природе. Ключ редакционный.',
'editorial:genova-scorza-due-piccioni-tordo','Два голубя и дрозд','Due piccioni con un tordo','первая треть XVII века; точный год не указан','Масло на холсте; тондо, диаметр 21 см','Musei di Strada Nuova, Генуя',G+'due-piccioni-con-un-tordo',
'Сравни коричневые, серые и белые участки. Какие небольшие различия света делают птиц объёмными, хотя общая гамма остаётся приглушённой?');
add('domenico_piola','Доменико Пиола','Domenico Piola','1627–1703','Генуя · фреска и иллюзионистическое пространство',
['В 1687–1688 годах Пиола расписал своды двух восточных комнат второго парадного этажа Палаццо Россо. Даты подтверждены окончательными выплатами. Его опыт поездки в Парму и общение с зятем Грегорио де Феррари помогли обновить отношения живописи и архитектуры.','Зима необычно молода и одета в светлое; она греется у жаровни. Вокруг разворачиваются ветры, карнавал, охота, пиршества, музыка и игры. Это ансамбль свода, а не отдельная станковая картина.'],
['Фресковая роспись свода. Лёгкий цвет, открытое пространство и вращательная организация связывают группы фигур. Общий размер здесь не уточняется.','Написанная балюстрада едва сдерживает действие по краям. Эффект усиливают перспективные декорации, штукатурный декор и настенные архитектурные иллюзии.'],
'Живопись продолжает архитектуру и включает зрителя в пространственное событие над головой. Смысл создаётся не только фигурами, но и взаимодействием свода, стен и декора.',
['Жаровня: найди молодую Зиму.','Ветры: проследи переплетение тел.','Края свода: различи карнавальные и охотничьи мотивы.','Балюстрада: сравни написанную преграду и движение.','Перспектива: оцени связь живописи и комнаты.'],
'Не приписываем Пиоле всё оформление: Джакомо Муттоне отвечал за штукатурный декор, Стефано Монки участвовал как квадратурист, настенные перспективы связаны с Никколо Кодацци. Фигура за Зимой определяется как Март или Фавоний. Источник показывает деталь свода; она не является отдельным оригиналом. Ключ редакционный для росписи.',
'editorial:genova-piola-inverno-vault','Аллегория Зимы — роспись свода','Allegoria dell’Inverno','1687–1688','Фресковая роспись свода; общий размер не уточняется','Musei di Strada Nuova, Палаццо Россо, Генуя',G+'allegoria-dellinverno-particolare-della-volta',
'Сопоставь молодую Зиму у жаровни с бурными ветрами и краями композиции. Почему фотографическая деталь не позволяет полностью оценить действие росписи в комнате?');
B.giovanni_andrea_de_ferrari.sources.push(['Музей: заказ цикла добродетелей и первоначальное назначение',G+'giovanni-andrea-de-ferrari-restituito-dipinti-e-disegni-inediti-intorno-alla-pala-di-san-nicolosio']);
B.domenico_piola.pendingWorks[0].collaborators=[{name:'Джакомо Муттоне',role:'Штукатурный декор ансамбля'},{name:'Стефано Монки',role:'Архитектурная перспективная живопись ансамбля'},{name:'Никколо Кодацци',role:'Настенные иллюзионистические перспективы'}];
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

;
/* artists-batch-91.js */
(()=>{'use strict';
const B={},G='https://www.museidigenova.it/it/';
function add(id,name,latin,life,aliases,tag,bio,technique,innovation,features,caution,key,title,originalTitle,date,medium,museum,source,look){B[id]={name,latin,life,aliases:[name,latin,...aliases],tag,bio,technique,innovation,features,caution,sources:[[museum+': '+title,source]],works:[],pendingWorks:[{key,title,originalTitle,date,medium,museum,source,look,reason:'Музейная запись установлена; конкретный свободный файл репродукции и права на него не проверены.'}],editorialStatus:'text_only_image_file_and_rights_pending'};}
add('luca_cambiaso','Лука Камбьязо','Luca Cambiaso','1527–1585',[],'Генуя · ночная сцена XVI века',
['«Христос перед Каиафой» относится к поздней живописи Камбьязо. Полотно происходит из римского собрания Винченцо Джустиниани и хранится в Музее Лигурийской академии изящных искусств.','Музей рассматривает его как выдающийся пример живописи при свечном освещении, распространившейся во второй половине XVI века. Свет усиливает драматизм сцены и позволяет сопоставить её с последующими европейскими поисками.'],
['Масло на холсте; 188 × 138 см. Ночное освещение помогает исследовать границы видимого, световые акценты и отношения фигуры с окружающей тенью.','Учебная задача — проследить, как свет организует встречу и направляет внимание. Конкретные выводы о расположении свечи и отдельных жестах не подменяем догадками.'],
'Сравнение показывает, что сильная светотень существовала до караваджизма. Сходство выразительного средства не означает тождества художественных задач и исторического направления.',
['Свет: выдели основные акценты.','Тень: найди границы видимости.','Фигуры: сравни степень освещённости.','Группа: проследи направление внимания.','Ночная сцена: сопоставь драматизм и читаемость.'],
'Около 1575 — приблизительная музейная дата, не XVII век. Оценка «величайший итальянский ноктюрн XVI века» — приведённое музеем суждение, не объективный рейтинг. Не называем картину караваджистской только из-за света. Инвентарный номер не установлен; ключ редакционный.',
'editorial:cambiaso-christ-caiaphas-genoa','Христос перед Каиафой','Christ before Caiaphas','около 1575','Масло на холсте; 188 × 138 см','Музей Лигурийской академии изящных искусств, Генуя','https://www.museidigenova.it/en/luca-cambiaso-christ-caiaphas',
'Проследи световые акценты и тёмные промежутки. Как свет организует драму? Почему одного сходства светотени недостаточно, чтобы отнести произведения к одному направлению?');
add('andrea_semino','Андреа Семино','Andrea Semino','1525–1595',[],'Генуя · мифологический сюжет и малый формат',
['Музейная страница подтверждает авторство Семино, название «Парнас», технику и размеры. Дата и развёрнутое описание в доступной записи отсутствуют.','Карточка предлагает учебное сравнение масштаба: мифологический сюжет помещён в небольшой горизонтальный холст, а не в монументальную роспись. Это основа для вопросов, не реконструкция первоначального заказа.'],
['Масло на холсте; 55 × 80 см. Горизонтальный формат и небольшой размер — проверенные свойства выбранного произведения.','При рассматривании предлагается выделить группы, направление внимания, цветовые отношения и границы пространства. Пока изображение не проверено, это вопросы для наблюдения, а не утверждения о конкретных деталях.'],
'Учебный ракурс — сопоставление масштаба и назначения: одна тема может решаться на небольшом холсте иначе, чем в декоративном ансамбле. Само назначение этого полотна пока неизвестно.',
['Группы: попробуй разделить участников.','Внимание: проследи связи внутри сцены.','Цвет: сравни крупные отношения.','Пространство: найди границы планов.','Формат: оцени горизонтальную организацию.'],
'Точный год не установлен. Перечень персонажей, сюжетные подробности, колорит и связь с определённой фреской не подтверждены доступной записью. Не называем холст подготовительным этюдом без источника. Номер неизвестен; ключ редакционный.',
'editorial:genova-semino-parnaso','Парнас','Parnaso','XVI век; точный год не установлен','Масло на холсте; 55 × 80 см','Musei di Genova, Генуя',G+'parnaso',
'Проверь, как организован небольшой горизонтальный холст. Отделяй видимые связи фигур от предположений о персонажах и первоначальном назначении.');
add('giovanni_battista_paggi','Джованни Баттиста Паджи','Giovanni Battista Paggi','1554–1627',['Giovan Battista Paggi'],'Генуя и Флоренция · цвет в тени и полутоне',
['Паджи почти двадцать лет работал во Флоренции и вернулся в Геную в 1599 году. Музей связывает его роль в обновлении местной живописи с переливчатым цветом и тонкими светотеневыми переходами.','«Бичевание» Палаццо Бьянко подписано и датировано на основании колонны справа внизу. Тосканские впечатления здесь соединены с возвращением к композиционным и фигурным решениям Камбьязо.'],
['Масло на холсте; 146 × 114 см. Музей выделяет тонкую передачу набедренной ткани Христа и характерный взмах одежды фигуры справа.','Фигуры второго плана написаны мягко и атмосферно. Цвет сохраняет насыщенность в тенях и полутенях благодаря рефлексам и контровому свету.'],
'Тень не только уменьшает яркость: она остаётся цветной. Сопоставление планов и тканей помогает увидеть соединение тосканского колорита с генуэзской композиционной традицией.',
['Ткань: рассмотри тонкость описания.','Одежда справа: проследи движение.','Второй план: найди мягкие переходы.','Тени: сравни их цвет.','Полутона: отдели рефлекс от прямого света.'],
'Подпись «G Batt . Paggi . 1615» подтверждает 1615, хотя заголовок страницы говорит «около 1615». Версия 1591 года из Палаццо Спинола — другое полотно. Первоначальное назначение выбранной работы неизвестно. Художественная поддержка Камбьязо не равна установленному формальному ученичеству. Ключ редакционный.',
'editorial:genova-paggi-flagellazione-1615','Бичевание Христа','Flagellazione di Cristo','1615; подписано и датировано','Масло на холсте; 146 × 114 см','Musei di Strada Nuova, Палаццо Бьянко, Генуя',G+'flagellazione-di-cristo-circa-1615',
'Сравни цвет теней, мягкость второго плана и ткань первого. Где затемнение сохраняет цвет, а не становится просто чёрным?');
add('bernardo_castello','Бернардо Кастелло','Bernardo Castello','1557–1629',[],'Генуя · группа Мадонны и святых',
['Музейная запись подтверждает Бернардо Кастелло как автора «Мадонны с Младенцем и святыми Иоанном Крестителем и Георгием». На полотне указан 1626 год.','Предлагается сравнить эту композиционную задачу с «Мадонной с покрывалом» Валерио Кастелло: здесь группа Мадонны и святых, там камерный материнский жест. Это учебное сопоставление, не смешение авторства.'],
['Масло на холсте; 173 × 149 см. Вертикальный формат даёт проверенную основу для анализа размещения фигуры Мадонны, Младенца и святых.','Направления взглядов, жесты, цветовые группы и планы предлагаются как вопросы для рассматривания. Доступная страница не содержит подробного технического анализа.'],
'Учебный ракурс — сопоставление разных способов организации религиозной группы. Имя художника и название сюжета ещё не объясняют композиционного решения.',
['Мадонна и Младенец: найди главную группу.','Святые: выдели остальных участников.','Взгляды: проверь связи фигур.','Жесты: сравни направления.','Формат: оцени распределение по вертикали.'],
'1626 подтверждён музейным указанием на дату картины. Первоначальное назначение и конкретный алтарь не установлены. Бернардо и Валерио Кастелло — разные художники; признаки выбранной работы Валерио сюда не переносим. Инвентарный номер не установлен; ключ редакционный.',
'editorial:genova-bernardo-castello-madonna-saints-1626','Мадонна с Младенцем и святыми Иоанном Крестителем и Георгием','Madonna col Bambino fra i SS. Giovanni Battista, Giorgio','1626','Масло на холсте; 173 × 149 см','Musei di Strada Nuova, Генуя',G+'madonna-col-bambino-fra-i-ss-giovanni-battista-giorgio',
'Сравни главную группу и святых. Какие видимые отношения связывают участников? Не заменяй наблюдение предположением о неизвестном первоначальном алтаре.');
add('domenico_fiasella','Доменико Фьязелла','Domenico Fiasella','1589–1669',['Иль Сарцана','Il Sarzana'],'Генуя · самообладание и повествовательный контраст',
['Фьязелла учился у Аурелио Ломи и Паджи, в 1607–1615 годах работал в Риме. Вернувшись в Геную, соединял позднеманьеристическую традицию, тосканский свет и караваджистские поиски.','В выбранной картине философ сидит с весами в равновесии. Трое учеников тщетно привлекают его внимание к горящему городу вдали; слева правитель указывает на противоположную группу.'],
['Масло на холсте; 153 × 189 см. Сдержанное построение формы соединено с повествовательным расположением фигур и живым взаимодействием цвета и света.','Надпись «Mediis Tranquillus In Undis» на основании позади философа объясняет контраст: мудрец сохраняет самообладание перед самыми драматичными событиями.'],
'Состояние героя становится читаемым через противопоставления: уравновешенные весы и горящий город, спокойствие философа и обращения учеников. Надпись служит ключом к рассказу.',
['Весы: проверь равновесие чаш.','Ученики: проследи обращения к философу.','Правитель: найди указующий жест.','Город: сопоставь дальнюю катастрофу и передний план.','Надпись: свяжи текст с поведением героя.'],
'Заголовок музея даёт 1630–1635, описание шире говорит о 1630-х. Философ признан исследователями Анаксархом; это не подписанное имя модели. Заказчик и повод неизвестны. Буквальный перевод девиза «спокойный среди волн» не означает морской сюжет. Иль Сарцана — прозвище автора. Ключ редакционный.',
'editorial:genova-fiasella-anassarco','Невозмутимость Анаксарха','Impassibilità di Anassarco (Mediis tranquillus in undis)','1630–1635; в описании — 1630-е','Масло на холсте; 153 × 189 см','Musei di Strada Nuova, Генуя',G+'impassibilita-di-anassarco-mediis-tranquillus-undis-1630-1635',
'Сравни равновесие весов с горящим городом и жестами учеников. Как надпись помогает прочитать спокойствие как самообладание, а не отсутствие внимания?');
if(typeof window.registerPaintingArtists!=='function')throw Error('Painting artist registry unavailable');
window.registerPaintingArtists(B);
})();

